def cmd_status(options):
    targets = selected_addons(options)
    manifest = load_manifest()
    installed = installed_addons()
    boot = boot_file()
    content = boot.read_text(errors='replace') if boot.is_file() else ''
    patched = MARKER in content
    print('boot.lua   : %s (marker x%d, backup %s)'
          % ('patched' if patched else 'unpatched', content.count(MARKER),
             'present' if boot.with_name('boot.lua.sls-addons.original').is_file() else 'absent'))
    print('processes  : steam=%s lumen=%s'
          % (process_running('steam') or process_running('steamwebhelper'), process_running('lumen')))
    print_component_inventory()
    rows = plan(targets)
    print('%-9s %-22s %s' % ('add-on', 'file', 'state'))
    degraded = False
    for addon, label, source, dest, state in rows:
        print('%-9s %-22s %s' % (addon, label, state))
        if state == 'differs' and addon in installed:
            degraded = True
        if state == 'missing-source':
            degraded = True
        if state == 'new' and addon in installed:
            # The directory claims the add-on is present but an expected
            # file is missing: that is corruption, not a fresh install.
            degraded = True
    for name in targets:
        if name not in installed:
            print('note       : %s is not installed' % name)
    if installed and not patched:
        print('note       : add-ons are installed but boot.lua is not patched; '
              'run scripts/install-local.sh')
        degraded = True
    print('data       : %s' % ('present' if data_dir().is_dir() else 'absent'))
    print('manifest   : %d add-on(s) pinned from %s'
          % (len(manifest.get('addons', {})), ', '.join(
              sorted({entry.get('source_repo', '?') for entry in manifest.get('addons', {}).values()}))))
    if getattr(options, 'live', False):
        # Read-only probe of the running client; see 96_live_probe.py.
        try:
            degraded = print_live_status(targets, installed) or degraded
        except Exception as error:  # the probe must never turn status into a traceback
            print('live       : unavailable - %s' % error)
    return 1 if degraded else EXIT_OK


def write_install_snapshot():
    """Record what this installer put on disk, for the Health page.

    Versions and sources identify the release; file hashes let the Health
    page report drift without a checkout. The full pins stay in
    vendor/MANIFEST.json (and in `luna verify`).
    """
    manifest = load_manifest()
    files = {}
    for name in ADDONS:
        entry = (manifest.get('addons', {}).get(name) or {}).get('files', {})
        hashes = {}
        for rel, meta in entry.items():
            path = payload_path(name, meta.get('source_path', ''))
            try:
                hashes[rel] = sha256(path) if path.is_file() else ''
            except OSError:
                hashes[rel] = ''
        files[name] = hashes
    snapshot = {
        'generated': manifest.get('generated', ''),
        'installedAt': int(time.time()),
        'source': repo_revision(),
        'versions': {name: addon_version(name) for name in ADDONS},
        'sources': {name: str((manifest.get('addons', {}).get(name) or {})
                              .get('source_commit', ''))[:12] for name in ADDONS},
        'files': files,
    }
    path = addons_dir() / 'luna-manifest.json'
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(snapshot, indent=2, sort_keys=True) + '\n')
    return path


def repo_revision():
    try:
        result = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', '--short', 'HEAD'],
                                capture_output=True, text=True)
        if result.returncode == 0:
            return result.stdout.strip()
    except OSError:
        pass
    return ''


ADDON_NAME_RE = re.compile(r'[a-z][a-z0-9_-]{0,31}')


def _unsafe_rel(rel):
    return (not isinstance(rel, str) or not rel or rel.startswith('/') or '\\' in rel or '\x00' in rel
            or any(part in ('', '.', '..') for part in rel.split('/')))


def _manifest_problems(manifest, root, require=()):
    """Payload bytes vs manifest pins, for a checkout or an extracted bundle.

    Walks the manifest's OWN add-ons (names strictly validated), so a bundle may drop an add-on;
    `require` names the add-ons that must be present (the release side asks for all of them)."""
    if not isinstance(manifest, dict) or not isinstance(manifest.get('addons'), dict):
        return ['the manifest is not an object with an "addons" object']
    problems = []
    addons = manifest['addons']
    for name in require:
        if name not in addons:
            problems.append('manifest has no entry for %s' % name)
    for name, entry in addons.items():
        if not isinstance(name, str) or not ADDON_NAME_RE.fullmatch(name):
            problems.append('the manifest has an invalid add-on name: %.40r' % (name,))
            continue
        if not isinstance(entry, dict) or not isinstance(entry.get('files', {}), dict):
            problems.append('manifest entry for add-on %s has the wrong shape' % name)
            continue
        for rel, meta in entry.get('files', {}).items():
            source = meta.get('source_path') if isinstance(meta, dict) else None
            if _unsafe_rel(source) or not isinstance(meta.get('sha256'), str):
                problems.append('manifest entry %s/%s has an unsafe path or no sha256' % (name, rel))
                continue
            path = root / 'addons' / name / source
            if not path.is_file():
                problems.append('missing payload %s/%s' % (name, rel))
                continue
            if sha256(path) != meta['sha256']:
                problems.append('payload %s/%s does not match the manifest' % (name, rel))
    shared = manifest.get('shared', {})
    if not isinstance(shared, dict):
        return problems + ['the manifest "shared" section is not an object']
    for rel, meta in shared.items():
        if _unsafe_rel(rel) or not isinstance(meta, dict) or not isinstance(meta.get('sha256'), str):
            problems.append('shared entry %.60r has an unsafe path or no sha256' % (rel,))
            continue
        path = root / rel
        if not path.is_file():
            problems.append('missing shared file %s' % rel)
        elif sha256(path) != meta['sha256']:
            problems.append('shared file %s does not match the manifest' % rel)
    return problems


RELEASE_LISTING = 'RELEASE-FILES.json'
RELEASE_FORMAT = 2


def _release_listing(entries):
    """{relative path: sha256} for every regular file the bundle will carry."""
    listing = {}
    for arcname, path in entries:
        files = sorted(p for p in path.rglob('*')) if path.is_dir() else [path]
        for item in files:
            if item.is_symlink():
                raise ValueError('refusing to release a symlink: %s' % item)
            if item.is_file():
                rel = arcname if not path.is_dir() else '%s/%s' % (arcname, item.relative_to(path).as_posix())
                listing[rel] = sha256(item)
    return listing


def cmd_release(options):
    """Build a bundle another machine can install with `luna update`."""
    manifest = load_manifest()  # fail early when the pins are missing
    problems = _manifest_problems(manifest, ROOT, require=ADDONS)
    if problems:
        print('REFUSING to release: the working tree does not match the manifest:')
        for problem in problems:
            print('  - %s' % problem)
        print('Run scripts/vendor-update.sh, then verify, before releasing.', file=sys.stderr)
        return 1
    warn_untraceable(manifest, sys.stderr)
    version = addon_version('luna')
    out_dir = Path(options.out).expanduser() if options.out else ROOT / 'dist'
    out_dir.mkdir(parents=True, exist_ok=True)
    name = 'luna-%s' % version
    bundle = out_dir / (name + '.tar.gz')
    entries = [
        ('addons', ROOT / 'addons'),
        ('vendor/MANIFEST.json', MANIFEST_PATH),
        ('scripts/luna.py', ROOT / 'scripts' / 'luna.py'),
        ('scripts/lumen-hook.py', ROOT / 'scripts' / 'lumen-hook.py'),
        ('scripts/steam-machine.py', ROOT / 'scripts' / 'steam-machine.py'),
        ('scripts/patch-lumen.py', PATCHER),
        ('bridge/bridge.lua', BRIDGE_SOURCE),
    ]
    readme = ROOT / 'README.md'
    if readme.is_file():
        entries.append(('README.md', readme))
    changelog = ROOT / 'CHANGELOG.md'
    if changelog.is_file():
        entries.append(('CHANGELOG.md', changelog))
    listing = _release_listing(entries)
    listing_bytes = (json.dumps({'format': RELEASE_FORMAT, 'files': listing},
                                indent=1, sort_keys=True) + '\n').encode()
    with tarfile.open(bundle, 'w:gz') as tar:
        for arcname, path in entries:
            tar.add(path, arcname='%s/%s' % (name, arcname), recursive=path.is_dir())
        info = tarfile.TarInfo('%s/%s' % (name, RELEASE_LISTING))
        info.size = len(listing_bytes)
        info.mode = 0o644
        info.mtime = int(time.time())
        tar.addfile(info, io.BytesIO(listing_bytes))
    digest = sha256(bundle)
    checksum = out_dir / (bundle.name + '.sha256')
    checksum.write_text('%s  %s\n' % (digest, bundle.name))
    print('bundle : %s' % bundle)
    print('sha256 : %s' % digest)
    sig_file = Path(str(bundle) + '.sig')
    if os.path.lexists(str(sig_file)):
        sig_file.unlink()  # a stale signature of an earlier build of this version must not linger
    signed = False
    if signing_key_path().is_file():
        fingerprint, sign_error = signing_sign(bundle)
        if sign_error:
            print('REFUSING to release: the bundle could not be signed: %s' % sign_error, file=sys.stderr)
            return 1
        signed = True
        print('signed : %s (%s)' % (fingerprint, sig_file.name))
    else:
        print('signed : NO (no release key at %s; the bundle is unsigned. Create one: luna signing init)'
              % signing_key_path())
    print('version: %s (%s)' % (version, ', '.join('%s %s' % (n, addon_version(n)) for n in ADDONS)))
    if options.publish:
        gh = shutil.which('gh')
        if not gh:
            print('gh CLI not found; publish manually: %s' % bundle, file=sys.stderr)
            return 1
        tag = 'v%s' % version
        view = subprocess.run([gh, 'release', 'view', tag], capture_output=True, text=True)
        assets = [str(bundle), str(checksum)] + ([str(sig_file)] if signed else [])
        if view.returncode == 0:
            args = [gh, 'release', 'upload', tag] + assets + ['--clobber']
        else:
            args = [gh, 'release', 'create', tag] + assets + [
                    '--title', 'Luna %s' % version,
                    '--notes', ('Luna %s: pinned payloads plus scripts/luna.py.\n\n'
                                'Install on another machine: `luna update --latest` (needs gh).'
                                % version)]
        result = subprocess.run(args, capture_output=True, text=True)
        if result.returncode != 0:
            print('gh failed: %s' % (result.stderr.strip() or result.stdout.strip()), file=sys.stderr)
            return 1
        print('published: %s' % tag)
    return EXIT_OK


URL_BUNDLE_MAX = 64 * 1024 * 1024   # a real bundle is ~165 KB
URL_SIDECAR_MAX = 4096              # one hex digest and a file name
URL_LOOPBACK = ('127.0.0.1', 'localhost', '::1')


class UrlRefused(Exception):
    """A URL or redirect the policy refuses (the message is printed as is)."""


class HttpsOnlyRedirect(urllib.request.HTTPRedirectHandler):
    """Follow redirects, but only to https: never file://, ftp:// or a downgrade to http://."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if urllib.parse.urlsplit(newurl).scheme.lower() != 'https':
            raise UrlRefused('REFUSING: the server redirected to a non-https address (%.80s); a redirect '
                             'may only lead to https' % newurl)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def url_check(url):
    """(ok, why) for the address given to --url: https, or http to this machine's loopback only."""
    try:
        parts = urllib.parse.urlsplit(url)
        host = parts.hostname
        parts.port  # noqa: B018 - raises ValueError on a malformed port
    except ValueError:
        return False, 'REFUSING: --url is not a valid address; it must be https'
    scheme = parts.scheme.lower()
    if '@' in parts.netloc or not host:
        return False, 'REFUSING: --url must be a plain https address without user:password@'
    if scheme == 'https' or (scheme == 'http' and host.lower() in URL_LOOPBACK):
        return True, ''
    return False, ('REFUSING: --url must be https (plain http is accepted only for 127.0.0.1/localhost, '
                   'for local testing); got %.60s' % url)


class _TooBig(Exception):
    pass


def url_download(url, dest, limit):
    """Stream `url` to `dest`, at most `limit` bytes. Returns (ok, why); on failure nothing is left."""
    ok, why = url_check(url)
    if not ok:
        return False, why
    opener = urllib.request.build_opener(HttpsOnlyRedirect)
    too_big = 'REFUSING: the download is larger than the %d byte limit' % limit
    try:
        with opener.open(url, timeout=60) as response:
            declared = response.headers.get('Content-Length', '')
            if declared.isdigit() and int(declared) > limit:
                raise _TooBig()
            written = 0
            with open(str(dest), 'wb') as out:
                while True:
                    block = response.read(65536)
                    if not block:
                        break
                    written += len(block)
                    if written > limit:
                        raise _TooBig()
                    out.write(block)
    except _TooBig:
        with contextlib.suppress(OSError):
            Path(dest).unlink()
        return False, too_big
    except UrlRefused as error:
        with contextlib.suppress(OSError):
            Path(dest).unlink()
        return False, str(error)
    except Exception as error:  # noqa: BLE001 - any network failure is a refusal to continue
        with contextlib.suppress(OSError):
            Path(dest).unlink()
        if isinstance(error, urllib.error.HTTPError) and 300 <= error.code < 400:
            # urllib itself declined to follow it (file://, ftp:// ...) before our handler saw it
            return False, 'REFUSING: the server sent a redirect that is not allowed (only https): %s' % error
        return False, 'download failed: %s' % error
    return True, ''


def _fetch_small(url, dest, limit):
    """Optional small file (.sig). Absent or unreachable counts as "no file"; an oversized one is
    stored as limit+1 bytes, which signing_read_sig refuses as implausibly large."""
    ok, why = url_download(url, dest, limit)
    if not ok and 'larger than' in why:
        Path(dest).write_bytes(b'x' * (limit + 1))
        return True
    return ok


def cmd_update(options):
    """Verify a released bundle and install it with the bundled script."""
    lock_path = _update_lock()
    acquired, reason = _acquire_lock(lock_path)
    if not acquired:
        print('REFUSING: %s' % reason, file=sys.stderr)
        return 1
    temp_dir = Path(tempfile.mkdtemp(prefix='luna-update-'))
    try:
        bundle = None
        if options.bundle:
            bundle = Path(options.bundle).expanduser()
        elif options.latest:
            tag, tag_error = latest_release()
            if not tag:
                print('gh release lookup failed: %s' % tag_error, file=sys.stderr)
                return 1
            bundle, error = download_release(tag, temp_dir)
            if bundle is None:
                print('gh release download failed: %s' % error, file=sys.stderr)
                return 1
        elif options.url:
            bundle = temp_dir / 'luna-bundle.tar.gz'
            ok, why = url_download(options.url, bundle, URL_BUNDLE_MAX)
            if not ok:
                print(why, file=sys.stderr)
                return EXIT_REFUSED if why.startswith('REFUSING') else 1
            sidecar = Path(str(bundle) + '.sha256')
            ok, why = url_download(options.url + '.sha256', sidecar, URL_SIDECAR_MAX)
            if not ok and (why.startswith('REFUSING') or 'larger than' in why):
                print('REFUSING: the checksum file (.sha256) beside the URL cannot be used: %s'
                      % why.replace('REFUSING: ', ''), file=sys.stderr)
                return EXIT_REFUSED
            if not sidecar.is_file():
                print('warning: no .sha256 beside the URL; only the bundle\'s own manifest can be '
                      'checked (self-consistency, not independent). Prefer --latest.', file=sys.stderr)
            # A missing, blocked or failed .sig is indistinguishable from "unsigned": the policy
            # in check_bundle_signature then refuses it wherever a trusted key is configured.
            _fetch_small(options.url + '.sig', str(bundle) + '.sig', SIG_MAX_BYTES)
        else:
            print('Point at a bundle: --bundle FILE, --url URL or --latest', file=sys.stderr)
            return 2
        return install_bundle(bundle, only=options.only, dry_run=options.dry_run,
                              allow_legacy=getattr(options, 'allow_legacy_bundle', False),
                              allow_unsigned=getattr(options, 'allow_unsigned', False),
                              allow_downgrade=getattr(options, 'allow_downgrade', False))
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)
        _release_lock(lock_path)


LUNA_REPO = 'pgm1207/Luna'
UPDATE_TTL = 6 * 3600


def gh_json(args):
    gh = find_gh()
    if not gh:
        return None, 'the gh CLI is not installed (update checks use your own GitHub auth)'
    try:
        result = subprocess.run([gh] + args, capture_output=True, text=True, timeout=GH_TIMEOUT)
    except subprocess.TimeoutExpired:
        return None, 'gh did not answer within %d seconds' % GH_TIMEOUT
    if result.returncode != 0:
        return None, (result.stderr.strip() or result.stdout.strip() or 'gh failed')
    try:
        return json.loads(result.stdout), ''
    except ValueError:
        return None, 'gh returned something that is not JSON'


def latest_release():
    data, error = gh_json(['release', 'view', '--json', 'tagName,assets', '-R', LUNA_REPO])
    if data is None:
        return '', error
    return str(data.get('tagName') or ''), ''


def check_updates(force=False):
    """Compare the installed version with the newest release; cached for 6h."""
    cache_path = luna_tools_dir() / 'update-check.json'
    cached = read_json_file(cache_path) or {}
    now = int(time.time())
    installed = installed_version()
    if (not force and cached.get('latest') and cached.get('checkedAt') and not cached.get('checkError')
            and now - int(cached['checkedAt']) < UPDATE_TTL):
        cached['installed'] = installed
        cached['available'] = version_key(cached.get('latest')) > version_key(installed)
        return cached
    latest, error = latest_release()
    if not latest and error:
        # A failed lookup keeps the last known release, so an offline check
        # does not hide an update that was already found.
        latest = str(cached.get('latest') or '')
    report = {
        'installed': installed,
        'latest': latest,
        'checkedAt': now,
        'checkError': error,
        'available': bool(latest) and version_key(latest) > version_key(installed),
    }
    write_json_file(cache_path, report)
    return report


def _safe_extract(bundle, extract_dir):
    """Unpack without allowing absolute paths or parent-directory escapes.

    A gzip bundle is first read to its end: tarfile stops at the tar end marker and never
    reaches the gzip CRC trailer, so a damaged stream that still decodes would otherwise
    extract silently. Members must be plain files or directories (no symlinks, hardlinks or
    devices) and names must be unique, so a later member cannot replace a verified one."""
    with open(str(bundle), 'rb') as probe:
        gzipped = probe.read(2) == b'\x1f\x8b'
    if gzipped:
        try:
            with gzip.open(str(bundle), 'rb') as stream:
                while stream.read(1024 * 1024):
                    pass
        except (OSError, EOFError, zlib.error) as error:
            raise ValueError('the bundle is corrupt (gzip stream check failed: %s)' % error) from error
    with tarfile.open(bundle) as tar:
        members = tar.getmembers()
        seen = set()
        for member in members:
            name = member.name
            if not name or name.startswith('/') or '..' in Path(name).parts:
                raise ValueError('REFUSING: unsafe path in bundle: %r' % name)
            if not (member.isfile() or member.isdir()):
                raise ValueError('REFUSING: bundle member %r is a link or special file' % name)
            key = Path(name).as_posix().rstrip('/')
            if key in seen:
                raise ValueError('REFUSING: duplicate bundle member %r' % name)
            seen.add(key)
        try:
            tar.extractall(extract_dir, filter='data')
        except TypeError:  # Python < 3.12 has no extraction filter
            tar.extractall(extract_dir)


def _listing_problems(root):
    """Check an extracted bundle against RELEASE-FILES.json, in both directions.

    Runs in the already-installed code before anything from the bundle executes. Returns
    (problems, listing_present)."""
    path = root / RELEASE_LISTING
    if not path.is_file():
        return [], False
    try:
        data = json.loads(path.read_text())
        if not isinstance(data, dict):
            raise ValueError('not a JSON object')
        files = data['files']
        if data.get('format') != RELEASE_FORMAT or not isinstance(files, dict):
            raise ValueError('unsupported format')
        if not all(isinstance(rel, str) and isinstance(digest, str) for rel, digest in files.items()):
            raise ValueError('paths and digests must be text')
    except (ValueError, KeyError, OSError, AttributeError, TypeError) as error:
        return ['%s is unreadable: %s' % (RELEASE_LISTING, error)], True
    problems = []
    for rel, digest in sorted(files.items()):
        if rel.startswith('/') or '..' in Path(rel).parts:
            problems.append('listed path is unsafe: %r' % rel)
            continue
        item = root / rel
        if item.is_symlink() or not item.is_file():
            problems.append('listed file is missing: %s' % rel)
        elif sha256(item) != digest:
            problems.append('%s does not match %s' % (rel, RELEASE_LISTING))
    for item in sorted(root.rglob('*')):
        rel = item.relative_to(root).as_posix()
        if item.is_symlink() or (item.is_file() and rel != RELEASE_LISTING and rel not in files):
            problems.append('unlisted file in the bundle: %s' % rel)
    return problems, True


def install_bundle(bundle, only=None, dry_run=False, allow_legacy=False, allow_unsigned=False,
                   allow_downgrade=False, expect_version=None):
    """Verify a bundle and run the installer inside it.

    The bundle is first copied into a private directory, and the checksum, the
    signature and the extraction all use that one copy, so the bytes that were
    verified are the bytes that get unpacked."""
    bundle = Path(bundle)
    if not bundle.is_file():
        print('bundle not found: %s' % bundle, file=sys.stderr)
        return 2
    with tempfile.TemporaryDirectory(prefix='luna-stage-') as stage:
        staged = Path(stage) / 'bundle.tar.gz'
        try:
            shutil.copyfile(str(bundle), str(staged))
        except OSError as error:
            print('REFUSING: cannot read the bundle: %s' % error, file=sys.stderr)
            return 1
        return _install_staged(bundle, staged, only, dry_run, allow_legacy, allow_unsigned,
                               allow_downgrade, expect_version)


def _install_staged(bundle, staged, only, dry_run, allow_legacy, allow_unsigned,
                    allow_downgrade=False, expect_version=None):
    checksum_file = Path(str(bundle) + '.sha256')
    if checksum_file.is_file():
        try:
            tokens = checksum_file.read_text().split()
        except (OSError, ValueError) as error:
            print('REFUSING: the checksum file %s cannot be read: %s' % (checksum_file.name, error),
                  file=sys.stderr)
            return 1
        expected = tokens[0].strip().lower() if tokens else ''
        if not re.fullmatch(r'[0-9a-f]{64}', expected):
            print('REFUSING: the checksum file %s is empty or does not start with a sha256 digest'
                  % checksum_file.name, file=sys.stderr)
            return 1
        actual = sha256(staged)
        if expected != actual:
            print('REFUSING: sha256 mismatch (bundle %s, sidecar %s)'
                  % (actual[:12], expected[:12]), file=sys.stderr)
            return 1
        print('sha256 : verified (%s)' % actual[:12])
    else:
        print('note   : no .sha256 beside the bundle: integrity is checked only against the bundle\'s '
              'own manifest (self-consistency), not an independent checksum')
    # Authenticity: decided by the INSTALLED code and the machine-local trust file, before unpacking.
    verdict = check_bundle_signature(staged, Path(str(bundle) + '.sig'), allow_unsigned)
    if verdict is None:
        return 1
    with tempfile.TemporaryDirectory(prefix='luna-bundle-') as work:
        extract_dir = Path(work) / 'unpacked'
        extract_dir.mkdir()
        try:
            _safe_extract(staged, extract_dir)
        except (tarfile.TarError, ValueError, OSError) as error:
            print('REFUSING: cannot safely unpack the bundle: %s' % error, file=sys.stderr)
            return 1
        roots = [entry for entry in extract_dir.iterdir() if entry.is_dir()]
        root = roots[0] if len(roots) == 1 else extract_dir
        script = root / 'scripts' / 'luna.py'
        if not script.is_file():
            print('REFUSING: the bundle does not contain scripts/luna.py', file=sys.stderr)
            return 1
        bundled_manifest = root / 'vendor' / 'MANIFEST.json'
        if not bundled_manifest.is_file():
            print('REFUSING: the bundle does not contain vendor/MANIFEST.json', file=sys.stderr)
            return 1
        try:
            manifest = json.loads(bundled_manifest.read_text())
        except (ValueError, OSError):
            print('REFUSING: the bundled manifest is not valid JSON', file=sys.stderr)
            return 1
        luna_entry = manifest.get('addons', {}).get('luna') if isinstance(manifest, dict) and \
            isinstance(manifest.get('addons'), dict) else None
        if not isinstance(luna_entry, dict):
            print('REFUSING: the bundled manifest has the wrong shape (no add-ons.luna entry)', file=sys.stderr)
            return 1
        version = luna_entry.get('plugin_version')
        if not isinstance(version, str) or not BUNDLE_VERSION_RE.fullmatch(version):
            print('REFUSING: the bundle version %.40r is not a plain x.y.z version' % (version,), file=sys.stderr)
            return 1
        problems = _manifest_problems(manifest, root)
        if problems:
            print('REFUSING: the bundle contents do not match its own manifest:', file=sys.stderr)
            for problem in problems:
                print('  - %s' % problem, file=sys.stderr)
            return 1
        listing_problems, listed = _listing_problems(root)
        if listing_problems:
            print('REFUSING: the bundle contents do not match its file list:', file=sys.stderr)
            for problem in listing_problems:
                print('  - %s' % problem, file=sys.stderr)
            return 1
        if not listed:
            # Old format: scripts/luna.py (which runs next) is not covered by any hash.
            if not allow_legacy:
                print('REFUSING: this bundle predates %s, so scripts/luna.py, which would run next, '
                      'is not verified. If you trust where it came from, repeat with '
                      '--allow-legacy-bundle.' % RELEASE_LISTING, file=sys.stderr)
                return 1
            print('WARNING: legacy bundle: scripts/luna.py is NOT covered by any hash; '
                  'continuing because --allow-legacy-bundle was given', file=sys.stderr)
        if expect_version is not None and version != expect_version:
            print('REFUSING: the bundle version %s does not match the release tag (%s); '
                  'a tag may only ship its own version' % (version, expect_version), file=sys.stderr)
            return 1
        if verdict['enforcing']:
            # Rollback protection: only while enforcing (an unauthenticated mark would be a denial-of-service lever).
            floor, floor_problem = update_floor_read()
            if floor_problem:
                print('REFUSING: the update state file is unusable: %s' % floor_problem, file=sys.stderr)
                return 1
            if floor is not None and version_tuple(version) < version_tuple(floor):
                if not allow_downgrade:
                    print('REFUSING: bundle version %s is older than %s, which this machine already installed '
                          'from a verified bundle (a rollback to a vulnerable release is the attack this '
                          'stops). To go back deliberately: --allow-downgrade' % (version, floor),
                          file=sys.stderr)
                    return 1
                print('WARNING: installing bundle version %s, older than the minimum %s; continuing because '
                      '--allow-downgrade was given (the minimum is not lowered)' % (version, floor),
                      file=sys.stderr)
        print('bundle : %s (Luna %s, manifest verified%s)'
              % (bundle.name, version, '' if listed else ', legacy: luna.py unverified'))
        # Add-on updates must not undo a deliberate client update from Health.
        command = [sys.executable, str(script), 'install', '--force']
        for name in only or []:
            command += ['--only', name]
        if dry_run:
            # Nothing from the bundle runs here: the plan comes from the installed code only.
            print('DRY RUN: verified bundle %s (Luna %s); a real update would run the bundled installer '
                  '`luna.py install --force%s`. Nothing from the bundle was executed and nothing was written.'
                  % (bundle.name, version, ''.join(' --only ' + name for name in only or [])))
            return EXIT_OK
        result = subprocess.run(command, env=dict(os.environ, LUNA_KEEP_STEAM_CLIENT='1'))
        if result.returncode == 0 and verdict['verified']:
            update_floor_raise(version)
        return result.returncode


def download_release(tag, work):
    """Fetch a release's bundle + checksum with the user's gh auth."""
    gh = find_gh()
    if not gh:
        return None, 'the gh CLI is not installed'
    if not tag:
        return None, 'no release tag to download'
    try:
        result = subprocess.run([gh, 'release', 'download', tag,
                                 '--pattern', 'luna-*.tar.gz',
                                 '--pattern', 'luna-*.tar.gz.sha256',
                                 '--pattern', 'luna-*.tar.gz.sig',
                                 '--dir', str(work), '--clobber', '-R', LUNA_REPO],
                                capture_output=True, text=True, timeout=GH_DOWNLOAD_TIMEOUT)
    except subprocess.TimeoutExpired:
        return None, 'the release download did not finish within %d seconds' % GH_DOWNLOAD_TIMEOUT
    if result.returncode != 0:
        return None, (result.stderr.strip() or result.stdout.strip() or 'download failed')
    found = sorted(work.glob('luna-*.tar.gz'))
    if not found:
        return None, 'the release has no bundle asset'
    bundle = found[-1]
    if not Path(str(bundle) + '.sha256').is_file():
        return None, 'the release has no checksum sidecar; refusing an unauthenticated bundle'
    return bundle, ''


def _update_lock():
    """Single-writer lock so timer, menu and shell never update concurrently."""
    tools = luna_tools_dir()
    try:
        tools.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass
    return tools / 'update.lock'


LOCK_TTL = 3600


_LOCK_FDS = {}


def _acquire_lock(lock_path):
    """Claim the update lock with flock(2) on a file that stays open for the whole update.

    The kernel drops the lock when the process dies, so a kill -9 can never wedge updates and a
    live holder can never be robbed (no pid guessing). Returns (True, '') or (False, reason).
    A lock file left by an older Luna (pid + time, no flock) is still honoured while its pid lives."""
    busy = 'another update is already running (%s)' % lock_path
    key = str(lock_path)
    if key in _LOCK_FDS:
        return False, busy
    try:
        import fcntl
    except ImportError:  # pragma: no cover - not POSIX
        return True, ''
    for _attempt in range(5):
        try:
            fd = os.open(key, os.O_CREAT | os.O_RDWR, 0o600)
        except OSError:
            return True, ''  # cannot create a lock here: do not block the update
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            os.close(fd)
            return False, busy
        try:
            same = os.fstat(fd).st_ino == os.stat(key).st_ino
        except OSError:
            same = False
        if not same:  # the file was replaced while we waited: lock the new one
            os.close(fd)
            continue
        try:
            owner, started = 0, 0
            try:
                info = json.loads(os.pread(fd, 4096, 0).decode('utf-8', 'replace') or '{}')
                owner, started = int(info.get('pid') or 0), int(info.get('at') or 0)
            except (ValueError, TypeError, AttributeError):
                pass
            if owner > 0 and owner != os.getpid() and time.time() - started < LOCK_TTL:
                try:
                    os.kill(owner, 0)
                    os.close(fd)
                    return False, busy
                except OSError:
                    pass
            os.ftruncate(fd, 0)
            os.pwrite(fd, json.dumps({'pid': os.getpid(), 'at': int(time.time())}).encode(), 0)
        except OSError:
            pass
        _LOCK_FDS[key] = fd
        return True, ''
    return False, busy


def _release_lock(lock_path):
    """Drop our lock. The file is removed only if it is still the one WE locked."""
    fd = _LOCK_FDS.pop(str(lock_path), None)
    if fd is None:
        return
    try:
        if os.fstat(fd).st_ino == os.stat(str(lock_path)).st_ino:
            lock_path.unlink()
    except OSError:
        pass
    finally:
        with contextlib.suppress(OSError):
            os.close(fd)


CLI_LAUNCHER = '''#!/bin/sh
# Managed by SLS Luna CLI v1
# Recovery remains available even if a base update replaces Lumen's tooling.
if [ "${1:-}" = hook ] && [ -f "$HOME/.local/share/slssteam-luna/lumen-hook.py" ]; then
    shift
    action="${1:-status}"
    case "$action" in on) action=enable;; off) action=disable;; esac
    [ "$#" -eq 0 ] || shift
    exec python3 "$HOME/.local/share/slssteam-luna/lumen-hook.py" "$action" "$@"
fi
exec python3 "$HOME/.local/share/Lumen/sls-luna/luna.py" "$@"
'''


def write_tooling():
    """Keep a standalone updater copy the timer can run without a checkout.

    Called both by the installer (from a checkout) and by the copy itself, so
    the source is *this* file, never a fixed path relative to it.
    """
    tools = luna_tools_dir()
    tools.mkdir(parents=True, exist_ok=True)
    target = tools / 'luna.py'
    source = Path(__file__).resolve()
    try:
        same = source.samefile(target)
    except OSError:
        same = False
    if not same:
        shutil.copy2(source, target)
        target.chmod(0o755)
    launcher = home() / '.local/bin/luna'
    if launcher.is_symlink() or (launcher.exists() and
                                (not launcher.is_file() or launcher.read_bytes() != CLI_LAUNCHER.encode())):
        print('WARNING: custom luna command preserved; use the installed Python tooling directly.', file=sys.stderr)
    elif not launcher.exists():
        launcher.parent.mkdir(parents=True, exist_ok=True)
        try:
            fd = os.open(launcher, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o755)
        except FileExistsError:
            print('WARNING: luna command appeared concurrently; it was left untouched.', file=sys.stderr)
        else:
            with os.fdopen(fd, 'wb') as out:
                out.write(CLI_LAUNCHER.encode())
    return target


def unit_paths():
    unit_dir = home() / '.config/systemd/user'
    return unit_dir, unit_dir / 'luna-autoupdate.service', unit_dir / 'luna-autoupdate.timer'




# --------------------------------------------------------------------------- release signing
# `luna release` signs the bundle with a dedicated ed25519 key (OpenSSH
# signatures, `ssh-keygen -Y sign`); `luna update` verifies the detached
# `<bundle>.sig` against the machine-local trust file BEFORE anything is
# unpacked or run. The trust file (release-signers) is local configuration: it
# is never shipped in a bundle and never written by install/update. Only
# `luna signing init|trust|untrust` change it. Nothing here touches ~/.ssh.

SIGN_NAMESPACE = 'luna-release'
SIGN_PRINCIPAL = 'luna-release'
SIGN_KEY_NAME = 'luna-release-ed25519'
SIGN_SIGNERS_NAME = 'release-signers'
SIG_MAX_BYTES = 8192            # a real ed25519 signature is ~400 bytes
SIGNERS_MAX_BYTES = 65536
# ssh-ed25519 blob = string "ssh-ed25519" + string(32 bytes) = 51 bytes = 68 base64 chars.
SIGN_BLOB_PREFIX = b'\x00\x00\x00\x0bssh-ed25519\x00\x00\x00\x20'
SIGN_KEY_RE = re.compile(r'^ssh-ed25519 ([A-Za-z0-9+/]{68})(?:[ \t]+\S.*)?$')
SIGN_SIGNERS_RE = re.compile(r'^%s namespaces="%s" ssh-ed25519 ([A-Za-z0-9+/]{68})(?:[ \t]+\S.*)?$'
                             % (SIGN_PRINCIPAL, SIGN_NAMESPACE))


def signing_dir():
    override = os.environ.get('LUNA_SIGNING_DIR')
    if override:
        return Path(override).expanduser()
    base = os.environ.get('XDG_CONFIG_HOME') or str(home() / '.config')
    return Path(base) / 'luna'


def signing_key_path():
    return signing_dir() / SIGN_KEY_NAME


def signing_pub_path():
    return signing_dir() / (SIGN_KEY_NAME + '.pub')


def signers_path():
    return signing_dir() / SIGN_SIGNERS_NAME


def signing_blob_valid(blob):
    try:
        raw = base64.b64decode(blob, validate=True)
    except ValueError:
        return False
    return len(raw) == 51 and raw.startswith(SIGN_BLOB_PREFIX)


def signing_fingerprint(blob):
    digest = hashlib.sha256(base64.b64decode(blob)).digest()
    return 'SHA256:' + base64.b64encode(digest).decode().rstrip('=')


def signing_parse_pubkey(text):
    """The base64 blob of the single ed25519 public key in `text`, or (None, why)."""
    blobs = []
    for line in str(text).splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        match = SIGN_KEY_RE.match(line)
        if not match or not signing_blob_valid(match.group(1)):
            return None, 'not an ssh-ed25519 public key line: %.60r' % line
        if match.group(1) not in blobs:
            blobs.append(match.group(1))
    if len(blobs) != 1:
        return None, 'expected exactly one ssh-ed25519 public key, found %d' % len(blobs)
    return blobs[0], ''


def signers_load():
    """(trusted blobs, unrecognised line count, error). Fails closed on an unreadable file."""
    path = signers_path()
    try:
        with open(str(path), 'rb') as handle:
            data = handle.read(SIGNERS_MAX_BYTES + 1)
    except FileNotFoundError:
        return [], 0, ''
    except OSError as error:
        return [], 0, 'cannot read %s: %s' % (path, error)
    if len(data) > SIGNERS_MAX_BYTES:
        return [], 0, '%s is implausibly large' % path
    keys, junk = [], 0
    for line in data.decode('utf-8', 'replace').splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        match = SIGN_SIGNERS_RE.match(line)
        if match and signing_blob_valid(match.group(1)):
            if match.group(1) not in keys:
                keys.append(match.group(1))
        else:
            junk += 1  # never trusted: only our own canonical line shape counts
    if junk and not keys:
        return [], junk, '%s has content but no valid key line; refusing to guess' % path
    return keys, junk, ''


def signers_text(keys):
    lines = ['# Luna release trust anchor (machine-local; managed by `luna signing`).',
             '# Only these keys may sign bundles accepted by `luna update`.']
    lines += ['%s namespaces="%s" ssh-ed25519 %s' % (SIGN_PRINCIPAL, SIGN_NAMESPACE, blob) for blob in keys]
    return '\n'.join(lines) + '\n'


def signers_save(keys):
    path = signers_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix='.' + path.name + '.', dir=str(path.parent))
    try:
        with os.fdopen(fd, 'w') as handle:
            handle.write(signers_text(keys))
        os.chmod(tmp, 0o644)
        os.replace(tmp, path)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp)
        raise


def signing_read_sig(sig_path):
    """('' | 'absent' | 'bad', bytes, reason) for the detached signature beside a bundle."""
    try:
        info = os.lstat(str(sig_path))
    except FileNotFoundError:
        return 'absent', b'', ''
    except OSError as error:
        return 'bad', b'', 'cannot stat the signature: %s' % error
    if not stat.S_ISREG(info.st_mode):
        return 'bad', b'', 'the signature is not a regular file (symlink or special file)'
    if info.st_size > SIG_MAX_BYTES:
        return 'bad', b'', 'the signature file is implausibly large (%d bytes)' % info.st_size
    try:
        fd = os.open(str(sig_path), os.O_RDONLY | os.O_NOFOLLOW | getattr(os, 'O_NONBLOCK', 0))
        with os.fdopen(fd, 'rb') as handle:
            data = handle.read(SIG_MAX_BYTES + 1)
    except OSError as error:
        return 'bad', b'', 'cannot read the signature: %s' % error
    if len(data) > SIG_MAX_BYTES:
        return 'bad', b'', 'the signature file is implausibly large'
    return 'present', data, ''


def signing_verify(bundle, sig_bytes, keys):
    """Verify `sig_bytes` over the bundle against `keys`. Returns (fingerprint, error)."""
    keygen = shutil.which('ssh-keygen')
    if not keygen:
        return '', 'ssh-keygen is not installed'
    with tempfile.TemporaryDirectory(prefix='luna-sig-') as work:
        sig_file = Path(work) / 'bundle.sig'
        sig_file.write_bytes(sig_bytes)
        signers = Path(work) / 'signers'
        signers.write_text(signers_text(keys))  # rebuilt from validated keys only
        try:
            with open(str(bundle), 'rb') as handle:
                result = subprocess.run([keygen, '-Y', 'verify', '-f', str(signers), '-I', SIGN_PRINCIPAL,
                                         '-n', SIGN_NAMESPACE, '-s', str(sig_file)],
                                        stdin=handle, capture_output=True, text=True, timeout=120)
        except (OSError, subprocess.TimeoutExpired) as error:
            return '', 'ssh-keygen could not run: %s' % error
    if result.returncode != 0:
        detail = (result.stderr.strip() or result.stdout.strip() or 'verification failed').splitlines()[-1]
        return '', detail
    match = re.search(r'\b(SHA256:[A-Za-z0-9+/]+)', result.stdout)
    trusted = {signing_fingerprint(blob) for blob in keys}
    if not match or match.group(1) not in trusted:
        return '', 'the signing key is not one of the trusted keys'
    return match.group(1), ''


def signing_sign(bundle):
    """Sign the bundle with the release key. Returns (fingerprint, error)."""
    key, pub = signing_key_path(), signing_pub_path()
    keygen = shutil.which('ssh-keygen')
    if not keygen:
        return '', 'ssh-keygen is not installed'
    blob, why = signing_parse_pubkey(pub.read_text() if pub.is_file() else '')
    if blob is None:
        return '', 'the public key %s is missing or unreadable (%s)' % (pub, why)
    sig = Path(str(bundle) + '.sig')
    with contextlib.suppress(OSError):
        sig.unlink()
    try:
        result = subprocess.run([keygen, '-Y', 'sign', '-f', str(key), '-n', SIGN_NAMESPACE, str(bundle)],
                                capture_output=True, text=True, timeout=60)
    except (OSError, subprocess.TimeoutExpired) as error:
        return '', 'ssh-keygen could not run: %s' % error
    if result.returncode != 0 or not sig.is_file():
        return '', (result.stderr.strip() or 'signing failed').splitlines()[-1]
    # Self-check against the matching public key so a bad signature is never published.
    fingerprint, error = signing_verify(bundle, sig.read_bytes(), [blob])
    if error:
        with contextlib.suppress(OSError):
            sig.unlink()
        return '', 'the fresh signature did not verify: %s' % error
    return fingerprint, ''


POLICY_NAME = 'signing-policy.json'
STATE_NAME = 'update-state.json'
BUNDLE_VERSION_RE = re.compile(r'[0-9]+\.[0-9]+\.[0-9]+')


def signing_anchor_dir():
    """A second, HOME-independent home for the enforcement marker and the version floor.

    It follows the account database (not $HOME), so a timer, an ssh session or a shell with a
    different HOME/XDG/LUNA_SIGNING_DIR still finds the marker. LUNA_ANCHOR_HOME overrides it (tests)."""
    base = os.environ.get('LUNA_ANCHOR_HOME')
    if not base:
        try:
            import pwd
            base = pwd.getpwuid(os.getuid()).pw_dir
        except (ImportError, KeyError, OSError):
            base = str(home())
    return Path(base) / '.local' / 'share' / 'Lumen' / 'sls-luna'


def signing_state_dirs():
    dirs = []
    for candidate in (luna_tools_dir(), signing_anchor_dir()):
        if candidate not in dirs:
            dirs.append(candidate)
    return dirs


def _read_state_file(path):
    """('missing', None) | ('ok', dict) | ('corrupt', why)."""
    try:
        with open(str(path), 'rb') as handle:
            data = handle.read(65537)
    except FileNotFoundError:
        return 'missing', None
    except OSError as error:
        return 'corrupt', 'cannot read it: %s' % error
    if len(data) > 65536:
        return 'corrupt', 'it is implausibly large'
    try:
        value = json.loads(data.decode('utf-8'))
    except ValueError as error:
        return 'corrupt', 'it is not valid JSON (%s)' % error
    if not isinstance(value, dict):
        return 'corrupt', 'it is not a JSON object'
    return 'ok', value


def signing_marker_read():
    """The enforcement marker, read from every location. Returns (state, trust_file, problem):
    state is 'on', 'off', 'none' or 'corrupt'. Any corrupt copy means corrupt; any enforce:true
    wins over a stale false."""
    states, trust_file = [], ''
    for directory in signing_state_dirs():
        path = directory / POLICY_NAME
        kind, value = _read_state_file(path)
        if kind == 'missing':
            continue
        if kind == 'corrupt' or not isinstance(value.get('enforce'), bool):
            why = value if kind == 'corrupt' else 'it has no boolean "enforce"'
            return 'corrupt', '', 'the signing enforcement marker %s is unusable (%s)' % (path, why)
        states.append(value['enforce'])
        if value['enforce'] and not trust_file and isinstance(value.get('trustFile'), str):
            trust_file = value['trustFile']
    if not states:
        return 'none', '', ''
    if any(states):
        return 'on', trust_file, ''
    return 'off', '', ''


def signing_marker_write(enforce):
    data = {'format': 1, 'enforce': bool(enforce), 'trustFile': str(signers_path()),
            'note': 'managed by `luna signing`; while enforce is true Luna refuses to update '
                    'when no trusted key can be found'}
    wrote = 0
    for directory in signing_state_dirs():
        try:
            write_json_file(directory / POLICY_NAME, data)
            wrote += 1
        except OSError:
            pass
    return wrote


def signing_policy(keys):
    """(enforcing, problem, trust_file, marker_state). Heals a keyed machine that has no marker."""
    marker, trust_file, problem = signing_marker_read()
    if marker == 'none' and keys:
        signing_marker_write(True)
        marker, trust_file = 'on', str(signers_path())
    if marker == 'corrupt':
        return True, problem, '', marker
    if marker == 'on':
        return True, '', trust_file or str(signers_path()), marker
    if marker == 'off':
        return False, '', '', marker
    return bool(keys), '', '', marker


def update_floor_read():
    """(highest min_version string or None, problem). A damaged copy is a problem, never a reset."""
    best = None
    for directory in signing_state_dirs():
        path = directory / STATE_NAME
        kind, value = _read_state_file(path)
        if kind == 'missing':
            continue
        version = value.get('min_version') if kind == 'ok' else None
        if kind == 'corrupt' or not isinstance(version, str) or not BUNDLE_VERSION_RE.fullmatch(version):
            why = value if kind == 'corrupt' else 'min_version is not a plain x.y.z version'
            return None, ('%s is unusable (%s). Luna will not guess; inspect it and delete or fix '
                          'the file by hand' % (path, why))
        if best is None or version_tuple(version) > version_tuple(best):
            best = version
    return best, ''


def version_tuple(version):
    return tuple(int(part) for part in version.split('.'))


def update_floor_raise(version):
    """Raise (never lower) the floor in every location."""
    current, problem = update_floor_read()
    if problem or not BUNDLE_VERSION_RE.fullmatch(version):
        return False
    if current is not None and version_tuple(current) >= version_tuple(version):
        return True
    for directory in signing_state_dirs():
        try:
            write_json_file(directory / STATE_NAME, {'format': 1, 'min_version': version})
        except OSError:
            pass
    return True


def check_bundle_signature(staged, sig_path, allow_unsigned):
    """Authenticity gate, run before anything is unpacked.

    None means refused. Otherwise {'verified': bool, 'enforcing': bool}."""
    keys, _junk, load_error = signers_load()
    state, sig_bytes, reason = signing_read_sig(sig_path)
    enforcing, marker_problem, expected_file, _marker = signing_policy(keys)
    if marker_problem:
        print('REFUSING: %s. This is refused even with --allow-unsigned. Repair it by hand, or run '
              '`luna signing trust PUBKEYFILE` (re-enable) or `luna signing disable`.' % marker_problem,
              file=sys.stderr)
        return None
    if load_error:
        print('REFUSING: the trust file is unusable: %s' % load_error, file=sys.stderr)
        return None
    if enforcing and not keys:
        print('REFUSING: this machine enforces release signatures, but there is no usable trusted key. '
              'Expected trust file: %s (it is missing, empty or in another environment: check '
              'LUNA_SIGNING_DIR / XDG_CONFIG_HOME / HOME). This is refused even with --allow-unsigned. '
              'To trust a key again: luna signing trust PUBKEYFILE. To deliberately stop checking '
              'signatures: luna signing disable' % (expected_file or signers_path()), file=sys.stderr)
        return None
    if keys and expected_file and expected_file != str(signers_path()):
        print('WARNING: the trust file in use (%s) is not the one that enabled enforcement (%s)'
              % (signers_path(), expected_file), file=sys.stderr)
    verdict = {'verified': False, 'enforcing': enforcing}
    if state == 'bad':
        print('REFUSING: the bundle has a signature file that cannot be used (%s). '
              'This is refused even with --allow-unsigned.' % reason, file=sys.stderr)
        return None
    if state == 'absent':
        if not enforcing:
            print('note   : authenticity NOT checked: the bundle is unsigned and no trusted release key is '
                  'configured on this machine. To enable it: luna signing trust PUBKEYFILE '
                  '(the release machine creates one with `luna signing init`)')
            return verdict
        if allow_unsigned:
            print('WARNING: the bundle is UNSIGNED; continuing because --allow-unsigned was given',
                  file=sys.stderr)
            return verdict
        print('REFUSING: the bundle has no signature (.sig) but this machine trusts release key(s) '
              '(%s). If you accept an unsigned bundle, repeat with --allow-unsigned.'
              % ', '.join(signing_fingerprint(k) for k in keys), file=sys.stderr)
        return None
    # A signature is present.
    if not keys:
        print('note   : the bundle is signed, but authenticity is NOT checked: no trusted release key is '
              'configured here. Enable it with: luna signing trust PUBKEYFILE')
        return verdict
    if not shutil.which('ssh-keygen'):
        if allow_unsigned:
            print('WARNING: ssh-keygen is missing, so the signature cannot be verified; continuing because '
                  '--allow-unsigned was given', file=sys.stderr)
            return verdict
        print('REFUSING: this machine trusts release keys but ssh-keygen is not installed, so the '
              'signature cannot be verified. Install openssh, or repeat with --allow-unsigned.',
              file=sys.stderr)
        return None
    fingerprint, error = signing_verify(staged, sig_bytes, keys)
    if error:
        print('REFUSING: the bundle signature is not valid for a trusted key (%s). '
              'This is refused even with --allow-unsigned.' % error, file=sys.stderr)
        return None
    print('signed : verified, signer %s (namespace %s)' % (fingerprint, SIGN_NAMESPACE))
    verdict['verified'] = True
    return verdict


def _signing_read_key_arg(arg):
    if arg == '-':
        return sys.stdin.read(SIGNERS_MAX_BYTES)
    candidate = Path(arg).expanduser()
    try:
        if candidate.is_file():
            if candidate.stat().st_size > SIGNERS_MAX_BYTES:
                return ''
            return candidate.read_text()
    except OSError:
        return ''
    return arg


def cmd_signing(options):
    action = options.signing_action
    arg = options.key
    keygen = shutil.which('ssh-keygen')
    if action == 'status':
        keys, junk, error = signers_load()
        key, pub = signing_key_path(), signing_pub_path()
        print('signing dir    : %s' % signing_dir())
        print('ssh-keygen     : %s' % (keygen or 'MISSING (cannot sign or verify)'))
        blob, _ = signing_parse_pubkey(pub.read_text() if pub.is_file() else '')
        if key.is_file() and blob:
            mode = stat.S_IMODE(key.stat().st_mode)
            print('signing key    : present, %s' % signing_fingerprint(blob))
            print('  private key  : %s (mode %o%s)' % (key, mode, '' if not mode & 0o077 else ' - TOO OPEN, chmod 600'))
            print('  public key   : %s' % pub)
        else:
            print('signing key    : none here (luna release writes unsigned bundles; create one: luna signing init)')
        print('trust file     : %s' % signers_path())
        if error:
            print('  PROBLEM      : %s' % error)
        for item in keys:
            print('  trusted      : %s%s' % (signing_fingerprint(item), '  (this machine\'s own key)' if item == blob else ''))
        if junk and keys:
            print('  ignored      : %d line(s) in the trust file are not valid key lines' % junk)
        enforcing, marker_problem, expected_file, marker = signing_policy(keys)
        print('marker         : %s' % {'on': 'enforcement recorded (%s)' % ', '.join(
                  str(d / POLICY_NAME) for d in signing_state_dirs()),
                  'off': 'enforcement deliberately disabled (luna signing disable)',
                  'none': 'none (no key has ever been trusted here)',
                  'corrupt': 'UNUSABLE'}[marker])
        if marker_problem:
            print('  PROBLEM      : %s' % marker_problem)
        if keys and expected_file and expected_file != str(signers_path()):
            print('  WARNING      : enforcement was enabled for the trust file %s, not this one' % expected_file)
        floor, floor_problem = update_floor_read()
        if floor_problem:
            print('  PROBLEM      : %s' % floor_problem)
        print('minimum bundle version: %s' % (floor or 'none yet (raised by the first signed, verified update)'))
        if error:
            print('policy         : REFUSING every update until the trust file is fixed')
        elif marker_problem:
            print('policy         : REFUSING every update until the marker is repaired')
        elif enforcing and not keys:
            print('policy         : ENFORCING, but NO usable trusted key: every update is refused until '
                  'luna signing trust PUBKEYFILE (expected trust file %s) or luna signing disable'
                  % (expected_file or signers_path()))
        elif enforcing:
            print('policy         : ENFORCING: unsigned or wrongly signed bundles are refused '
                  '(--allow-unsigned overrides only the missing-signature case)')
        else:
            print('policy         : not enforcing: unsigned bundles are accepted (authenticity unchecked); '
                  'luna signing trust PUBKEYFILE turns it on')
        return EXIT_OK
    if action == 'disable':
        signing_marker_write(False)
        print('disabled : signature enforcement is OFF on this machine (unsigned bundles are accepted, '
              'authenticity unchecked). Trusted keys, if any, stay in %s but are not consulted. '
              'luna signing trust PUBKEYFILE turns enforcement back on' % signers_path())
        return EXIT_OK
    if action == 'init':
        key, pub = signing_key_path(), signing_pub_path()
        if os.path.lexists(str(key)) or os.path.lexists(str(pub)):
            print('REFUSING: a signing key already exists (%s); it is never overwritten' % key, file=sys.stderr)
            return EXIT_REFUSED
        if not keygen:
            print('REFUSING: ssh-keygen is not installed', file=sys.stderr)
            return EXIT_REFUSED
        signing_dir().mkdir(parents=True, exist_ok=True, mode=0o700)
        result = subprocess.run([keygen, '-q', '-t', 'ed25519', '-N', '', '-C', SIGN_PRINCIPAL, '-f', str(key)],
                                capture_output=True, text=True)
        if result.returncode != 0 or not key.is_file() or not pub.is_file():
            print('ssh-keygen failed: %s' % (result.stderr.strip() or result.returncode), file=sys.stderr)
            return 1
        os.chmod(key, 0o600)
        blob, why = signing_parse_pubkey(pub.read_text())
        if blob is None:
            print('the new public key is unreadable: %s' % why, file=sys.stderr)
            return 1
        keys, _junk, error = signers_load()
        if error:
            print('key created, but the trust file is unusable: %s' % error, file=sys.stderr)
            return 1
        signing_marker_write(True)  # the marker first: a crash must never leave keys without it
        if blob not in keys:
            signers_save(keys + [blob])
        print('created  : %s (private, mode 600, no passphrase)' % key)
        print('public   : %s' % pub)
        print('trusted  : %s (added to %s)' % (signing_fingerprint(blob), signers_path()))
        print('next     : copy the public key to other machines and run: luna signing trust %s' % pub.name)
        return EXIT_OK
    if action in ('trust', 'untrust'):
        if not arg:
            print('usage: luna signing %s PUBKEY_OR_FILE%s' % (action, ' | SHA256:FINGERPRINT' if action == 'untrust' else ''),
                  file=sys.stderr)
            return EXIT_REFUSED
        keys, _junk, error = signers_load()
        if error:
            print('REFUSING: the trust file is unusable: %s (fix or remove it by hand)' % error, file=sys.stderr)
            return EXIT_REFUSED
        if action == 'untrust' and arg.startswith('SHA256:'):
            matches = [k for k in keys if signing_fingerprint(k) == arg]
            if not matches:
                print('no trusted key with fingerprint %s' % arg, file=sys.stderr)
                return 1
            blob = matches[0]
        else:
            blob, why = signing_parse_pubkey(_signing_read_key_arg(arg))
            if blob is None:
                print('REFUSING: %s' % why, file=sys.stderr)
                return EXIT_REFUSED
        if action == 'trust':
            if blob in keys:
                signing_marker_write(True)
                print('already trusted: %s' % signing_fingerprint(blob))
                return EXIT_OK
            signing_marker_write(True)
            signers_save(keys + [blob])
            print('trusted  : %s (%s)' % (signing_fingerprint(blob), signers_path()))
            print('from now on `luna update` here refuses bundles without a valid signature from a trusted key')
            return EXIT_OK
        if blob not in keys:
            print('not trusted: %s' % signing_fingerprint(blob), file=sys.stderr)
            return 1
        remaining = [k for k in keys if k != blob]
        signers_save(remaining)
        print('untrusted: %s' % signing_fingerprint(blob))
        if not remaining:
            if signing_marker_read()[0] == 'none':
                signing_marker_write(True)
            print('note     : no trusted keys left, but this machine is STILL ENFORCING: every update is '
                  'refused until you trust a key again (luna signing trust PUBKEYFILE) or deliberately '
                  'stop checking with: luna signing disable')
        return EXIT_OK
    return EXIT_REFUSED
def cmd_check(options):
    """Print the update check as JSON (the Luna menu reads it)."""
    write_heartbeat()
    print(json.dumps(check_updates(force=getattr(options, 'force', False)), sort_keys=True))
    return EXIT_OK


def cmd_timer(options):
    """Enable, disable or report the unattended-update timer."""
    unit_dir, service, timer = unit_paths()
    if options.action == 'status':
        enabled = subprocess.run(['systemctl', '--user', 'is-enabled', 'luna-autoupdate.timer'],
                                 capture_output=True, text=True)
        active = subprocess.run(['systemctl', '--user', 'is-active', 'luna-autoupdate.timer'],
                                capture_output=True, text=True)
        print(json.dumps({'enabled': enabled.stdout.strip() or 'unknown',
                          'active': active.stdout.strip() or 'unknown',
                          'units': str(unit_dir)}, sort_keys=True))
        return EXIT_OK
    if options.action == 'on':
        write_tooling()
        unit_dir.mkdir(parents=True, exist_ok=True)
        service.write_text(
            '[Unit]\n'
            'Description=SLS Luna updates (applies a newer release when Steam is closed)\n'
            'After=graphical-session.target\n\n'
            '[Service]\n'
            'Type=oneshot\n'
            'Environment=PATH=%%h/.local/bin:/usr/local/bin:/usr/bin\n'
            'ExecStart=%s %s autoupdate\n' % (sys.executable, luna_tools_dir() / 'luna.py'))
        timer.write_text(
            '[Unit]\n'
            'Description=Check the SLS Luna release channel every 30 minutes\n\n'
            '[Timer]\n'
            'OnCalendar=*:0/30\n'
            'Persistent=true\n'
            'RandomizedDelaySec=120\n\n'
            '[Install]\n'
            'WantedBy=timers.target\n')
        subprocess.run(['systemctl', '--user', 'daemon-reload'], capture_output=True)
        result = subprocess.run(['systemctl', '--user', 'enable', '--now', 'luna-autoupdate.timer'],
                                capture_output=True, text=True)
        if result.returncode != 0:
            print('FAILED: %s' % (result.stderr.strip() or result.stdout.strip()), file=sys.stderr)
            return 1
        print('unattended updates: on (%s)' % timer)
        return EXIT_OK
    if options.action == 'off':
        subprocess.run(['systemctl', '--user', 'disable', '--now', 'luna-autoupdate.timer'],
                       capture_output=True)
        for path in (timer, service):
            if path.exists():
                path.unlink()
        subprocess.run(['systemctl', '--user', 'daemon-reload'], capture_output=True)
        print('unattended updates: off')
        return EXIT_OK
    print('unknown timer action: %s' % options.action, file=sys.stderr)
    return 2


def lumen_hook(action):
    """Use the source worker or the independent installed copy; no full install."""
    candidates = (ROOT / 'scripts/lumen-hook.py',
                  home() / '.local/share/slssteam-luna/lumen-hook.py')
    script = next((path for path in candidates if path.is_file()), None)
    if script is None:
        print('Lumen update hook worker missing; install Luna from a complete bundle.', file=sys.stderr)
        return 1
    return subprocess.run([sys.executable, str(script), action]).returncode


def cmd_hook(options):
    return lumen_hook({'on': 'enable', 'off': 'disable'}.get(options.action, options.action))


def arm_lumen_hook():
    if (addons_dir() / 'luna/backend/main.lua').is_file():
        if lumen_hook('enable'):
            print('WARNING: add-ons installed, but automatic Lumen recovery could not be armed. '
                  'Inspect: luna hook status', file=sys.stderr)


def cmd_autoupdate(options):
    """Timer entry point: check quietly and apply when Steam is closed.

    Modes come from the Health page switch (data/luna.json -> auto_update):
    "off" does nothing unless a manual update was queued, "notify" only
    records what it found, "install" applies a newer release. A queued update
    (pending.json) is honoured in any mode but still needs Steam closed.
    """
    tools = luna_tools_dir()
    pending_path = tools / 'pending.json'
    result_path = tools / 'autoupdate.json'
    lock_path = _update_lock()
    prefs = read_json_file(data_dir() / 'luna.json') or {}
    mode = str(prefs.get('auto_update') or 'off')
    pending = read_json_file(pending_path) or {}
    pending_refresh = read_refresh_pending()
    verbose = bool(getattr(options, 'verbose', False))
    write_heartbeat()
    extra_result = {}

    def record(payload):
        payload.update(extra_result)
        payload['mode'] = mode
        payload['at'] = int(time.time())
        snapshot = steam_state()
        payload['steamBuild'] = snapshot['build']
        payload['steamPinned'] = snapshot['pinned']
        payload['steamDrift'] = steam_drift_note()
        queued = read_steam_pending()
        payload['steamPending'] = str(queued.get('action') or '') if queued else ''
        write_json_file(result_path, payload)
        if verbose:
            print(json.dumps(payload, sort_keys=True))
        return EXIT_OK

    if mode not in ('notify', 'install') and not pending and not pending_refresh:
        return EXIT_OK
    acquired, reason = _acquire_lock(lock_path)
    if not acquired:
        return record({'result': 'deferred', 'reason': reason})
    refresh_message = ''
    try:
        # An explicit refresh request (Health page or `luna refresh --dry-run`
        # planned it, the timer applies it): Steam to Valve's latest, then pin
        # and cache, then hand the Luna add-ons to the normal bundle path
        # below so the bridge and payloads land verified. Needs Steam closed
        # like every other mutation; otherwise it waits for the next run.
        if read_refresh_pending():
            reasons = refuse_reasons(for_install=True)
            if reasons:
                return record({'result': 'deferred', 'reason': reasons[0],
                               'refreshPending': True})
            ok, message, build = _refresh_steam_side()
            if not ok:
                return record({'result': 'error', 'reason': message,
                               'refreshPending': True})
            refresh_message = message
            extra_result['refresh'] = message
            try:
                refresh_pending_path().unlink()
            except OSError:
                pass
            pending = {'tag': '', 'requestedAt': int(time.time())}
            write_json_file(pending_path, pending)
        # The timer only runs while Steam is closed, which is exactly when a
        # pinned client can be restored safely. In install mode (explicit
        # consent via pin + mode) a drifted client is recovered from the local
        # cache before anything else; every mode reports the drift.
        snapshot = steam_state()
        if (snapshot['pinned'] and snapshot['cacheReady']
                and (snapshot['packagesMatch'] is False or snapshot.get('binariesMatch') is False)
                and (mode == 'install' or pending)):
            ok, message = _recover_steam_client(snapshot['pinned'])
            if ok:
                snapshot = steam_state()
            else:
                return record({'result': 'error', 'reason': message})
        # Queued Steam work (Health menu or `luna steam update|cache`) runs here:
        # the timer only fires while Steam is closed, which both need.
        pending_steam = read_steam_pending()
        if pending_steam:
            steam_job = pending_steam.get('action')
            if steam_job == 'update':
                ok, message = _apply_steam_update()
            elif steam_job == 'cache':
                build = steam_client_build()
                if not build:
                    return record({'result': 'error',
                                    'reason': 'cannot determine the client build for caching'})
                try:
                    _cache_client_packages(build)
                    ok, message = True, 'cached Steam client %s' % build
                except OSError as error:
                    ok, message = False, 'could not cache the client: %s' % error
                if ok:
                    try:
                        steam_pending_path().unlink()
                    except OSError:
                        pass
            else:
                try:
                    steam_pending_path().unlink()
                except OSError:
                    pass
                ok, message = True, 'dropped unknown queued Steam task'
            if not ok:
                return record({'result': 'error', 'reason': message})
            # Fall through: a Steam change may come with owed Luna updates.
        # A check is read-only (gh only): notify mode must report even while
        # Steam runs. Only an actual install needs Steam and the sidecar gone.
        report = check_updates(force=True)
        installed = report.get('installed') or '?'
        latest = report.get('latest') or ''
        if not latest:
            return record({'result': 'error', 'reason': report.get('checkError') or 'no release found'})
        target = str(pending.get('tag') or '') if pending else ''
        if not target:
            target = latest
        if not pending and version_key(target) <= version_key(installed):
            return record({'result': 'current', 'version': installed})
        if mode == 'notify' and not pending:
            return record({'result': 'available', 'version': target, 'installed': installed})
        reasons = refuse_reasons(for_install=True)
        if reasons:
            return record({'result': 'deferred', 'reason': reasons[0]})

        # The tag reaches `gh release download` and names the version the bundle must carry:
        # pending.json is writable by anything running as the user, so it is validated first.
        if not isinstance(target, str) or not re.fullmatch(r'v?[0-9]+\.[0-9]+\.[0-9]+', target):
            return record({'result': 'error', 'reason': 'refusing a release tag that is not vX.Y.Z: %.40r' % (target,)})
        work = Path(tempfile.mkdtemp(prefix='luna-autoupdate-'))
        try:
            bundle, error = download_release(target, work)
            if bundle is None:
                return record({'result': 'error', 'reason': error, 'version': target})
            # Never --allow-downgrade here: an unattended update must not roll back.
            code = install_bundle(bundle, expect_version=target.lstrip('v'))
        finally:
            shutil.rmtree(work, ignore_errors=True)
        if code == 0 and pending_path.exists():
            pending_path.unlink()
        return record({'result': 'applied' if code == 0 else 'failed',
                       'version': target, 'installedBefore': installed, 'exit': code})
    except Exception as error:  # noqa: BLE001 - the timer must always leave a trace of why it failed
        return record({'result': 'failed', 'reason': str(error) or error.__class__.__name__})
    finally:
        _release_lock(lock_path)


# Files under ~/.local/share/slssteam-integrations/ that make up a backup.
# Volatile compressor state (jobs, logs, queue, status) is deliberately left
# out: it is rebuilt on the next run. Everything here is small, local JSON.
BACKUP_PATHS = (
    'playtime',
    'presence.json',
    'hltb.json',
    'hltb-library.json',
    'luna.json',
    'sgdb.json',
    'compressor/settings.json',
)


def _backup_entries():
    """(relative path, absolute path) pairs that exist right now."""
    base = data_dir()
    entries = []
    for rel in BACKUP_PATHS:
        path = base / rel
        if path.is_dir():
            for child in sorted(path.rglob('*')):
                if child.is_file():
                    entries.append((str(child.relative_to(base)), child))
        elif path.is_file():
            entries.append((rel, path))
    return entries


def cmd_backup(options):
    """Write one archive with the Luna user data plus a hash manifest."""
    entries = _backup_entries()
    if not entries:
        print('nothing to back up: %s holds no Luna data' % data_dir())
        return EXIT_OK
    out_dir = Path(options.out).expanduser() if options.out else Path(tempfile.gettempdir())
    out_dir.mkdir(parents=True, exist_ok=True)
    stamp = time.strftime('%Y%m%d-%H%M%S')
    archive = out_dir / ('luna-backup-%s.tar.gz' % stamp)
    manifest = {'created': int(time.time()),
                'createdBy': installed_version(),
                'files': {rel: sha256(path) for rel, path in entries}}
    with tempfile.TemporaryDirectory(prefix='luna-backup-') as work:
        stage = Path(work) / 'stage'
        (stage / 'data').mkdir(parents=True)
        for rel, path in entries:
            dest = stage / 'data' / rel
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, dest)
        (stage / 'manifest.json').write_text(json.dumps(manifest, indent=2, sort_keys=True) + '\n')
        with tarfile.open(archive, 'w:gz') as tar:
            tar.add(stage / 'manifest.json', arcname='luna-backup/manifest.json')
            tar.add(stage / 'data', arcname='luna-backup/data')
    print('backup : %s (%d file(s))' % (archive, len(entries)))
    print('note   : includes the SteamGridDB API key (sgdb.json); keep the archive private')
    return EXIT_OK


def cmd_restore(options):
    """Restore a backup archive after validating its manifest.

    Refuses while Steam or the sidecar runs (same rule as install), and never
    overwrites a file that is newer than the archived copy unless --force.
    """
    archive = Path(options.archive).expanduser() if options.archive else None
    if not archive or not archive.is_file():
        print('backup archive not found: %s' % (options.archive or ''), file=sys.stderr)
        return 2
    if process_running('steam') or process_running('steamwebhelper') or process_running('lumen'):
        print('REFUSING to restore: Steam or the Lumen sidecar is running. '
              'Close it completely (Steam -> Exit) first.')
        return EXIT_REFUSED
    with tempfile.TemporaryDirectory(prefix='luna-restore-') as work:
        extract_dir = Path(work) / 'unpacked'
        extract_dir.mkdir()
        try:
            _safe_extract(archive, extract_dir)
        except (tarfile.TarError, ValueError, OSError) as error:
            print('REFUSING: cannot safely unpack the archive: %s' % error, file=sys.stderr)
            return 1
        roots = [entry for entry in extract_dir.iterdir() if entry.is_dir()]
        root = roots[0] if len(roots) == 1 else extract_dir
        manifest_path = root / 'manifest.json'
        data_root = root / 'data'
        if not manifest_path.is_file() or not data_root.is_dir():
            print('REFUSING: not a Luna backup (manifest.json + data/ required)', file=sys.stderr)
            return 1
        try:
            manifest = json.loads(manifest_path.read_text())
            pinned = manifest.get('files') or {}
        except ValueError:
            print('REFUSING: the backup manifest is not valid JSON', file=sys.stderr)
            return 1
        if not isinstance(pinned, dict):
            print('REFUSING: the backup manifest has no file list', file=sys.stderr)
            return 1
        problems, restored, skipped = [], 0, 0
        for rel in sorted(pinned):
            if '..' in Path(rel).parts or rel.startswith('/'):
                problems.append('unsafe path in manifest: %r' % rel)
                continue
            source = data_root / rel
            if not source.is_file():
                problems.append('archive is missing backed-up file: %s' % rel)
                continue
            if sha256(source) != pinned[rel]:
                problems.append('archived file does not match the manifest: %s' % rel)
                continue
            dest = data_dir() / rel
            if dest.is_file() and not options.force:
                try:
                    newer = dest.stat().st_mtime > source.stat().st_mtime
                except OSError:
                    newer = False
                if newer:
                    print('skip   : %s (current copy is newer; re-run with --force to overwrite)' % rel)
                    skipped += 1
                    continue
            dest.parent.mkdir(parents=True, exist_ok=True)
            tmp = dest.with_name(dest.name + '.luna-tmp')
            shutil.copy2(source, tmp)
            os.replace(tmp, dest)
            restored += 1
        if problems:
            print('REFUSING: the backup did not validate:')
            for problem in problems:
                print('  - %s' % problem, file=sys.stderr)
            return 1
    print('restored %d file(s), skipped %d newer file(s)' % (restored, skipped))
    return EXIT_OK


    print('restored %d file(s), skipped %d newer file(s)' % (restored, skipped))
    return EXIT_OK


# ---------------------------------------------------------------------------
# Steam client version management.
#
# A Steam client update can move the interfaces SLSsteam hooks, breaking
# installs and launches until the integration catches up. Luna cannot stop
# Valve's updater on its own, but it can pin the working build, keep a local
# cache of its packages, and put that build back with Steam closed.
# Everything here is machine-local (luna_tools_dir is excluded from sync):
# each machine pins the build it actually validated.

def steam_home():
    native = home() / '.local/share/Steam'
    alternate = home() / '.steam/steam'
    return alternate.resolve() if not native.exists() and alternate.is_dir() else native


def steam_tools_files():
    """SLSsteam binaries whose unexpected change invalidates a pin."""
    base = home() / '.local/share/SLSsteam'
    return {'SLSsteam.so': base / 'SLSsteam.so',
            'library-inject.so': base / 'library-inject.so'}


def steam_client_build():
    """Verified installed binaries, then the on-disk manifest, then runtime logs.

    A package manifest alone does NOT prove that its client was extracted.
    The install receipt is preferred only while the core executable hashes match.
    Newer clients log "Client version: 0" at startup, so a zero report is
    treated as "no information" rather than a build number.
    """
    receipt = read_json_file(luna_tools_dir() / 'steam-client-installed.json') or {}
    core = receipt.get('core') or {}
    if core:
        try:
            if all(sha256(steam_home() / _steam_payload_path(name)) == digest
                   for name, digest in core.items()):
                return str(receipt.get('build') or '')
        except (OSError, ValueError):
            pass
    try:
        manifest = (steam_home() / 'package' / 'steam_client_ubuntu12.manifest').read_text(
            encoding='utf-8', errors='replace')
        found = re.findall(r'"version"\s+"(\d+)"', manifest)
        manifest_build = next((build for build in reversed(found) if build != '0'), '')
        if manifest_build:
            return manifest_build
    except OSError:
        pass
    log = steam_home() / 'logs' / 'console_log.txt'
    try:
        size = log.stat().st_size
    except OSError:
        size = 0
    if size:
        try:
            with open(log, 'rb') as handle:
                handle.seek(max(0, size - 65536))
                tail = handle.read().decode('utf-8', errors='replace')
            found = [build for build in re.findall(r'Client version:\s*(\d+)', tail)
                     if build != '0']
            if found:
                return found[-1]
        except OSError:
            pass
    return ''


STEAM_CFG_BLOCK = ('BootStrapperInhibitAll=enable\n'
                     'BootStrapperForceSelfUpdate=disable\n')


# The hard lock (`luna steam lock`) also stops the launch-time update check and
# is written to both spellings of the file name that Steam's bootstrapper reads.
STEAM_HARD_CFG_BLOCK = ('BootStrapperInhibitAll=enable\n'
                        'BootStrapperInhibitUpdateOnLaunch=enable\n'
                        'BootStrapperForceSelfUpdate=false\n')
_STEAM_CFG_KEYS = re.compile(
    r'\s*BootStrapper(?:InhibitAll|InhibitUpdateOnLaunch|ForceSelfUpdate)\s*=', re.I)


def steam_cfg_path():
    return steam_home() / 'steam.cfg'


def steam_cfg_paths():
    """Both spellings the bootstrapper honors (distinct files on Linux)."""
    return [steam_home() / 'Steam.cfg', steam_home() / 'steam.cfg']


def steam_updates_blocked():
    try:
        content = steam_cfg_path().read_text()
    except OSError:
        return False
    return bool(re.search(r'^\s*BootStrapperInhibitAll\s*=\s*enable\s*$', content, re.M | re.I))


def ensure_steam_cfg_block(paths=None, block=None):
    """Write the bootstrapper inhibit block; Steam honors it on next launch.

    While a hard lock is recorded the hard block goes to both cfg files, so
    every code path that re-applies the block keeps the lock intact.
    """
    hard = steam_hard_lock_active()
    if block is None:
        block = STEAM_HARD_CFG_BLOCK if hard else STEAM_CFG_BLOCK
    if paths is None:
        paths = steam_cfg_paths() if hard else [steam_cfg_path()]
    for path in paths:
        path.parent.mkdir(parents=True, exist_ok=True)
        try:
            previous = path.read_text()
        except FileNotFoundError:
            previous = ''
        lines = [line for line in previous.splitlines() if not _STEAM_CFG_KEYS.match(line)]
        path.write_text('\n'.join(lines + block.splitlines()) + '\n')
    return paths[-1]


def remove_steam_cfg_block(paths=None):
    """Remove the block only if the file holds exactly what Luna wrote.

    Returns True when every file that held a Luna block was removed.
    """
    removed, kept = False, False
    for path in (paths if paths is not None else [steam_cfg_path()]):
        try:
            content = path.read_text()
        except OSError:
            continue
        if content in (STEAM_CFG_BLOCK, STEAM_HARD_CFG_BLOCK):
            try:
                path.unlink()
                removed = True
            except OSError:
                kept = True
        elif any(_STEAM_CFG_KEYS.match(line) for line in content.splitlines()):
            kept = True
    return removed and not kept


def pacman_conf_path():
    return Path(os.environ.get('LUNA_PACMAN_CONF', '/etc/pacman.conf'))


def pacman_steam_state():
    """Is the Steam client pacman-managed, and is it ignored on updates?

    No root needed: `pacman -Q` answers the first, the conf file the second.
    """
    managed, ignored = False, False
    try:
        result = subprocess.run(['pacman', '-Q', 'steam'],
                                capture_output=True, text=True, timeout=15)
        managed = result.returncode == 0
    except (OSError, subprocess.SubprocessError):
        return managed, ignored
    if not managed:
        return managed, ignored
    try:
        content = pacman_conf_path().read_text()
    except OSError:
        return managed, ignored
    for line in content.splitlines():
        stripped = line.split('#', 1)[0].strip()
        if not stripped or '=' not in stripped:
            continue
        key, _, value = stripped.partition('=')
        if key.strip().lower() == 'ignorepkg' and 'steam' in value.split():
            ignored = True
    return managed, ignored


def steam_pin_path():
    return luna_tools_dir() / 'steam-pin.json'


def steam_cache_dir():
    return luna_tools_dir() / 'steam-client-cache'


def read_steam_pin():
    pin = read_json_file(steam_pin_path())
    return pin if isinstance(pin, dict) else {}


def steam_hard_lock_active():
    """Is the ubuntu12 rollback + read-only package lock recorded in the pin?"""
    lock = read_steam_pin().get('hardLock')
    return isinstance(lock, dict) and bool(lock)


def new_steam_pin(build):
    """A pin record for `build`; carries an active hard lock forward."""
    pin = {'clientBuild': str(build), 'slssteam': slssteam_hashes(),
           'at': int(time.time()), 'by': installed_version()}
    lock = read_steam_pin().get('hardLock')
    if isinstance(lock, dict) and lock:
        pin['hardLock'] = lock
    return pin


@contextlib.contextmanager
def steam_package_writable():
    """Let Luna write into SDIR/package despite the hard lock's read-only bit.

    A no-op when the directory is writable and no hard lock is recorded;
    otherwise (Luna's hard lock, or a read-only bit left by a manual/community
    lock) it is made writable and put back to read-only afterwards, even if
    the work raises.
    """
    package = steam_home() / 'package'
    relock = package.is_dir() and (steam_hard_lock_active() or not os.access(package, os.W_OK))
    if relock:
        package.chmod(package.stat().st_mode | stat.S_IWUSR)
    try:
        yield
    finally:
        if relock and package.is_dir():
            package.chmod(package.stat().st_mode & ~(stat.S_IWUSR | stat.S_IWGRP | stat.S_IWOTH))


def slssteam_hashes():
    """Current hashes of the SLSsteam binaries (missing -> '')."""
    hashes = {}
    for name, path in steam_tools_files().items():
        try:
            hashes[name] = sha256(path) if path.is_file() else ''
        except OSError:
            hashes[name] = ''
    return hashes


def _package_stats(root, with_hash=False):
    """Fingerprint of a package tree: {rel: [size, mtime_ns]} (+ sha256)."""
    stats = {}
    for path in sorted(root.rglob('*')):
        if path.is_file():
            try:
                st = path.stat()
                entry = [st.st_size, st.st_mtime_ns]
                if with_hash:
                    entry.append(sha256(path))
                stats[str(path.relative_to(root))] = entry
            except OSError:
                pass
    return stats


def _cache_manifest():
    manifest = read_json_file(steam_cache_dir() / 'manifest.json')
    return manifest if isinstance(manifest, dict) else {}


def _stats_match(left, right):
    """Size+mtime comparison (hashes, when present, are ignored: fast path)."""
    if not set(left).issubset(right):
        return False
    return all(left[key][:2] == right[key][:2] for key in left)


def packages_match_cache():
    """Do the installed packages still match the cached build?

    None when there is no usable cache; otherwise a size+mtime comparison,
    which is instant and catches any client update or partial download.
    """
    manifest = _cache_manifest()
    if not manifest or not (steam_cache_dir() / 'package').is_dir():
        return None
    target = steam_home() / 'package'
    if not target.is_dir():
        return False
    return _stats_match(manifest, _package_stats(target))


def _package_read_only():
    try:
        return not (steam_home() / 'package').stat().st_mode & stat.S_IWUSR
    except OSError:
        return False


def steam_state():
    """Everything the menu and preflight report about the Steam client."""
    build = steam_client_build()
    pin = read_steam_pin()
    pinned = str(pin.get('clientBuild') or '')
    cache_marker = steam_cache_dir() / 'build.txt'
    try:
        cached = cache_marker.read_text().strip()
    except OSError:
        cached = ''
    cache_ready = bool(cached) and (steam_cache_dir() / 'package').is_dir()
    packages_match = packages_match_cache() if cache_ready else None
    receipt = read_json_file(luna_tools_dir() / 'steam-client-installed.json') or {}
    binaries_match = None
    if receipt.get('core'):
        try:
            binaries_match = all(sha256(steam_home() / _steam_payload_path(name)) == digest
                                 for name, digest in receipt['core'].items())
        except (OSError, ValueError):
            binaries_match = False
    if cache_ready:
        match = packages_match is True and binaries_match is not False and build == pinned
    else:
        match = bool(build and pinned and build == pinned)
    current_hashes = slssteam_hashes()
    pinned_hashes = pin.get('slssteam') or {}
    tools_drift = [name for name, digest in current_hashes.items()
                   if digest and pinned_hashes.get(name) and digest != pinned_hashes[name]]
    pacman_managed, pacman_ignored = pacman_steam_state()
    return {
        'build': build,
        'pinned': pinned,
        'match': match,
        'packagesMatch': packages_match,
        'binariesMatch': binaries_match,
        'updatesBlocked': steam_updates_blocked(),
        'slssteam': current_hashes,
        'slssteamDrift': tools_drift,
        'cachedBuild': cached,
        'cacheReady': cache_ready,
        'pacmanManaged': pacman_managed,
        'pacmanIgnored': pacman_ignored,
        'hardLock': bool(pin.get('hardLock')),
        'packageReadOnly': _package_read_only(),
    }


def cached_client_build():
    try:
        return (steam_cache_dir() / 'build.txt').read_text().strip()
    except OSError:
        return ''


def steam_pending_path():
    return luna_tools_dir() / 'pending-steam.json'


def read_steam_pending():
    pending = read_json_file(steam_pending_path())
    return pending if isinstance(pending, dict) else {}


def steam_sh_path():
    override = os.environ.get('LUNA_STEAM_SH')
    if override:
        return Path(override)
    return steam_home() / 'steam.sh'


def _steam_force_update():
    """Run the Steam bootstrapper's forced update and exit.

    Called only with Steam closed. Returns (ok, message). The update block
    is lifted for the run and re-applied afterwards either way.
    """
    if steam_hard_lock_active():
        return False, ('the Steam hard lock is active (package/ read-only, ubuntu12 rollback); '
                       'run: luna steam unlock --now to let Steam update')
    try:
        _steam_client_closed()
    except ValueError as error:
        return False, str(error)
    had_block = steam_updates_blocked()
    try:
        steam_cfg_path().unlink()
    except OSError:
        pass
    try:
        result = subprocess.run([str(steam_sh_path()), '-forcesteamupdate',
                                 '-forcepackagedownload', '-exitsteam'],
                                capture_output=True, text=True, timeout=600)
    except (OSError, subprocess.SubprocessError, subprocess.TimeoutExpired) as error:
        result = None
        failure = str(error)
    if had_block:
        try:
            ensure_steam_cfg_block()
        except OSError:
            pass
    if result is None:
        return False, 'could not run the Steam updater: %s' % failure
    if result.returncode != 0:
        tail = (result.stderr.strip() or result.stdout.strip())[-500:]
        return False, 'Steam updater exited %d: %s' % (result.returncode, tail)
    # The bootstrapper relaunches Steam after a successful update even with
    # -exitsteam. Shut it back down gracefully: the caller asked for Steam to
    # stay closed. Never kill processes; report if it is still up.
    note = ('; block re-applied' if had_block
            else '; updates currently allowed - pin the new build to block them')
    relaunched = ''
    if process_running('steam') or process_running('steamwebhelper'):
        windows = gui_describe_blockers()  # best effort; '' when the GUI layer is unavailable
        relaunched = '; the updater relaunched Steam (%s)' % windows if windows else ''
        try:
            subprocess.run([str(steam_sh_path()), '-shutdown'],
                           capture_output=True, text=True, timeout=30)
        except (OSError, subprocess.SubprocessError, subprocess.TimeoutExpired):
            pass
        deadline = time.monotonic() + 60
        while deadline > time.monotonic():
            if not (process_running('steam') or process_running('steamwebhelper')):
                break
            time.sleep(2)
        if process_running('steam') or process_running('steamwebhelper'):
            still = gui_describe_blockers()
            return False, ('Steam updated but is still running after a shutdown request; '
                           'close it completely (Steam -> Exit) before pinning or installing' + note
                           + (' [%s]' % still if still else ''))
        sidecar = gui_lumen_note()
        if sidecar:
            note += '; ' + sidecar
    return True, 'Steam client updated by Valve' + relaunched + note


def prune_steam_client_backups(keep=5):
    """Keep only the newest `keep` client rollback backups.

    Each successful client install/recovery retains a full rollback copy, so
    without pruning this directory grows without bound. Only directories whose
    names are nanosecond timestamps (written by this installer) are touched;
    anything else is left alone.
    """
    backups = luna_tools_dir() / 'steam-client-backups'
    try:
        entries = [entry for entry in backups.iterdir()
                   if entry.is_dir() and entry.name.isdigit()]
    except OSError:
        return 0
    entries.sort(key=lambda entry: int(entry.name))
    removed = 0
    for entry in entries[:-keep] if len(entries) > keep else []:
        try:
            shutil.rmtree(entry, ignore_errors=False)
            removed += 1
        except OSError:
            pass
    return removed


def _cache_client_packages(build):
    """Snapshot the installed package tree into the local cache.

    The cached manifest must describe `build`; a stale on-disk manifest (or a
    mislabeled earlier cache) is refused instead of silently relabeled.
    """
    source = steam_home() / 'package'
    cache = steam_cache_dir()
    try:
        installed_manifest = (source / STEAM_MANIFEST_NAME).read_text(
            encoding='utf-8', errors='replace')
    except OSError:
        raise ValueError('no Steam package manifest at %s' % (source / STEAM_MANIFEST_NAME))
    found = re.findall(r'"version"\s+"(\d+)"', installed_manifest)
    installed_build = next((item for item in reversed(found) if item != '0'), '')
    if installed_build != build:
        raise ValueError('installed packages describe build %s, not %s; refusing to mislabel the cache'
                         % (installed_build or 'unknown', build))
    if cache.exists():
        shutil.rmtree(cache, ignore_errors=True)
    shutil.copytree(source, cache / 'package', symlinks=False)
    # copytree preserves the hard lock's read-only bit; the cache must stay deletable.
    (cache / 'package').chmod((cache / 'package').stat().st_mode | stat.S_IWUSR)
    (cache / 'build.txt').write_text(build + '\n')
    write_json_file(cache / 'manifest.json', _package_stats(cache / 'package', with_hash=True))
    return cache


STEAM_COMPAT_BUILD = '1791918634'
STEAM_COMPAT_MANIFEST_SHA256 = 'a87699c36d28721af5ca6ade7276f506d22a11f9829747167d96845fc080afa5'
STEAM_ARCHIVE_BASE = ('https://web.archive.org/web/20261014104109if_/'
                      'http://media.steampowered.com/client/')
STEAM_MANIFEST_NAME = 'steam_client_ubuntu12.manifest'
STEAM_CORE_FILES = ('ubuntu12_32/steam', 'ubuntu12_32/steamclient.so',
                    'ubuntu12_64/steamwebhelper')


def _steam_payload_path(name):
    """Valve ZIPs use both slash styles. Never accept account/game/cache paths."""
    path = PurePosixPath(name.replace('\\', '/'))
    protected = {'config', 'userdata', 'steamapps', 'appcache', 'logs', 'depotcache', 'package'}
    if (path.is_absolute() or not path.parts or '..' in path.parts
            or ':' in str(path) or path.parts[0].startswith('.')
            or path.parts[0].lower() in protected):
        raise ValueError('unsafe/protected Steam payload path: %s' % name)
    return path


def _steam_package_entries(data, want):
    manifest = parse_vdf(data.decode('utf-8'))
    body = manifest.get('ubuntu12') or {}
    if body.get('version') != want:
        raise ValueError('Steam manifest is not build %s' % want)
    entries = []
    for values in body.values():
        if not isinstance(values, dict) or 'file' not in values:
            continue
        compressed = 'zipvz' in values
        name = values.get('zipvz') if compressed else values['file']
        digest = values.get('sha2vz' if compressed else 'sha2', '')
        if (not re.fullmatch(r'[A-Za-z0-9_.-]+', name or '')
                or not re.fullmatch(r'[0-9a-f]{64}', digest)):
            raise ValueError('unsafe package name or missing SHA256 in Steam manifest')
        entries.append((name, digest, compressed))
    if not entries:
        raise ValueError('Steam manifest has no verified packages')
    return entries


STEAM_DOWNLOAD_ATTEMPTS = 5
STEAM_RETRY_STATUS = (408, 425, 429, 500, 502, 503, 504)
STEAM_CACHE_HINT = ('copy the verified package files into a local directory and pass '
                    '--client-cache DIR (or set LUNA_STEAM_CACHE=DIR), e.g. from another '
                    "machine's ~/.local/share/Lumen/sls-luna/steam-client-cache/package")


def _retry_after_seconds(error):
    """Seconds from a Retry-After header (delta-seconds form), else None."""
    try:
        value = error.headers.get('Retry-After') if error.headers else None
        return max(0.0, min(float(value), 300.0)) if value is not None else None
    except (TypeError, ValueError):
        return None


def _format_mb(size):
    return '%.1f MB' % (size / 1e6)


class _Progress:
    """Throttled progress: carriage-return on a TTY, sparse plain lines otherwise."""

    def __init__(self, label, total=0):
        self.label, self.total = label, total
        self.tty = sys.stdout.isatty()
        self.last = 0.0
        self.step = 0

    def update(self, done, final=False):
        now = time.monotonic()
        if not final and now - self.last < (0.2 if self.tty else 5.0):
            return
        self.last = now
        text = ('%s of %s (%d%%)' % (_format_mb(done), _format_mb(self.total), 100 * done // self.total)
                if self.total else _format_mb(done))
        if self.tty:
            print('\r\033[Ksteam     : %s  %s' % (self.label, text), end='\n' if final else '', flush=True)
        else:
            print('steam     :   %s  %s' % (self.label, text), flush=True)


def _download_steam_file(url, destination, expected, limit=512 * 1024 * 1024,
                         label=None, total=0, attempts=None):
    """Download `url` to `destination`, verify sha256.

    Retries timeouts, connection errors and HTTP 408/425/429/5xx with
    exponential backoff + jitter (honouring Retry-After). A hash mismatch or
    other 4xx is final for this URL.
    """
    attempts = attempts or STEAM_DOWNLOAD_ATTEMPTS
    request = urllib.request.Request(url, headers={'User-Agent': 'Luna-Steam-Installer'})
    for attempt in range(1, attempts + 1):
        try:
            progress = _Progress(label, total) if label else None
            with urllib.request.urlopen(request, timeout=60) as source, open(destination, 'wb') as out:
                size = 0
                try:
                    header_size = int(source.headers.get('Content-Length') or 0)
                except (AttributeError, TypeError, ValueError):
                    header_size = 0
                if progress and header_size:
                    progress.total = header_size
                while True:
                    chunk = source.read(1024 * 1024)
                    if not chunk:
                        break
                    size += len(chunk)
                    if size > limit:
                        raise ValueError('Steam download exceeds size limit')
                    out.write(chunk)
                    if progress:
                        progress.update(size)
            if progress:
                progress.update(size, final=True)
            break
        except urllib.error.HTTPError as error:
            if error.code not in STEAM_RETRY_STATUS or attempt == attempts:
                raise OSError('HTTP %s from %s' % (error.code, url)) from error
            delay = _retry_after_seconds(error)
            reason = 'HTTP %s' % error.code
        except (urllib.error.URLError, TimeoutError, ConnectionError) as error:
            if attempt == attempts:
                raise OSError('%s: %s' % (url, error)) from error
            delay = None
            reason = str(error)
        if delay is None:
            delay = min(60.0, 2.0 ** attempt) * (0.5 + random.random() / 2)
        print('steam     : %s; retry %d/%d in %.0fs' % (reason, attempt, attempts - 1, delay), flush=True)
        time.sleep(delay)
    if sha256(destination) != expected:
        raise ValueError('Steam download SHA256 mismatch: %s' % url)


def _steam_package_sizes(data):
    """{package name: advertised size in bytes or 0} from the manifest."""
    body = parse_vdf(data.decode('utf-8')).get('ubuntu12') or {}
    sizes = {}
    for values in body.values():
        if isinstance(values, dict) and 'file' in values:
            compressed = 'zipvz' in values
            name = values.get('zipvz') if compressed else values['file']
            raw = str(values.get('sizevz' if compressed else 'size', ''))
            sizes[name] = int(raw) if raw.isdigit() else 0
    return sizes


def _stage_steam_payload(packages, data, want, destination):
    """Verify each package, decode VZip and extract ONLY official client files."""
    entries = {}
    total = 0
    destination.mkdir()
    for name, expected, compressed in _steam_package_entries(data, want):
        source = packages / name
        if source.is_symlink() or sha256(source) != expected:
            raise ValueError('Steam package SHA256 mismatch: %s' % name)
        raw = source.read_bytes()
        if compressed:
            if raw[:3] != b'VZa' or raw[-2:] != b'zv' or len(raw) < 22:
                raise ValueError('invalid Steam VZip header: %s' % name)
            prop = raw[7]
            dictionary = struct.unpack('<I', raw[8:12])[0]
            if prop >= 225 or dictionary > 128 * 1024 * 1024:
                raise ValueError('invalid Steam LZMA properties')
            filters = [{'id': lzma.FILTER_LZMA1, 'dict_size': dictionary,
                        'lc': prop % 9, 'lp': (prop // 9) % 5, 'pb': prop // 45}]
            crc, size = struct.unpack('<II', raw[-10:-2])
            if size > 1024 * 1024 * 1024:
                raise ValueError('Steam archive exceeds size limit')
            decoder = lzma.LZMADecompressor(format=lzma.FORMAT_RAW, filters=filters)
            raw = decoder.decompress(raw[12:-10], max_length=size + 1)
            if not decoder.eof or len(raw) != size or zlib.crc32(raw) != crc:
                raise ValueError('Steam VZip integrity check failed: %s' % name)
        with zipfile.ZipFile(io.BytesIO(raw)) as archive:
            for item in archive.infolist():
                relative = _steam_payload_path(item.filename)
                target = destination / relative
                if not target.parent.resolve().is_relative_to(destination.resolve()):
                    raise ValueError('Steam archive traverses a symlink: %s' % relative)
                if item.is_dir():
                    target.mkdir(parents=True, exist_ok=True)
                    continue
                total += item.file_size
                if item.file_size > 512 * 1024 * 1024 or total > 4 * 1024 * 1024 * 1024:
                    raise ValueError('Steam payload exceeds size limit')
                content = archive.read(item)  # also verifies ZIP CRC
                link = stat.S_ISLNK(item.external_attr >> 16)
                if link:
                    link_target = content.decode('utf-8')
                    if not (target.parent / link_target).resolve().is_relative_to(destination.resolve()):
                        raise ValueError('Steam symlink escapes payload: %s' % relative)
                info = {'sha256': hashlib.sha256(content).hexdigest(), 'link': link}
                key = str(relative)
                if key in entries:
                    if entries[key] != info:
                        raise ValueError('conflicting Steam archive entry: %s' % key)
                    continue
                target.parent.mkdir(parents=True, exist_ok=True)
                if link:
                    target.symlink_to(link_target)
                else:
                    target.write_bytes(content)
                    # Valve's ZIPs mark Linux executables as 0666, even ELF files.
                    target.chmod(0o755 if content.startswith((b'\x7fELF', b'#!')) else 0o644)
                    stamp = time.mktime((*item.date_time, 0, 0, -1))
                    os.utime(target, (stamp, stamp))
                entries[key] = info
    if not set(STEAM_CORE_FILES).issubset(entries):
        raise ValueError('Steam payload is missing core client executables')
    return entries


def _steam_client_closed():
    if any(process_running(name) for name in ('steam', 'steamwebhelper', 'lumen')):
        raise ValueError('Steam or the Lumen sidecar is running; close it completely first')


def _install_steam_payload(payload, entries, want, packages):
    """Install extracted binaries transactionally (package/ unlocked meanwhile)."""
    with steam_package_writable():
        return _install_steam_payload_locked(payload, entries, want, packages)


def _install_steam_payload_locked(payload, entries, want, packages):
    """Install extracted binaries transactionally; retain a machine-local backup."""
    _steam_client_closed()
    root = steam_home().resolve()
    backup = luna_tools_dir() / 'steam-client-backups' / str(time.time_ns())
    backup.mkdir(parents=True)
    changed = []
    targets = []
    for name, info in entries.items():
        target = root / _steam_payload_path(name)
        try:
            if target.is_symlink() != info['link']:
                raise OSError('different file type')
            content = os.readlink(target).encode() if info['link'] else target.read_bytes()
            same = hashlib.sha256(content).hexdigest() == info['sha256']
            source = payload / name
            if same and (info['link'] or stat.S_IMODE(target.stat().st_mode) == stat.S_IMODE(source.stat().st_mode)):
                continue
        except OSError:
            pass
        targets.append((target, payload / name))
    data = (packages / STEAM_MANIFEST_NAME).read_bytes()
    for name in [STEAM_MANIFEST_NAME] + [entry[0] for entry in _steam_package_entries(data, want)]:
        source, target = packages / name, root / 'package' / name
        # Preserve package stats so Health can cheaply compare the installed cache.
        if (not target.is_file() or target.is_symlink()
                or source.stat().st_size != target.stat().st_size
                or source.stat().st_mtime_ns != target.stat().st_mtime_ns
                or sha256(source) != sha256(target)):
            targets.append((target, source))
    # Save/update the receipt and cfg in the same transaction as the binaries.
    receipt = luna_tools_dir() / 'steam-client-installed.json'
    marker = root / '.steam-enable-steamrt64-client'
    saved = []
    try:
        for index, (target, _) in enumerate(targets + [(receipt, None), (steam_cfg_path(), None), (marker, None)]):
            if not target.parent.resolve().is_relative_to(root) and target != receipt:
                raise ValueError('Steam destination escapes its root: %s' % target)
            if target.exists() and not target.is_symlink() and not target.is_file():
                raise ValueError('Steam destination is not a regular file: %s' % target)
            previous = backup / str(index)
            exists = target.exists() or target.is_symlink()
            if exists:
                shutil.copy2(target, previous, follow_symlinks=False)
            saved.append((target, previous if exists else None))
        write_json_file(backup / 'restore.json', {
            'build': want, 'files': [{'path': str(path), 'backup': old.name if old else None}
                                    for path, old in saved]})
        _steam_client_closed()  # recheck after slow backup/extraction
        for target, source in targets:
            target.parent.mkdir(parents=True, exist_ok=True)
            temp = target.with_name(target.name + '.luna-new')
            if temp.exists() or temp.is_symlink():
                raise ValueError('Steam temporary destination already exists: %s' % temp)
            try:
                shutil.copy2(source, temp, follow_symlinks=False)
                os.replace(temp, target)
            finally:
                if temp.exists() or temp.is_symlink():
                    temp.unlink()
            changed.append(target)
        for name, info in entries.items():
            target = root / name
            content = os.readlink(target).encode() if info['link'] else target.read_bytes()
            if hashlib.sha256(content).hexdigest() != info['sha256']:
                raise ValueError('installed Steam client verification failed: %s' % name)
        for target in (receipt, steam_cfg_path(), marker):
            changed.append(target)
        if marker.exists() or marker.is_symlink():
            marker.unlink()
        ensure_steam_cfg_block()
        write_json_file(receipt, {'build': want, 'at': int(time.time()), 'backup': str(backup),
                                 'core': {name: entries[name]['sha256'] for name in STEAM_CORE_FILES}})
    except Exception:
        for target, previous in reversed(saved):
            if target not in changed:
                continue
            if target.exists() or target.is_symlink():
                target.unlink()
            if previous is not None:
                shutil.copy2(previous, target, follow_symlinks=False)
        raise
    return backup


def _steam_sources(extra_cache=None):
    """Directories searched (sha256-verified) before downloading, in order."""
    sources = []
    for raw in (extra_cache, os.environ.get('LUNA_STEAM_CACHE')):
        if raw:
            base = Path(raw).expanduser()
            sources.append(base / 'package' if (base / 'package').is_dir() else base)
    sources += [steam_home() / 'package', steam_cache_dir() / 'package']
    return sources


def _find_steam_package(sources, name, digest):
    for source in sources:
        candidate = source / name
        try:
            if candidate.is_file() and not candidate.is_symlink() and sha256(candidate) == digest:
                return candidate
        except OSError:
            continue
    return None


def steam_client_summary(extra_cache=None):
    """Read-only, offline description of what installing the client would fetch."""
    sources = _steam_sources(extra_cache)
    for source in sources:
        candidate = source / STEAM_MANIFEST_NAME
        try:
            if candidate.is_file() and sha256(candidate) == STEAM_COMPAT_MANIFEST_SHA256:
                data = candidate.read_bytes()
                break
        except OSError:
            continue
    else:
        return ('need the build %s manifest from Valve/archive.org (download size unknown until '
                'manifest download)' % STEAM_COMPAT_BUILD)
    sizes = _steam_package_sizes(data)
    need, reuse = [], 0
    for name, digest, _ in _steam_package_entries(data, STEAM_COMPAT_BUILD):
        if _find_steam_package(sources, name, digest):
            reuse += 1
        else:
            need.append(name)
    total = sum(sizes.get(name, 0) for name in need)
    return ('need %d file(s), %s to download, %d reused from cache'
            % (len(need) + reuse, _format_mb(total) if total or not need else 'size unknown', reuse))


def steam_client_needed(options):
    """(needed, reason). Install touches the Steam client only when this says so."""
    if getattr(options, 'keep_steam_client', False) or getattr(options, 'no_steam_client', False):
        return False, 'skipped by --no-steam-client / --keep-steam-client'
    if getattr(options, 'steam_client', False):
        return True, 'forced by --steam-client'
    pin = read_steam_pin()
    if not pin.get('clientBuild'):
        return True, 'no Steam client pin yet'
    if str(pin['clientBuild']) != STEAM_COMPAT_BUILD:
        return True, 'pin is build %s, Luna targets %s' % (pin['clientBuild'], STEAM_COMPAT_BUILD)
    state = steam_state()
    if state['build'] != state['pinned']:
        return True, 'Steam is build %s but the pin is %s' % (state['build'] or 'unknown', state['pinned'])
    if state['packagesMatch'] is False or state['binariesMatch'] is False:
        return True, 'Steam packages/executables drifted from the pin'
    if not getattr(options, 'only', None):
        return True, 'full install (verifies the pinned client; nothing is downloaded if it matches)'
    return False, 'pinned client build %s is intact; use --steam-client to force' % STEAM_COMPAT_BUILD


def ensure_compatible_steam(extra_cache=None):
    """Default install policy: fetch/verify the pinned Valve build, then extract it."""
    try:
        _steam_client_closed()
        if read_steam_pending():
            raise ValueError('a Steam task is queued; run: luna steam cancel before installing')
        if not (steam_home() / 'steam.sh').is_file():
            raise ValueError('Steam must be installed and opened once before installing Luna')
        tools = luna_tools_dir()
        tools.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(prefix='steam-client-stage-', dir=tools) as temporary:
            work = Path(temporary)
            packages = work / 'package'
            packages.mkdir()
            manifest = packages / STEAM_MANIFEST_NAME
            sources = _steam_sources(extra_cache)
            for source in sources:
                candidate = source / STEAM_MANIFEST_NAME
                if candidate.is_file() and sha256(candidate) == STEAM_COMPAT_MANIFEST_SHA256:
                    shutil.copy2(candidate, manifest)
                    break
            else:
                print('steam     : fetching the build %s manifest ...' % STEAM_COMPAT_BUILD, flush=True)
                _download_steam_file(STEAM_ARCHIVE_BASE + 'steam_client_ubuntu12', manifest,
                                     STEAM_COMPAT_MANIFEST_SHA256, limit=1024 * 1024)
            data = manifest.read_bytes()
            sizes = _steam_package_sizes(data)
            entries_list = _steam_package_entries(data, STEAM_COMPAT_BUILD)
            found = {name: _find_steam_package(sources, name, digest) for name, digest, _ in entries_list}
            todo = [name for name, _, _ in entries_list if not found[name]]
            print('steam     : need %d file(s), %s to download, %d reused from cache'
                  % (len(entries_list), _format_mb(sum(sizes.get(n, 0) for n in todo)),
                     len(entries_list) - len(todo)), flush=True)
            for index, (name, digest, _) in enumerate(entries_list, 1):
                destination = packages / name
                if found[name]:
                    shutil.copy2(found[name], destination)
                    continue
                label = '%s (%d/%d)' % (name, index, len(entries_list))
                print('steam     : downloading %s' % label, flush=True)
                try:
                    _download_steam_file('https://client-update.steamstatic.com/' + name, destination, digest,
                                         label=name, total=sizes.get(name, 0))
                except (OSError, ValueError) as first:
                    print('steam     : primary mirror failed (%s); trying the archive' % first, flush=True)
                    try:
                        _download_steam_file(STEAM_ARCHIVE_BASE + name, destination, digest,
                                             label=name, total=sizes.get(name, 0))
                    except (OSError, ValueError) as second:
                        raise ValueError('could not download %s: %s; %s. To avoid downloading, %s'
                                         % (name, first, second, STEAM_CACHE_HINT)) from second
            entries = _stage_steam_payload(packages, data, STEAM_COMPAT_BUILD, work / 'payload')
            # Keep a complete verified cache, not a copy of stale installed metadata.
            cache = steam_cache_dir()
            replacement = work / 'cache'
            prepared_stats = _package_stats(packages, with_hash=True)
            reuse_cache = (cached_client_build() == STEAM_COMPAT_BUILD
                           and _package_stats(cache / 'package', with_hash=True) == prepared_stats)
            if not reuse_cache:
                shutil.copytree(packages, replacement / 'package')
                (replacement / 'build.txt').write_text(STEAM_COMPAT_BUILD + '\n')
                write_json_file(replacement / 'manifest.json', prepared_stats)
            backup = _install_steam_payload(work / 'payload', entries, STEAM_COMPAT_BUILD, packages)
            if reuse_cache:
                write_json_file(cache / 'manifest.json', prepared_stats)
            else:
                if cache.exists():
                    os.replace(cache, backup / 'previous-cache')
                try:
                    os.replace(replacement, cache)
                except OSError:
                    if (backup / 'previous-cache').exists():
                        os.replace(backup / 'previous-cache', cache)
                    raise
            write_json_file(steam_pin_path(), new_steam_pin(STEAM_COMPAT_BUILD))
            pruned = prune_steam_client_backups()
        return True, ('installed and verified Steam client %s executables; updates blocked; backup: %s%s. '
                      'Runtime version will be confirmed on the next Steam launch.'
                      % (STEAM_COMPAT_BUILD, backup,
                         '; pruned %d old backup(s)' % pruned if pruned else ''))
    except (OSError, ValueError, lzma.LZMAError, zipfile.BadZipFile) as error:
        return False, 'Steam client installation failed (not reported as a downgrade): %s' % error


def _recover_steam_client(want):
    """Restore and verify actual cached Steam client executables for `want`.

    Returns (ok, message). Rechecks that Steam/Lumen are closed internally,
    verifies and extracts the packages, retains a rollback backup, and blocks
    self-updates. Copying package metadata alone can never report success.
    """
    if cached_client_build() != want or not (steam_cache_dir() / 'package').is_dir():
        return False, 'no cache for build %s; run: luna steam cache (Steam closed)' % want
    manifest = _cache_manifest()
    if manifest:
        cached_stats = {}
        for path in sorted((steam_cache_dir() / 'package').rglob('*')):
            if path.is_file():
                try:
                    cached_stats[str(path.relative_to(steam_cache_dir() / 'package'))] = True
                except OSError:
                    pass
        problems = [rel for rel, entry in manifest.items()
                    if not isinstance(entry, list) or len(entry) < 3]
        if problems or set(cached_stats) != set(manifest):
            return False, 'the cache is incomplete; re-run: luna steam cache (Steam closed)'
        for rel, entry in manifest.items():
            try:
                if sha256(steam_cache_dir() / 'package' / rel) != entry[2]:
                    return False, ('the cache failed its own integrity check (%s changed); '
                                     're-run: luna steam cache (Steam closed)' % rel)
            except OSError as error:
                return False, 'cannot read the cache: %s' % error
    # A package-only swap is not a recovery. Extract and verify the executables
    # first; never report success solely from build.txt or a copied manifest.
    try:
        _steam_client_closed()
        packages = steam_cache_dir() / 'package'
        data = (packages / STEAM_MANIFEST_NAME).read_bytes()
        if want == STEAM_COMPAT_BUILD and hashlib.sha256(data).hexdigest() != STEAM_COMPAT_MANIFEST_SHA256:
            raise ValueError('cached compatibility manifest SHA256 mismatch')
        with tempfile.TemporaryDirectory(prefix='steam-recover-', dir=luna_tools_dir()) as work:
            payload = Path(work) / 'payload'
            entries = _stage_steam_payload(packages, data, want, payload)
            backup = _install_steam_payload(payload, entries, want, packages)
    except (OSError, ValueError, lzma.LZMAError, zipfile.BadZipFile) as error:
        return False, 'could not recover Steam client executables: %s' % error
    pruned = prune_steam_client_backups()
    return True, ('recovered and verified Steam client %s executables; updates blocked; backup: %s%s'
                  % (want, backup, '; pruned %d old backup(s)' % pruned if pruned else ''))


def _apply_steam_update():
    """Valve-driven client update with the block lifted, then re-blocked.

    Called only with Steam closed (timer or --now). On success the local
    package cache is stale by definition and is dropped, so a later recover
    can never restore the pre-update build by accident.
    """
    ok, message = _steam_force_update()
    if not ok:
        return False, message
    try:
        shutil.rmtree(steam_cache_dir(), ignore_errors=True)
    except OSError:
        pass
    try:
        steam_pending_path().unlink()
    except OSError:
        pass
    build = steam_client_build()
    note = ('; cache is now stale and was dropped - re-pin after verifying, then re-cache'
            if not build else '; re-pin the new build %s after verifying, then re-cache' % build)
    return True, message + note


def steam_moon_state_dir():
    return home() / '.local/state/slsteam-moon'


def _find_steam_dir():
    """First Steam root that has a package/ dir, symlinks resolved."""
    candidates = [steam_home(), home() / '.local/share/Steam', home() / '.steam/steam',
                  home() / '.steam/root',
                  home() / '.var/app/com.valvesoftware.Steam/.local/share/Steam']
    for candidate in candidates:
        if (candidate / 'package').is_dir():
            return candidate.resolve()
    return None


def _steam_package_set_readonly(package, readonly):
    mode = package.stat().st_mode
    package.chmod(mode & ~0o222 if readonly else mode | stat.S_IWUSR)


def _rollback_steam_client(sdir, say):
    """Kill Steam, wipe the steamrt64 client packages and fetch the ubuntu12 client.

    Returns (ok, message). Never touches the cfg/pin; the caller locks only
    after this succeeded. The bootstrapper download is ~500 MB.
    """
    package = sdir / 'package'
    binary = sdir / 'ubuntu12_32' / 'steam'
    if not binary.is_file():
        binary = sdir / 'steam.sh'
    if not binary.is_file():
        return False, 'no Steam launcher found under %s' % sdir
    uid = str(os.getuid())
    say('stopping Steam')
    for name in ('steam', 'steamwebhelper'):
        subprocess.run(['pkill', '-9', '-u', uid, '-x', name], capture_output=True)
    time.sleep(2)
    _steam_package_set_readonly(package, False)
    for stale in package.glob('steam_client_steamrt64*'):
        stale.unlink()
    for stale in steam_moon_state_dir().glob('safe_mode*'):
        stale.unlink()
    say('downloading the ubuntu12 client (about 500 MB); this can take a while')
    # The Luna block would inhibit this very download; it is re-applied by the caller.
    try:
        subprocess.run([str(binary), '-forcemanifestsuffix', 'ubuntu12', '-exitsteam'],
                       timeout=3600)  # a non-zero exit is tolerated, as in the community script
    except (OSError, subprocess.SubprocessError) as error:
        return False, 'Steam bootstrapper failed: %s' % error
    return True, 'ubuntu12 client downloaded'


def _lock_steam_client(force, confirm):
    """`luna steam lock`: roll back to the ubuntu12 client and hard-lock updates."""
    sdir = _find_steam_dir()
    if sdir is None:
        return 1, 'no Steam installation with a package/ directory found'
    if sdir != steam_home().resolve():
        return 1, ('Steam found at %s, but Luna manages %s; refusing to lock a layout it '
                   'cannot pin' % (sdir, steam_home()))
    if read_steam_pending():
        return EXIT_REFUSED, 'a Steam task is queued; run: luna steam cancel first'
    running = [name for name in ('steam', 'steamwebhelper') if process_running(name)]
    if running and not force and not confirm():
        return EXIT_REFUSED, ('REFUSING: Steam is running and lock must kill it (kill -9, unsaved '
                              'state is lost). Close it, or re-run with --force.')

    def say(text):
        print('lock    : %s' % text, flush=True)

    # The bootstrapper must be free to download: lift Luna's block for the run.
    had_block = steam_updates_blocked() or steam_hard_lock_active()
    remove_steam_cfg_block(steam_cfg_paths())
    try:
        ok, message = _rollback_steam_client(sdir, say)
    except OSError as error:
        ok, message = False, 'rollback failed: %s' % error
    if not ok:
        if had_block:
            ensure_steam_cfg_block()
        return 1, message
    say(message)
    build = steam_client_build()
    if not build:
        if had_block:
            ensure_steam_cfg_block()
        return 1, ('rolled back, but the client build cannot be determined; launch Steam once '
                   'and re-run: luna steam lock')
    tools = luna_tools_dir()
    tools.mkdir(parents=True, exist_ok=True)
    # Pin first (carrying the lock marker) so every block/cfg helper agrees.
    pin = new_steam_pin(build)
    pin['hardLock'] = {'rollback': 'ubuntu12', 'at': int(time.time()), 'by': installed_version()}
    write_json_file(steam_pin_path(), pin)
    # The old receipt/cache describe the previous build and would read as drift.
    shutil.rmtree(steam_cache_dir(), ignore_errors=True)
    try:
        write_json_file(tools / 'steam-client-installed.json', {
            'build': build, 'at': int(time.time()), 'backup': '',
            'core': {name: sha256(sdir / _steam_payload_path(name)) for name in STEAM_CORE_FILES}})
    except (OSError, ValueError):
        try:
            (tools / 'steam-client-installed.json').unlink()
        except OSError:
            pass
    try:
        _cache_client_packages(build)
    except (OSError, ValueError) as error:
        say('warning: could not cache build %s (%s); run: luna steam cache' % (build, error))
    ensure_steam_cfg_block()
    _steam_package_set_readonly(sdir / 'package', True)
    if steam_moon_state_dir().is_dir():
        (steam_moon_state_dir() / 'boot_fail_count').write_text('0\n')
    return 0, ('Steam rolled back to the ubuntu12 client (build %s), pinned and hard-locked: '
               'Steam.cfg + steam.cfg written, package/ read-only. Undo: luna steam unlock' % build)


def adoptable_steam_lock():
    """Why a read-only package/ + pin can (or cannot) become Luna's hard lock. (ok, reason)

    Adoption only records the lock for a Steam that already is the pinned build and
    already has read-only package/ and the update block; it changes none of Steam's files.
    """
    if steam_hard_lock_active():
        return False, 'the hard lock is already recorded'
    pin = read_steam_pin()
    if not pin.get('clientBuild'):
        return False, 'no Steam pin recorded (run: luna steam pin)'
    package = steam_home() / 'package'
    if not package.is_dir():
        return False, 'no Steam package/ directory at %s' % package
    if not _package_read_only():
        return False, 'package/ is not read-only; nothing to adopt (use: luna steam lock)'
    if not steam_updates_blocked():
        return False, 'steam.cfg does not block updates (run: luna steam pin)'
    state = steam_state()
    if not state['match']:
        return False, ('Steam (build %s) does not match the pin (%s): run luna steam recover '
                       'first' % (state['build'] or '?', state['pinned']))
    return True, ''


def adopt_steam_lock():
    """`luna steam lock --adopt`: record hardLock for the pinned build as it stands.

    No rollback, no process killed, Steam's files untouched; only the pin record and
    Luna's own cfg block (both Steam.cfg and steam.cfg) are written. Undo: luna steam unlock.
    """
    ok, reason = adoptable_steam_lock()
    if not ok:
        return 1, 'cannot adopt the lock: %s' % reason
    pin = read_steam_pin()
    pin['hardLock'] = {'rollback': 'adopted', 'at': int(time.time()), 'by': installed_version()}
    write_json_file(steam_pin_path(), pin)
    ensure_steam_cfg_block()
    return 0, ('adopted the existing read-only Steam lock for build %s as Luna\'s hard lock '
               '(nothing rolled back or killed). Undo: luna steam unlock' % pin['clientBuild'])


def _notify(title, text):
    """Best-effort desktop notification; never fails the job."""
    try:
        subprocess.run(['notify-send', '-a', 'Luna', title, text], capture_output=True, timeout=10)
    except (OSError, subprocess.SubprocessError):
        pass


def _launch_steam_detached():
    try:
        subprocess.Popen(['setsid', 'steam'], stdin=subprocess.DEVNULL,
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         start_new_session=True)
        return True
    except OSError as error:
        print('could not launch Steam: %s' % error, file=sys.stderr)
        return False


def _close_steam_gracefully(timeout=90):
    """`steam -shutdown`, then wait for the client to exit. True when it is gone."""
    if not process_running('steam'):
        return True
    try:
        subprocess.run(['steam', '-shutdown'], capture_output=True, timeout=30)
    except (OSError, subprocess.SubprocessError):
        pass
    for _ in range(timeout):
        if not process_running('steam'):
            sidecar = gui_lumen_note()
            if sidecar:
                print('note: %s' % sidecar, file=sys.stderr)
            return True
        time.sleep(1)
    return False


def _unlock_steam_client(now):
    """`luna steam unlock`: undo the hard lock and the pin."""
    package = steam_home() / 'package'
    if package.is_dir():
        _steam_package_set_readonly(package, False)
        print('package/ is writable again')
    if remove_steam_cfg_block(steam_cfg_paths()):
        print('update block removed: Steam may update itself again')
    elif any(path.exists() for path in steam_cfg_paths()):
        print('note: Steam.cfg/steam.cfg left in place (they hold more than the Luna block)')
    try:
        steam_pin_path().unlink()
        print('pin and hard-lock marker removed')
    except OSError:
        print('no pin to remove')
    if now:
        if process_running('steam'):
            print('Steam is already running; restart it to let it self-update')
        else:
            try:
                subprocess.Popen(['setsid', 'steam'], stdin=subprocess.DEVNULL,
                                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                                 start_new_session=True)
                print('Steam launched; it will self-update to the latest client')
            except OSError as error:
                print('could not launch Steam: %s' % error, file=sys.stderr)
                return 1
    return EXIT_OK


def refresh_pending_path():
    return luna_tools_dir() / 'pending-refresh.json'


def read_refresh_pending():
    pending = read_json_file(refresh_pending_path())
    return pending if isinstance(pending, dict) else {}


def _refresh_steam_side():
    """Update Steam to Valve's latest, then pin and cache the new build.

    Caller guarantees Steam and the sidecar are closed. Fails closed at each
    step with the exact next action; never kills processes and never mislabels
    the cache. Returns (ok, message, build).
    """
    try:
        _steam_client_closed()
    except ValueError as error:
        return False, str(error), ''
    if read_steam_pending():
        return False, 'a Steam task is already queued; run: luna steam cancel first', ''
    ok, message = _steam_force_update()
    if not ok:
        return False, message, ''
    build = steam_client_build()
    if not build:
        return False, ('Steam updated, but the new build cannot be determined; '
                       'launch Steam once, then run: luna steam pin [--build N]'), ''
    pin = new_steam_pin(build)
    try:
        luna_tools_dir().mkdir(parents=True, exist_ok=True)
        write_json_file(steam_pin_path(), pin)
        ensure_steam_cfg_block()
        _cache_client_packages(build)
    except (OSError, ValueError) as error:
        return False, 'Steam updated to %s, but pin/cache failed: %s' % (build, error), build
    return True, 'Steam client %s updated, pinned, cached and blocked' % build, build


def cmd_refresh(options):
    """Wizard: bring Steam to Valve's latest and reinstall Luna on top.

    Steam and Lumen must already be closed (this command never kills
    anything). Steps: update, pin, cache, install add-ons keeping the new
    client, verify. Any failure stops the wizard with the exact next action.
    """
    if options.dry_run:
        print('refresh : would update Steam (closed), pin, cache, install Luna --keep-steam-client, verify')
        print('\nDRY RUN: Steam stays untouched, nothing was written.')
        return EXIT_OK
    reasons = refuse_reasons(for_install=True)
    if reasons:
        print('REFUSING to refresh:')
        for reason in reasons:
            print('  - %s' % reason)
        return EXIT_REFUSED
    ok, message, build = _refresh_steam_side()
    print('refresh : %s' % message, file=sys.stdout if ok else sys.stderr)
    if not ok:
        return 1
    install_options = argparse.Namespace(only=[], force=False, dry_run=False,
                                         keep_steam_client=True, no_steam_machine=False,
                                         migrate_steam_machine=False)
    code = cmd_install(install_options)
    if code != EXIT_OK:
        print('refresh : Steam is on %s, but the Luna install needs attention (exit %d)'
              % (build, code), file=sys.stderr)
        return code
    verify_options = argparse.Namespace(sources=False, source_dir=None)
    code = cmd_verify(verify_options)
    if code != EXIT_OK:
        print('refresh : installed, but verification failed (exit %d)' % code, file=sys.stderr)
        return code
    print('\nrefresh : Steam %s + Luna installed and verified. Restart Steam to load the add-ons.' % build)
    return EXIT_OK


def cmd_steam(options):
    """Pin, cache and recover the Steam client build (see `luna steam --help`)."""
    action = getattr(options, 'steam_action', '') or 'status'
    if action == 'status':
        state = steam_state()
        print('client : %s' % (state['build'] or 'unknown (Steam never logged a version here)'))
        print('pinned : %s' % (state['pinned'] or 'none (run: luna steam pin)'))
        print('packages: %s' % ('match the pin' if state['match']
                                 else 'DIFFER from the pin - run: luna steam recover (Steam closed)'
                                 if state['pinned'] and state['cacheReady']
                                 else 'unknown (no cache)'))
        print('updates: %s' % ('blocked (steam.cfg)' if state['updatesBlocked'] else 'NOT blocked'))
        if state['hardLock']:
            print('lock   : HARD (ubuntu12 rollback, package/ %s)'
                  % ('read-only' if state['packageReadOnly']
                     else 'WRITABLE - re-run: luna steam lock'))
        if state['pacmanManaged']:
            print('pacman : Steam is system-managed%s'
                  % (', ignored on updates' if state['pacmanIgnored']
                     else ' and NOT ignored - add "IgnorePkg = steam" to /etc/pacman.conf (needs sudo)'))
        for name, digest in sorted(state['slssteam'].items()):
            print('%-16s %s' % (name + ':', digest[:12] if digest else '(missing)'))
        if state['slssteamDrift']:
            print('WARN   : SLSsteam changed since the pin: %s' % ', '.join(state['slssteamDrift']))
        print('cache  : %s' % ('build ' + state['cachedBuild'] if state['cacheReady']
                                else 'empty (run: luna steam cache with Steam closed)'))
        pending = read_steam_pending()
        if pending:
            print('queued : %s (requested %s; timer applies it while Steam is closed, or: luna steam cancel)'
                  % (pending.get('action', '?'),
                     time.strftime('%Y-%m-%d %H:%M', time.localtime(int(pending.get('at') or 0)))))
        return EXIT_OK
    if action == 'pin':
        build = options.build or steam_client_build()
        if not build:
            print('cannot determine the client build; pass --build N explicitly', file=sys.stderr)
            return 2
        pin = new_steam_pin(build)
        luna_tools_dir().mkdir(parents=True, exist_ok=True)
        write_json_file(steam_pin_path(), pin)
        ensure_steam_cfg_block()
        print('pinned Steam client %s with current SLSsteam hashes; updates blocked via steam.cfg' % build)
        return EXIT_OK
    if action == 'lock' and getattr(options, 'adopt', False):
        code, message = adopt_steam_lock()
        print(message, file=sys.stdout if code == 0 else sys.stderr)
        return code
    if action == 'lock':
        def confirm():
            if not sys.stdin.isatty():
                return False
            blockers = gui_describe_blockers()  # best effort; '' when unavailable
            if blockers:
                print('Steam currently shows: %s' % blockers)
            answer = input('Steam is running and will be killed (kill -9). Continue? [y/N] ')
            return answer.strip().lower() in ('y', 'yes')
        code, message = _lock_steam_client(getattr(options, 'force', False), confirm)
        print(message, file=sys.stdout if code == 0 else sys.stderr)
        if getattr(options, 'relaunch', False):
            # Detached-job mode (in-Steam UI): report, then bring Steam back even on failure.
            _notify('Luna: Steam updates blocked' if code == 0 else 'Luna: could not block Steam updates',
                    message[:200])
            _launch_steam_detached()
        return code
    if action == 'unlock':
        if getattr(options, 'relaunch', False):
            # Close Steam first so the next start runs the bootstrapper and self-updates.
            if not _close_steam_gracefully():
                print('Steam did not close in time; nothing was changed', file=sys.stderr)
                _notify('Luna: Steam update not started', 'Steam did not close; try again.')
                return 1
            code = _unlock_steam_client(False)
            if code == EXIT_OK:
                _notify('Luna: Steam unblocked', 'Steam is restarting and will update to the latest client.')
                _launch_steam_detached()
            else:
                _notify('Luna: could not unblock Steam', 'See the Luna steam job log.')
            return code
        return _unlock_steam_client(getattr(options, 'now', False))
    if action == 'unpin':
        if steam_hard_lock_active():
            print('the hard lock is active (package/ read-only); run: luna steam unlock',
                  file=sys.stderr)
            return 1
        try:
            steam_pin_path().unlink()
            print('pin removed')
        except OSError:
            print('no pin to remove')
        if remove_steam_cfg_block():
            print('update block removed: Steam may update itself again')
        else:
            print('note: steam.cfg left untouched (it holds more than the Luna block)')
        return EXIT_OK
    if action == 'cache':
        if process_running('steam') or process_running('steamwebhelper'):
            # Queue it: the timer runs while Steam is closed and caches then.
            existing = read_steam_pending()
            if existing:
                print('a Steam task is already queued (%s); run: luna steam cancel first'
                      % existing.get('action', '?'), file=sys.stderr)
                return 1
            write_json_file(steam_pending_path(), {'action': 'cache', 'at': int(time.time())})
            print('Steam is running: caching queued for the next closed-Steam window')
            return EXIT_OK
        source = steam_home() / 'package'
        if not source.is_dir():
            print('no Steam package directory to cache at %s' % source, file=sys.stderr)
            return 1
        build = str(options.build or '') or steam_client_build()
        if not build or build == '0':
            print('cannot determine the client build; launch Steam once, then retry', file=sys.stderr)
            return 1
        try:
            cache = _cache_client_packages(build)
        except (OSError, ValueError) as error:
            print('cannot cache the Steam client: %s' % error, file=sys.stderr)
            return 1
        print('cached Steam client %s (%s)' % (build, cache))
        return EXIT_OK
    if action == 'update':
        # The blessed path for a Steam client update: queue it here (menu or
        # shell); the timer applies it while Steam is closed, then re-blocks.
        # --now applies it right away instead (Steam must already be closed).
        if steam_hard_lock_active():
            print('the hard lock is active; run: luna steam unlock --now to let Steam update',
                  file=sys.stderr)
            return 1
        if getattr(options, 'now', False):
            if process_running('steam') or process_running('steamwebhelper') or process_running('lumen'):
                print('REFUSING: Steam or the Lumen sidecar is running. '
                      'Close it completely (Steam -> Exit) first.')
                return EXIT_REFUSED
            ok, message = _apply_steam_update()
            print(message, file=sys.stderr if not ok else sys.stdout)
            return EXIT_OK if ok else 1
        existing = read_steam_pending()
        if existing:
            print('a Steam task is already queued (%s); run: luna steam cancel first'
                  % existing.get('action', '?'), file=sys.stderr)
            return 1
        write_json_file(steam_pending_path(), {'action': 'update', 'at': int(time.time())})
        if process_running('steam') or process_running('steamwebhelper'):
            print('Steam update queued: it applies the next time Steam is closed '
                  '(timer), then updates are blocked again')
        else:
            print('Steam update queued: enable the timer or run: luna steam update --now')
        return EXIT_OK
    if action == 'cancel':
        try:
            steam_pending_path().unlink()
            print('queued Steam task cancelled')
        except OSError:
            print('nothing queued')
        return EXIT_OK
    if action == 'recover':
        if process_running('steam') or process_running('steamwebhelper') or process_running('lumen'):
            print('REFUSING to recover: Steam or the Lumen sidecar is running. '
                  'Close it completely (Steam -> Exit) first.')
            return EXIT_REFUSED
        want = str(options.build or '')
        pin = read_steam_pin()
        if not want:
            want = str(pin.get('clientBuild') or '')
        if not want:
            print('nothing pinned; run: luna steam pin [--build N]', file=sys.stderr)
            return 2
        ok, message = _recover_steam_client(want)
        if not ok:
            print(message, file=sys.stderr)
            return 1
        print(message)
        print('launch Steam and verify, then run: luna steam pin')
        return EXIT_OK
    print('unknown steam action: %s (status|pin|unpin|cache|recover|update|cancel|lock|unlock)' % action, file=sys.stderr)
    return 2


def steam_drift_note():
    """One-line summary for preflight/Health, or '' when nothing is wrong."""
    state = steam_state()
    if state.get('binariesMatch') is False:
        return 'Steam client executables changed; close Steam and run: luna steam recover'
    if state['pinned'] and state['cacheReady'] and state['packagesMatch'] is False:
        return ('Steam client packages changed since the pin; close Steam and run: luna steam recover')
    if state['slssteamDrift']:
        return ('SLSsteam changed since the pin (%s); re-pin after verifying: luna steam pin'
                % ', '.join(state['slssteamDrift']))
    if state['pinned'] and state['pacmanManaged'] and not state['pacmanIgnored']:
        return ('Steam is pacman-managed and not ignored: a system update can replace the launcher; '
                'add "IgnorePkg = steam" under [options] in /etc/pacman.conf (needs sudo)')
    if state['pinned'] and not state['updatesBlocked']:
        return 'a Steam build is pinned but updates are not blocked; run: luna steam recover or re-add steam.cfg'
    if state['pinned'] and not state['cacheReady'] and state['build'] and state['build'] != state['pinned']:
        return ('Steam client %s does not match the pin %s and no cache exists; '
                'cache a known-good build: luna steam cache (Steam closed)'
                % (state['build'], state['pinned']))
    return ''


def cmd_install(options):
    targets = selected_addons(options)
    reasons = refuse_reasons(for_install=True)
    if reasons:
        print('REFUSING to install:')
        for reason in reasons:
            print('  - %s' % reason)
        return EXIT_REFUSED
    check = patcher('check')
    if check.returncode != 0:
        print('REFUSING to install: %s' % (check.stderr.strip() or check.stdout.strip()), file=sys.stderr)
        return EXIT_PATCH
    rows = plan(targets)
    to_write = [row for row in rows if row[4] in ('new', 'differs')]
    # A base (Lumen/Moon) update replaces boot.lua and wipes the bridge while
    # the payloads stay current. That is not "nothing to do": reinstalling the
    # bridge is part of every install, or Luna silently leaves the menu.
    needs_bridge = 'bridge compatible, not installed' in check.stdout
    print('plan for %s:' % ', '.join(targets))
    for addon, label, source, dest, state in rows:
        print('  %-9s %-22s %s' % (addon, label, state))
    if needs_bridge:
        print('  bridge    boot.lua               reinstall (a base update wiped it)')
    if options.dry_run:
        if not getattr(options, 'no_steam_machine', False):
            code = steam_machine_action('install', dry_run=True,
                                        migrate=getattr(options, 'migrate_steam_machine', False))
            if code:
                return code
        needed, why = steam_client_needed(options)
        if needed:
            print('steam     : would install/verify build %s executables, cache, pin and block updates (%s)'
                  % (STEAM_COMPAT_BUILD, why))
            print('steam     : %s' % steam_client_summary(getattr(options, 'client_cache', None)))
        else:
            print('steam     : Steam client untouched (%s)' % why)
        print('\nDRY RUN: %d file(s) would change%s.' % (len(to_write),
              ' + bridge reinstall' if needs_bridge else ', nothing was written'))
        return EXIT_OK
    differing = [row for row in to_write if row[4] == 'differs']
    if differing and not options.force:
        print('\nREFUSING to overwrite %d file(s) that differ from the pinned payloads:' % len(differing))
        for addon, label, source, dest, state in differing:
            print('  %s/%s (installed %s)' % (addon, label, dest))
        print('Re-run with --force if you really want to replace them.')
        return EXIT_NEEDS_FORCE

    touch_client, why = steam_client_needed(options)
    if touch_client:
        print('steam     : installing client build %s (%s)' % (STEAM_COMPAT_BUILD, why), flush=True)
        ok, message = ensure_compatible_steam(getattr(options, 'client_cache', None))
        print('steam     : %s' % message, file=sys.stdout if ok else sys.stderr)
        if not ok:
            return 1
    else:
        print('steam     : client untouched (%s)' % why)
    if not to_write and not needs_bridge:
        if not getattr(options, 'no_steam_machine', False):
            code = steam_machine_action('install', migrate=getattr(options, 'migrate_steam_machine', False))
            if code:
                return code
        write_install_snapshot()
        write_tooling()
        arm_lumen_hook()
        if read_steam_pin():
            ensure_steam_cfg_block()
        print('\nAlready installed and identical to the pinned payloads. Nothing to do.')
        return EXIT_OK
    only_bridge = needs_bridge and not to_write

    apply = Apply()
    try:
        apply.mkdir(addons_dir())
        for addon, label, source, dest, state in rows:
            if state in ('new', 'differs'):
                apply.write(source, dest)
        result = patcher('install')
        if result.returncode != 0:
            raise RuntimeError('boot.lua patch failed: %s' % (result.stderr.strip() or result.stdout.strip()))
        apply.did_patch = True
    except Exception as error:  # noqa: BLE001 - report and undo whatever was done
        apply.rollback()
        print('FAILED: %s' % error, file=sys.stderr)
        print('Every add-on change made by this run was rolled back.', file=sys.stderr)
        if touch_client:
            print('The separately verified Steam client installation remains in place; '
                  'its rollback backup was retained.', file=sys.stderr)
        return 1

    write_install_snapshot()
    write_tooling()
    arm_lumen_hook()
    if not getattr(options, 'no_steam_machine', False):
        code = steam_machine_action('install', migrate=getattr(options, 'migrate_steam_machine', False))
        if code:
            print('Add-ons installed, but SteamOS Mode shortcuts need attention; no custom launchers were overwritten.', file=sys.stderr)
            return code
    if read_steam_pin():
        # Base installers drop steam.cfg; a pin means updates must stay
        # blocked, so re-apply Luna's block right away (Steam is closed here).
        ensure_steam_cfg_block()
        print('steam.cfg : update block re-applied (a Steam build is pinned)')
    print('\ninstalled: %s' % ', '.join('%s %s' % (name, addon_version(name)) for name in targets))
    if only_bridge:
        print('bridge   : reinstalled into boot.lua (payloads were already current)')
    print('bridge   : %s' % (addons_dir() / 'bridge.lua'))
    print('boot.lua : %s' % patcher('check').stdout.strip())
    print('\nRestart Steam (Steam -> Exit, then launch it again) to load the add-ons.')
    hint = gui_install_hint()
    if hint:
        print(hint)
    return EXIT_OK


def cmd_uninstall(options):
    reasons = refuse_reasons(for_install=False)
    if reasons:
        print('REFUSING to uninstall:')
        for reason in reasons:
            print('  - %s' % reason)
        return EXIT_REFUSED
    targets = selected_addons(options) if options.only else installed_addons()
    if not targets:
        print('Nothing installed for the selected add-ons.')
        return EXIT_OK
    remaining = tuple(name for name in installed_addons() if name not in targets)
    hook_config = home() / '.local/share/slssteam-luna/config.json'
    if 'luna' in targets and hook_config.is_file() and (read_json_file(hook_config) or {}).get('enabled'):
        if lumen_hook('disable'):
            print('REFUSING uninstall: could not safely disable automatic Lumen recovery.', file=sys.stderr)
            return EXIT_PATCH
    if remaining:
        for name in targets:
            shutil.rmtree(addons_dir() / name, ignore_errors=True)
            print('removed %s; %s still installed, bridge and boot.lua left in place'
                  % (name, ', '.join(remaining)))
        return EXIT_OK
    # Last one out: restore Lumen before deleting the payload it points at, so a
    # failed restore can never leave a live bridge aiming at removed files.
    result = patcher('uninstall')
    if result.returncode != 0:
        print('REFUSING to remove the last add-on: %s'
              % (result.stderr.strip() or result.stdout.strip()), file=sys.stderr)
        return EXIT_PATCH
    print(result.stdout.strip())
    for name in targets:
        shutil.rmtree(addons_dir() / name, ignore_errors=True)
        print('removed %s' % name)
    bridge = addons_dir() / 'bridge.lua'
    if bridge.is_file():
        bridge.unlink()
        print('removed bridge.lua')
    snapshot = addons_dir() / 'luna-manifest.json'
    if snapshot.is_file():
        snapshot.unlink()
    # A full uninstall must not leave the unattended worker behind: without
    # the payloads it would only fail, and with them gone a timer could
    # reinstall after the user asked for removal.
    try:
        unit_dir, service, timer = unit_paths()
        subprocess.run(['systemctl', '--user', 'disable', '--now', 'luna-autoupdate.timer'],
                       capture_output=True)
        for path in (timer, service):
            try:
                if path.exists():
                    path.unlink()
            except OSError:
                pass
        subprocess.run(['systemctl', '--user', 'daemon-reload'], capture_output=True)
        pending = luna_tools_dir() / 'pending.json'
        try:
            if pending.exists():
                pending.unlink()
        except OSError:
            pass
        print('unattended updates: disabled and queued updates cleared')
    except Exception:  # noqa: BLE001 - uninstall must succeed even if systemd is absent
        pass
    print('Local playtime and presence data were left untouched.')
    launcher = home() / '.local/bin/luna'
    if launcher.is_file() and not launcher.is_symlink() and launcher.read_bytes() == CLI_LAUNCHER.encode():
        launcher.unlink()
    if steam_machine_action('uninstall'):
        print('Some SteamOS Mode shortcuts could not be removed; custom edits were preserved.', file=sys.stderr)
    return EXIT_OK


def untraceable_pins(manifest):
    """Pins whose source_commit is not a commit id, so the bytes cannot be traced."""
    found = []
    for section in ('shared', 'addons'):
        for name, entry in sorted(manifest.get(section, {}).items()):
            commit = str(entry.get('source_commit', ''))
            if not re.fullmatch(r'[0-9a-f]{40}', commit):
                found.append('%s (%s)' % (name, commit or 'no commit'))
    return found


def warn_untraceable(manifest, stream=sys.stdout):
    found = untraceable_pins(manifest)
    if found:
        print('\nWARNING: pinned to no commit, so these bytes cannot be traced to a source '
              'revision: %s. Commit the source and re-run vendor.' % ', '.join(found), file=stream)


def cmd_verify(options):
    manifest = load_manifest()
    problems = []
    checked = 0
    expected = {}
    for name in ADDONS:
        entry = manifest.get('addons', {}).get(name)
        if not entry:
            problems.append('manifest has no entry for %s' % name)
            continue
        expected_paths = set()
        for rel, meta in entry.get('files', {}).items():
            path = payload_path(name, meta['source_path'])
            expected_paths.add(path)
            if not path.is_file():
                problems.append('missing payload %s/%s' % (name, rel))
                continue
            if sha256(path) != meta['sha256']:
                problems.append('payload %s/%s does not match the manifest' % (name, rel))
            else:
                checked += 1
        expected[name] = expected_paths
    for rel, meta in manifest.get('shared', {}).items():
        path = ROOT / rel
        if not path.is_file():
            problems.append('missing shared file %s' % rel)
            continue
        if sha256(path) != meta['sha256']:
            problems.append('shared file %s does not match the manifest' % rel)
        else:
            checked += 1
    # A payload directory must contain exactly what the manifest lists, otherwise
    # a removed or renamed file could survive in the checkout unnoticed.
    for name, expected_paths in expected.items():
        directory = ROOT / 'addons' / name
        for path in sorted(directory.rglob('*')):
            if path.is_file() and path not in expected_paths:
                problems.append('unexpected file in the payload: %s' % path.relative_to(ROOT))
    print('manifest   : %d file(s) verified, generated %s' % (checked, manifest.get('generated', '?')))
    for name in ADDONS:
        entry = manifest.get('addons', {}).get(name, {})
        print('  %-9s %s %s @ %s' % (name, entry.get('plugin_version', '?'),
                                     entry.get('source_repo', '?'), entry.get('source_commit', '?')[:12]))
    if options.sources:
        for name, entry in manifest.get('addons', {}).items():
            if name not in SOURCED:
                continue
            base = Path(options.source_dir) if options.source_dir else (home() / 'Documents/Scripts')
            source = base / ('slsteam-' + name)
            # A plain copy is fine; a git checkout is not required to compare bytes.
            if not source.is_dir():
                print('  skip %s: no source checkout at %s' % (name, source))
                continue
            for rel, meta in entry.get('files', {}).items():
                origin = source / meta['source_path']
                if not origin.is_file():
                    problems.append('%s: source file missing: %s' % (name, origin))
                elif sha256(origin) != meta['sha256']:
                    problems.append('%s: %s differs from the source checkout (re-run vendor)'
                                    % (name, meta['source_path']))
            print('  %-9s compared against %s' % (name, source))
    if problems:
        print('\nPROBLEMS:')
        for problem in problems:
            print('  - %s' % problem)
        return 1
    warn_untraceable(manifest)
    print('\nOK: the payloads match the manifest.')
    return EXIT_OK


def cmd_vendor(options):
    # --only re-pins the named add-ons and keeps every other manifest entry as
    # it is, so refreshing one payload never silently moves the others.
    only = set(selected_addons(options)) if options.only else None
    sources = {}
    for name in SOURCED:
        if only is not None and name not in only:
            continue
        source = Path(options.source_dir or (home() / 'Documents/Scripts' / ('slsteam-' + name)))
        if not (source / '.git').is_dir():
            print('FAIL: no git checkout for %s at %s (pass --source-dir)' % (name, source), file=sys.stderr)
            return 1
        sources[name] = source

    def head(source):
        return subprocess.run(['git', '-C', str(source), 'rev-parse', 'HEAD'],
                              capture_output=True, text=True).stdout.strip()

    def show(source, commit, path):
        result = subprocess.run(['git', '-C', str(source), 'show', '%s:%s' % (commit, path)],
                                capture_output=True)
        if result.returncode != 0:
            raise SystemExit('FAIL: %s has no %s at %s' % (source, path, commit[:12]))
        return result.stdout

    def archive(source, commit, paths, dest):
        if dest.exists():
            shutil.rmtree(dest)
        dest.mkdir(parents=True, exist_ok=True)
        producer = subprocess.Popen(['git', '-C', str(source), 'archive', '--format=tar', commit, '--'] + list(paths),
                                    stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        consumer = subprocess.Popen(['tar', '-x', '-C', str(dest)], stdin=producer.stdout,
                                    stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        producer.stdout.close()
        consumer.communicate()
        producer.wait()
        if producer.returncode != 0 or consumer.returncode != 0:
            raise SystemExit('FAIL: git archive from %s failed: %s'
                             % (source, producer.stderr.read().decode(errors='replace')))

    generated = time.strftime('%Y-%m-%dT%H:%M:%S%z')
    if only is None:
        manifest = {'generated': generated, 'shared': {}, 'addons': {}}
    else:
        manifest = json.loads(MANIFEST_PATH.read_text())
        manifest['generated'] = generated
    repo_commit = subprocess.run(['git', '-C', str(ROOT), 'rev-parse', 'HEAD'],
                                 capture_output=True, text=True).stdout.strip()
    if only is None:
        vendor_shared(manifest, sources['playtime'], head, show, repo_commit)
    # First-party add-ons come from this repository, so they are pinned to this
    # checkout's HEAD - and only when the bytes are HEAD's, so a pin always names
    # a commit that really contains them.
    for name in FIRST_PARTY:
        if only is not None and name not in only:
            continue
        files = {}
        for source_rel, dest_rel in ADDON_FILES[name]:
            path = payload_path(name, source_rel)
            if not path.is_file():
                raise SystemExit('FAIL: this repository has no addons/%s/%s' % (name, source_rel))
            rel = path.relative_to(ROOT).as_posix()
            committed = subprocess.run(['git', '-C', str(ROOT), 'show', '%s:%s' % (repo_commit, rel)],
                                       capture_output=True)
            if committed.returncode != 0 or committed.stdout != path.read_bytes():
                raise SystemExit('FAIL: %s differs from HEAD; commit it before pinning' % rel)
            files[dest_rel] = {'source_path': source_rel, 'sha256': sha256(path)}
        manifest['addons'][name] = {
            'source_repo': 'https://github.com/pgm1207/Luna',
            'source_commit': repo_commit,
            'plugin_version': addon_version(name),
            'files': files,
        }
        print('pinned addons/%s from this repository@%s (%d files)' % (name, repo_commit[:12], len(files)))
    for name, source in sources.items():
        commit = head(source)
        paths = sorted({source_path for source_path, _ in ADDON_FILES[name]})
        archive(source, commit, paths, ROOT / 'addons' / name)
        files = {}
        for source_rel, dest_rel in ADDON_FILES[name]:
            path = payload_path(name, source_rel)
            if not path.is_file():
                raise SystemExit('FAIL: %s did not produce %s' % (name, source_rel))
            files[dest_rel] = {'source_path': source_rel, 'sha256': sha256(path)}
        manifest['addons'][name] = {
            'source_repo': 'https://github.com/pgm1207/slsteam-' + name,
            'source_commit': commit,
            'plugin_version': addon_version(name),
            'files': files,
        }
        print('pinned addons/%s from %s@%s (%d files)' % (name, source.name, commit[:12], len(files)))
    MANIFEST_PATH.parent.mkdir(parents=True, exist_ok=True)
    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2, sort_keys=True) + '\n')
    print('wrote %s' % MANIFEST_PATH)
    return EXIT_OK


def vendor_shared(manifest, shared_source, head, show, repo_commit):
    # The shared bridge and patcher come from the playtime project; both projects
    # ship byte-identical copies, and `verify --sources` keeps them honest.
    shared_commit = head(shared_source)
    for rel, source_path in (('bridge/bridge.lua', 'bridge/bridge.lua'),
                             ('scripts/patch-lumen.py', 'scripts/patch-lumen.py')):
        (ROOT / rel).write_bytes(show(shared_source, shared_commit, source_path))
        manifest['shared'][rel] = {'source_repo': 'https://github.com/pgm1207/slsteam-playtime',
                                   'source_commit': shared_commit, 'source_path': source_path,
                                   'sha256': sha256(ROOT / rel)}
        print('pinned %s from %s@%s' % (rel, shared_source.name, shared_commit[:12]))
    # First-party scripts come from this repository, pinned to its HEAD.
    manifest['shared']['scripts/steam-machine.py'] = {
        'source_repo': 'https://github.com/pgm1207/Luna', 'source_commit': repo_commit,
        'source_path': 'scripts/steam-machine.py', 'sha256': sha256(ROOT / 'scripts/steam-machine.py')}
    hook_rel = 'scripts/lumen-hook.py'
    committed_hook = subprocess.run(['git', '-C', str(ROOT), 'show', repo_commit + ':' + hook_rel],
                                    capture_output=True)
    hook_clean = committed_hook.returncode == 0 and committed_hook.stdout == (ROOT / hook_rel).read_bytes()
    manifest['shared'][hook_rel] = {
        'source_repo': 'https://github.com/pgm1207/Luna',
        'source_commit': repo_commit if hook_clean else 'uncommitted-worktree',
        'source_path': hook_rel, 'sha256': sha256(ROOT / hook_rel)}


def steam_machine_action(action, dry_run=False, migrate=False):
    script = ROOT / 'scripts/steam-machine.py'
    if not script.is_file():
        script = luna_tools_dir() / 'steam-machine.py'
    if not script.is_file():
        if action == 'uninstall':
            return EXIT_OK
        print('Steam Machine helper missing; reinstall Luna from a complete bundle.', file=sys.stderr)
        return 1
    command = [sys.executable, str(script), action]
    if dry_run:
        command.append('--dry-run')
    if migrate:
        command.append('--migrate-legacy')
    return subprocess.run(command).returncode


def cmd_launchers(options):
    return steam_machine_action('install', options.dry_run, options.migrate_legacy)


# --------------------------------------------------------------------------- fleet
# `luna fleet`: see and manage Luna on several machines over SSH. Hostnames
# reach ssh/rsync/scp as argv only (never through a shell string), remote
# scripts go to `bash -s` on stdin (the remote login shell may be fish), and
# every connection is BatchMode with a connect timeout, so a dead host cannot
# hang the command or prompt for a password.

FLEET_HOST_RE = re.compile(r'(?:[A-Za-z0-9_][A-Za-z0-9_.-]*@)?[A-Za-z0-9][A-Za-z0-9._-]*')  # use fullmatch: `$` also matches before a trailing newline
# What `mktemp -d "${TMPDIR:-/tmp}/luna-fleet.XXXXXX"` may answer; it goes into single-quoted remote scripts.
FLEET_REMOTE_DIR_RE = re.compile(r'/[A-Za-z0-9._/-]+/luna-fleet\.[A-Za-z0-9]{6,}')
FLEET_BUNDLE_NAME_RE = re.compile(r'luna-[A-Za-z0-9._-]+\.tar\.gz')
FLEET_BLOB_RE = re.compile(r'[A-Za-z0-9+/]{68}')
FLEET_SSH_OPTS = ('-o', 'BatchMode=yes', '-o', 'ConnectTimeout=8',
                  '-o', 'ServerAliveInterval=10', '-o', 'ServerAliveCountMax=3')
FLEET_REMOTE_LUNA = '$HOME/.local/share/Lumen/sls-luna/luna.py'
FLEET_REMOTE_CACHE = '.local/share/Lumen/sls-luna/steam-client-cache'  # relative to $HOME


def fleet_config_path():
    override = os.environ.get('LUNA_FLEET_CONFIG')
    if override:
        return Path(override).expanduser()
    base = os.environ.get('XDG_CONFIG_HOME') or str(home() / '.config')
    return Path(base) / 'luna' / 'fleet.json'


def fleet_valid_host(host):
    return isinstance(host, str) and len(host) <= 253 and bool(FLEET_HOST_RE.fullmatch(host))


def fleet_load_hosts():
    data = read_json_file(fleet_config_path())
    hosts = data.get('hosts') if isinstance(data, dict) else None
    result = []
    for host in hosts if isinstance(hosts, list) else []:
        if fleet_valid_host(host) and host not in result:
            result.append(host)
    return result


def fleet_save_hosts(hosts):
    write_json_file(fleet_config_path(), {'hosts': list(hosts)})


def fleet_ssh(host, script, timeout=120):
    """Run a bash script on HOST over ssh. Returns (code, stdout, stderr); code 255 = ssh failed."""
    command = ['ssh'] + list(FLEET_SSH_OPTS) + ['--', host, 'bash', '-s']
    try:
        result = subprocess.run(command, input=script, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return 255, '', 'timed out after %ds' % timeout
    except OSError as error:
        return 255, '', str(error)
    return result.returncode, result.stdout, result.stderr


def probe_data():
    """Machine-readable state of THIS machine's Luna install (works from the installed copy:
    needs no checkout). Drift = an installed add-on file differs from its pin."""
    snapshot = read_json_file(addons_dir() / 'luna-manifest.json') or {}
    snap_files = snapshot.get('files') if isinstance(snapshot.get('files'), dict) else {}
    manifest = {}
    if MANIFEST_PATH.is_file():
        try:
            manifest = json.loads(MANIFEST_PATH.read_text())
        except ValueError:
            manifest = {}
    installed = installed_addons()
    addons = {}
    for name in ADDONS:
        if name not in installed:
            addons[name] = 'absent'
            continue
        # What the installer recorded wins (that is what drift is measured from);
        # a checkout's MANIFEST is the fallback for installs that predate the snapshot.
        pins = dict(snap_files.get(name) or {})
        if not pins:
            pins = {rel: meta.get('sha256', '') for rel, meta in
                    ((manifest.get('addons') or {}).get(name) or {}).get('files', {}).items()}
        if not pins:
            addons[name] = 'unknown'
            continue
        state = 'match'
        for rel, expected in pins.items():
            path = addons_dir() / name / rel
            if not path.is_file():
                state = 'missing'
                break
            try:
                if sha256(path) != expected:
                    state = 'drift'
            except OSError:
                state = 'missing'
                break
        addons[name] = state
    script = luna_tools_dir() / 'luna.py'
    if not script.is_file():
        script = Path(__file__).resolve()
    steam = steam_state()
    versions = snapshot.get('versions') if isinstance(snapshot.get('versions'), dict) else {}
    try:
        games = games_probe_block()  # additive (93_games.py); older readers ignore it
    except Exception:  # a broken library must not hide the rest of the probe
        games = None
    return {
        'games': games,
        'schema': 1,
        'lunaVersion': str(versions.get('luna') or addon_version('luna')),
        'lunaSha': sha256(script),
        'source': str(snapshot.get('source') or ''),
        'versions': versions,
        'sources': snapshot.get('sources') if isinstance(snapshot.get('sources'), dict) else {},
        'addons': addons,
        'payloadsMatch': all(state in ('match', 'absent') for state in addons.values())
                         and any(state == 'match' for state in addons.values()),
        'steam': {key: steam[key] for key in ('build', 'pinned', 'match', 'packagesMatch', 'updatesBlocked',
                                                 'hardLock', 'cachedBuild', 'cacheReady')},
        'steamRunning': process_running('steam') or process_running('steamwebhelper'),
        'lumenRunning': process_running('lumen'),
        'proton': [t['name'] for t in proton_installed()],
    }


def cmd_probe(options):
    data = probe_data()
    if options.json:
        print(json.dumps(data, sort_keys=True))
    else:
        for key, value in sorted(data.items()):
            print('%-14s %s' % (key, value))
    return EXIT_OK


FLEET_STATUS_SCRIPT = r'''
p="$HOME/.local/share/Lumen/sls-luna/luna.py"
if [ ! -f "$p" ]; then echo NOLUNA; exit 0; fi
echo "SHA $(sha256sum "$p" | cut -d' ' -f1)"
s=0; l=0
pgrep -u "$(id -u)" -x steam >/dev/null && s=1
pgrep -u "$(id -u)" -x steamwebhelper >/dev/null && s=1
pgrep -u "$(id -u)" -x lumen >/dev/null && l=1
echo "STEAMRUN $s"
echo "LUMENRUN $l"
if out=$(python3 "$p" probe --json 2>/dev/null) && [ -n "$out" ]; then
  echo "PROBE $out"
else
  echo LEGACY
  python3 "$p" steam status 2>/dev/null | sed 's/^/ST /'
fi
# doctor exits 1/2 when it has findings, so only its output decides support
d=$(python3 "$p" doctor --json 2>/dev/null | tr -d '\n')
case "$d" in "{"*) echo "DOCTOR $d";; esac
'''


def fleet_parse_status(code, out, err):
    """Turn the remote status script's output into a host record."""
    if code == 255:
        return {'reachable': False, 'error': (err.strip().splitlines() or ['ssh failed'])[-1]}
    record = {'reachable': True}
    legacy_lines = []
    for line in out.splitlines():
        tag, _, rest = line.partition(' ')
        if tag == 'NOLUNA':
            record['installed'] = False
            return record
        if tag == 'SHA':
            record['lunaSha'] = rest.strip()
        elif tag == 'STEAMRUN':
            record['steamRunning'] = rest.strip() == '1'
        elif tag == 'LUMENRUN':
            record['lumenRunning'] = rest.strip() == '1'
        elif tag == 'PROBE':
            try:
                probe = json.loads(rest)
            except ValueError:
                continue
            if isinstance(probe, dict):
                seen = {key: record.get(key) for key in ('steamRunning', 'lumenRunning')}
                record.update(probe)
                for key, value in seen.items():
                    if value is not None:
                        record[key] = value or bool(probe.get(key))
                record['installed'] = True
        elif tag == 'DOCTOR':
            try:
                report = json.loads(rest)
            except ValueError:
                continue
            if isinstance(report, dict) and isinstance(report.get('findings'), list):
                record['doctor'] = doctor_summary(report['findings'])
        elif tag == 'LEGACY':
            record['legacy'] = True
        elif tag == 'ST':
            legacy_lines.append(rest)
    if record.get('legacy'):
        record['installed'] = True
        steam = {}
        for line in legacy_lines:
            key, _, value = line.partition(':')
            key, value = key.strip(), value.strip()
            if key == 'client':
                steam['build'] = value
            elif key == 'pinned':
                steam['pinned'] = '' if value.startswith('none') else value
            elif key == 'packages':
                steam['packagesMatch'] = True if value.startswith('match') else (
                    False if value.startswith('DIFFER') else None)
            elif key == 'updates':
                steam['updatesBlocked'] = value.startswith('blocked')
            elif key == 'lock':
                steam['hardLock'] = value.startswith('HARD')
        record['steam'] = steam
    elif 'installed' not in record:
        record['installed'] = bool(record.get('lunaSha'))
    return record


def fleet_collect(host):
    """Status record for one host name, or for this machine when host is None."""
    if host is None:
        record = probe_data()
        record['reachable'] = True
        record['installed'] = True
        record['host'] = os.uname().nodename
        record['local'] = True
        try:
            record['doctor'] = doctor_summary(doctor_findings())
        except Exception:  # a broken check must not hide the fleet table
            pass
        return record
    code, out, err = fleet_ssh(host, FLEET_STATUS_SCRIPT)
    record = fleet_parse_status(code, out, err)
    record['host'] = host
    record['local'] = False
    return record


def fleet_notes(records):
    """Cross-host findings, relative to this machine (the first record)."""
    notes = []
    reference = records[0] if records else {}
    for record in records:
        if not record.get('reachable'):
            notes.append('%s: unreachable (%s)' % (record['host'], record.get('error', '?')))
            continue
        if record.get('installed') is False:
            notes.append('%s: Luna is not installed' % record['host'])
            continue
        if record.get('legacy'):
            notes.append('%s: older Luna without `probe --json`; add-on state unknown '
                         '(run: luna fleet install %s --force)' % (record['host'], record['host']))
        doctor = record.get('doctor')
        if doctor and (doctor.get('warn') or doctor.get('error')):
            notes.append('%s: doctor reports %d warning(s), %d error(s) (run `luna doctor` there)'
                         % (record['host'], doctor.get('warn', 0), doctor.get('error', 0)))
        if record is reference:
            continue
        if record.get('lunaSha') and reference.get('lunaSha') and record['lunaSha'] != reference['lunaSha']:
            notes.append('%s: luna.py differs from %s' % (record['host'], reference['host']))
        drifted = [n for n, s in (record.get('addons') or {}).items() if s in ('drift', 'missing')]
        if drifted:
            notes.append('%s: add-on payloads drifted/missing: %s' % (record['host'], ', '.join(drifted)))
        ref_pin = (reference.get('steam') or {}).get('pinned')
        pin = (record.get('steam') or {}).get('pinned')
        if ref_pin and pin != ref_pin:
            notes.append('%s: Steam pin %s differs from %s (%s)'
                         % (record['host'], pin or 'none', reference['host'], ref_pin))
    return notes


def _fleet_yes(value):
    return '?' if value is None else ('yes' if value else 'no')


def _fleet_doctor(summary):
    """'ok' / '2w 1e' / '?' (remote too old for `doctor --json`)."""
    if not isinstance(summary, dict):
        return '?'
    if not summary.get('warn') and not summary.get('error'):
        return 'ok'
    return '%dw %de' % (summary.get('warn', 0), summary.get('error', 0))


def fleet_row(record):
    if not record.get('reachable'):
        return [record['host'], 'UNREACHABLE', '', '', '', '', '', '', '']
    if record.get('installed') is False:
        return [record['host'], 'no luna', '', '', '', '', '', '', '']
    steam = record.get('steam') or {}
    if record.get('legacy'):
        addons = 'unknown'
    else:
        states = set((record.get('addons') or {}).values()) - {'absent'}
        addons = 'match' if states == {'match'} else ('drift' if states else 'none')
    lock = 'HARD' if steam.get('hardLock') else ('blocked' if steam.get('updatesBlocked') else 'open')
    return [record['host'], record.get('lunaVersion') or '?', (record.get('lunaSha') or '')[:8] or '?',
            addons, steam.get('pinned') or 'none', _fleet_yes(steam.get('packagesMatch')), lock,
            _fleet_yes(record.get('steamRunning')), _fleet_doctor(record.get('doctor'))]


def fleet_status(hosts, as_json):
    records = [fleet_collect(None)] + [fleet_collect(host) for host in hosts]
    notes = fleet_notes(records)
    if as_json:
        print(json.dumps({'hosts': records, 'notes': notes}, indent=2, sort_keys=True))
    else:
        header = ['HOST', 'LUNA', 'SHA', 'ADD-ONS', 'STEAM PIN', 'PKGS', 'UPDATES', 'RUNNING', 'DOCTOR']
        rows = [header] + [fleet_row(record) for record in records]
        widths = [max(len(str(row[i])) for row in rows) for i in range(len(header))]
        for row in rows:
            print('  '.join(str(cell).ljust(widths[i]) for i, cell in enumerate(row)).rstrip())
        for note in notes:
            print('note: %s' % note)
    bad = any(not r.get('reachable') or r.get('installed') is False for r in records)
    return 1 if bad else EXIT_OK


# ---------------------------------------------------------------- fleet gui
# `luna fleet gui`: ask every machine what its Steam client looks like through the
# existing `luna gui` layer there. Read-only by default (`gui status --json`); --verify
# also runs `gui verify --json` (it navigates the UI and takes a window screenshot) on
# hosts whose Steam is running in accessible mode. Nothing here launches, restarts or
# stops Steam, and remote output is untrusted: size-capped, JSON-typed, never evaluated.

FLEET_GUI_MAX_OUTPUT = 65536
FLEET_GUI_SCRIPT = r'''
p="$HOME/.local/share/Lumen/sls-luna/luna.py"
if [ ! -f "$p" ]; then echo NOLUNA; exit 0; fi
out=$(python3 "$p" gui status --json 2>/dev/null); rc=$?
echo "GUIRC $rc"
printf 'GUI %s\n' "$(printf '%s' "$out" | tr -d '\n' | head -c 65537)"
'''
FLEET_GUI_VERIFY_SCRIPT = r'''
p="$HOME/.local/share/Lumen/sls-luna/luna.py"
if [ ! -f "$p" ]; then echo NOLUNA; exit 0; fi
out=$(python3 "$p" gui verify --json 2>/dev/null); rc=$?
echo "VERIFYRC $rc"
printf 'VERIFY %s\n' "$(printf '%s' "$out" | tr -d '\n' | head -c 65537)"
'''
FLEET_GUI_VERIFY_TIMEOUT = 420


def fleet_clean(value, limit=80):
    """Untrusted text -> a short printable string (no control or escape characters)."""
    if not isinstance(value, str):
        return ''
    return ''.join(c if c.isprintable() else '?' for c in value)[:limit]


def fleet_bool(value):
    return value if isinstance(value, bool) else None


def fleet_gui_blockers(windows):
    """Open windows other than the main Steam window and the sign-in window."""
    return [t for t in windows if t.strip().lower() != 'steam' and 'sign in to steam' not in t.lower()]


def fleet_gui_from_status(info):
    """Validate a `gui status --json` dict into the fields of a fleet GUI record."""
    windows = [fleet_clean(t) for t in (info.get('windows') if isinstance(info.get('windows'), list) else [])[:20]
               if isinstance(t, str)]
    backend = info.get('backend')
    backend = {fleet_clean(k, 24): fleet_clean(v, 120) for k, v in list(backend.items())[:8] if isinstance(k, str)} \
        if isinstance(backend, dict) else {}
    tool = fleet_clean(info.get('tool'), 200)
    record = {'state': 'ok', 'agentDesktop': bool(tool) and tool != 'missing',
              'steamRunning': fleet_bool(info.get('steamRunning')), 'accessible': fleet_bool(info.get('accessible')),
              'screen': fleet_clean(info.get('screen'), 24) or '?', 'windows': windows,
              'blockers': fleet_gui_blockers(windows), 'backend': backend}
    if isinstance(info.get('signal'), str):
        record['signal'] = fleet_clean(info['signal'], 160)
    return record


def fleet_gui_parse(code, out, err):
    """Remote `fleet gui` script output -> record. state: ok | unreachable | no-luna | luna-too-old | bad-output."""
    if code == 255:
        return {'reachable': False, 'state': 'unreachable',
                'error': fleet_clean((err.strip().splitlines() or ['ssh failed'])[-1], 160)}
    record = {'reachable': True}
    if len(out) > FLEET_GUI_MAX_OUTPUT:
        record.update(state='bad-output', error='remote output larger than %d bytes was ignored' % FLEET_GUI_MAX_OUTPUT)
        return record
    gui_line, rc = None, None
    for line in out.splitlines():
        tag, _, rest = line.partition(' ')
        if tag == 'NOLUNA':
            record.update(installed=False, state='no-luna')
            return record
        if tag == 'GUIRC':
            rc = rest.strip()
        elif tag == 'GUI' and gui_line is None:
            gui_line = rest
    record['installed'] = True
    if code != 0 and gui_line is None:
        record.update(state='bad-output', error='remote script failed (exit %s)' % code)
        return record
    info = None
    if gui_line and len(gui_line) <= FLEET_GUI_MAX_OUTPUT:
        try:
            info = json.loads(gui_line)
        except ValueError:
            info = None
    if not isinstance(info, dict) or rc != '0':
        record.update(state='luna-too-old', error='luna too old: run luna fleet install')
        return record
    record.update(fleet_gui_from_status(info))
    return record


def fleet_verify_parse(code, out):
    """Remote `gui verify --json` output -> {'result': pass|fail|skipped, 'reason'?, 'failures': [...]}."""
    if code == 255:
        return {'result': 'fail', 'failures': ['ssh failed during verify']}
    rc, line = None, None
    for raw in out[:FLEET_GUI_MAX_OUTPUT].splitlines():
        tag, _, rest = raw.partition(' ')
        if tag == 'NOLUNA':
            return {'result': 'fail', 'failures': ['Luna is not installed']}
        if tag == 'VERIFYRC':
            rc = rest.strip()
        elif tag == 'VERIFY' and line is None:
            line = rest
    try:
        data = json.loads(line) if line else None
    except ValueError:
        data = None
    if not isinstance(data, dict) or rc not in ('0', '1', '5'):
        return {'result': 'fail', 'failures': ['luna too old for `gui verify --json`: run luna fleet install']}
    # the exit code is the verdict; the JSON only explains it
    result = {'0': 'pass', '1': 'fail', '5': 'skipped'}[rc]
    failures = [fleet_clean(f, 200) for f in (data.get('failures') if isinstance(data.get('failures'), list) else [])[:3]
                if isinstance(f, str)]
    verdict = {'result': result, 'failures': failures}
    if result == 'skipped':
        verdict['reason'] = fleet_clean(data.get('reason'), 200) or 'skipped'
    elif result == 'fail' and not failures:
        verdict['failures'] = ['verify failed (no detail)']
    return verdict


def fleet_gui_skip_reason(record):
    """Why `gui verify` is not attempted on this record (None = go ahead)."""
    if record.get('state') != 'ok':
        return None
    if not record.get('agentDesktop'):
        return 'agent-desktop is not installed'
    if not record.get('steamRunning'):
        return 'Steam is not running (fleet gui never starts it)'
    if not record.get('accessible'):
        return 'Steam is not in accessible mode (fleet gui never restarts it)'
    return None


def fleet_gui_collect(host, verify, local_status=None, local_verify=None):
    """GUI record for one host name, or for this machine when host is None."""
    if host is None:
        info = (local_status or gui_status_info)(argparse.Namespace(login_grace=GUI_LOGIN_GRACE))
        record = {'reachable': True, 'installed': True, 'host': os.uname().nodename, 'local': True}
        record.update(fleet_gui_from_status(info if isinstance(info, dict) else {}))
    else:
        code, out, err = fleet_ssh(host, FLEET_GUI_SCRIPT, timeout=60)
        record = fleet_gui_parse(code, out, err)
        record['host'], record['local'] = host, False
    if verify and record.get('state') == 'ok':
        reason = fleet_gui_skip_reason(record)
        if reason:
            record['verify'] = {'result': 'skipped', 'reason': reason, 'failures': []}
        elif host is None:
            code, summary = (local_verify or gui_verify_data)(argparse.Namespace(json=True))
            record['verify'] = {'result': summary.get('result') if summary.get('result') in ('pass', 'fail', 'skipped') else 'fail',
                                'failures': [fleet_clean(f, 200) for f in (summary.get('failures') or [])[:3]
                                             if isinstance(f, str)]}
            if record['verify']['result'] == 'skipped':
                record['verify']['reason'] = fleet_clean(summary.get('reason'), 200) or 'skipped'
        else:
            code, out, _ = fleet_ssh(host, FLEET_GUI_VERIFY_SCRIPT, timeout=FLEET_GUI_VERIFY_TIMEOUT)
            record['verify'] = fleet_verify_parse(code, out)
    return record


def fleet_gui_failed(record):
    return (record.get('state') != 'ok') or (record.get('verify') or {}).get('result') == 'fail'


def fleet_gui_notes(records):
    notes = []
    for record in records:
        host, state = record['host'], record.get('state')
        if state == 'unreachable':
            notes.append('%s: unreachable (%s)' % (host, record.get('error', '?')))
            continue
        if state == 'no-luna':
            notes.append('%s: Luna is not installed' % host)
            continue
        if state == 'luna-too-old':
            notes.append('%s: luna too old for `gui` (run: luna fleet install %s)' % (host, host))
            continue
        if state != 'ok':
            notes.append('%s: %s' % (host, record.get('error', 'unusable output')))
            continue
        if not record.get('agentDesktop'):
            notes.append('%s: agent-desktop is missing (GUI checks need it)' % host)
        if record.get('steamRunning') and record.get('accessible') is False:
            notes.append('%s: Steam runs in normal mode; tree checks need accessible mode '
                         '(close Steam, then `luna gui launch` there)' % host)
        if record.get('screen') == 'login':
            notes.append('%s: Steam is at the sign-in screen' % host)
        if record.get('blockers'):
            notes.append('%s: open window(s) in front of Steam: %s' % (host, ', '.join('"%s"' % t for t in record['blockers'])))
        verify = record.get('verify') or {}
        if verify.get('result') == 'fail':
            notes.append('%s: gui verify FAILED: %s' % (host, '; '.join(verify.get('failures') or ['?'])))
        elif verify.get('result') == 'skipped':
            notes.append('%s: gui verify skipped: %s' % (host, verify.get('reason', '?')))
    return notes


def fleet_gui_row(record, verify):
    labels = {'unreachable': 'UNREACHABLE', 'no-luna': 'no luna', 'luna-too-old': 'luna too old: run luna fleet install',
              'bad-output': 'bad output'}
    if record.get('state') != 'ok':
        return [record['host'], labels.get(record.get('state'), '?')] + [''] * (7 if verify else 6)
    backend = record.get('backend') or {}
    row = [record['host'], 'ok', 'yes' if record.get('agentDesktop') else 'MISSING',
           _fleet_yes(record.get('steamRunning')), _fleet_yes(record.get('accessible')), record.get('screen') or '?',
           ('%d (blocked by %d)' % (len(record.get('windows') or []), len(record['blockers'])))
           if record.get('blockers') else str(len(record.get('windows') or [])),
           backend.get('name', '?')]
    if verify:
        result = (record.get('verify') or {}).get('result')
        row.append({'pass': 'pass', 'fail': 'FAIL', 'skipped': 'skip'}.get(result, '-'))
    return row


def fleet_gui(hosts, as_json, verify):
    records = [fleet_gui_collect(None, verify)] + [fleet_gui_collect(host, verify) for host in hosts]
    notes = fleet_gui_notes(records)
    if as_json:
        print(json.dumps({'hosts': records, 'notes': notes, 'verify': verify}, indent=2, sort_keys=True))
    else:
        header = ['HOST', 'LUNA', 'AGENT', 'STEAM', 'ACCESSIBLE', 'SCREEN', 'WINDOWS', 'BACKEND'] + (['VERIFY'] if verify else [])
        rows = [header] + [fleet_gui_row(record, verify) for record in records]
        widths = [max(len(str(row[i])) for row in rows) for i in range(len(header))]
        for row in rows:
            print('  '.join(str(cell).ljust(widths[i]) for i, cell in enumerate(row)).rstrip())
        for note in notes:
            print('note: %s' % note)
    return 1 if any(fleet_gui_failed(r) for r in records) else EXIT_OK


def fleet_push_cache(host, dry_run=False):
    """rsync the verified local Steam client cache to HOST when its build differs. (code, message)"""
    state = steam_state()
    build = state['cachedBuild']
    if not state['cacheReady'] or not build:
        return 1, 'no local cache to push (run: luna steam cache, with Steam closed)'
    if state['pinned'] and state['pinned'] != build:
        return 1, 'local cache is build %s but the pin is %s; refusing to push a stale cache' % (build, state['pinned'])
    if state['packagesMatch'] is False:
        return 1, 'local cache failed verification against its manifests; refusing to push it'
    code, out, err = fleet_ssh(host, 'cat "$HOME/%s/build.txt" 2>/dev/null; '
                                     '[ -d "$HOME/%s/package" ] && echo HAS_PACKAGE; true'
                               % (FLEET_REMOTE_CACHE, FLEET_REMOTE_CACHE))
    if code == 255:
        return 1, 'unreachable: %s' % ((err.strip().splitlines() or ['ssh failed'])[-1])
    lines = out.split()
    if lines[:1] == [build] and 'HAS_PACKAGE' in lines:
        return 0, 'already at build %s; nothing to push' % build
    if dry_run:
        return 0, 'would push cache build %s (remote has %s)' % (build, lines[0] if lines and lines[0] != 'HAS_PACKAGE' else 'none')
    src = str(steam_cache_dir()) + '/'
    dest = '%s:%s/' % (host, FLEET_REMOTE_CACHE)
    rsh = 'ssh ' + ' '.join(FLEET_SSH_OPTS)
    base = ['rsync', '-a', '--partial', '--delete', '-e', rsh]
    # build.txt goes last: a half-copied cache never claims to be complete.
    steps = [base + ['--exclude', '/build.txt', '--', src, dest],
             base + ['--include', '/build.txt', '--exclude', '*', '--', src, dest]]
    for step in steps:
        try:
            result = subprocess.run(step, capture_output=True, text=True)
        except OSError as error:
            return 1, 'rsync not runnable: %s' % error
        if result.returncode != 0:
            return 1, 'rsync failed (%d): %s' % (result.returncode, (result.stderr.strip().splitlines() or ['?'])[-1])
    return 0, ('pushed cache build %s (a later install there finds it in its standard cache '
               'dir; no --client-cache needed)' % build)


FLEET_STOP_STEAM_SCRIPT = r'''
uid="$(id -u)"
up() { for n in steam steamwebhelper lumen; do pgrep -u "$uid" -x "$n" >/dev/null && return 0; done; return 1; }
if pgrep -u "$uid" -x steam >/dev/null; then timeout 30 steam -shutdown >/dev/null 2>&1; fi
for i in $(seq 1 %d); do up || exit 0; sleep 1; done
exit 1
'''

FLEET_START_STEAM_SCRIPT = r'''
[ -n "$XDG_RUNTIME_DIR" ] || export XDG_RUNTIME_DIR="/run/user/$(id -u)"
systemd-run --user --quiet --collect steam
'''

FLEET_MKTEMP_SCRIPT = 'mktemp -d "${TMPDIR:-/tmp}/luna-fleet.XXXXXX"\n'


def fleet_build_bundle(out_dir):
    """Build the release bundle from this checkout with `luna release`. Returns (path, error)."""
    buffer = io.StringIO()
    errors = io.StringIO()
    with contextlib.redirect_stdout(buffer), contextlib.redirect_stderr(errors):
        code = cmd_release(argparse.Namespace(out=str(out_dir), publish=False, only=[]))
    bundles = sorted(Path(out_dir).glob('luna-*.tar.gz'))
    if code != 0 or not bundles:
        return None, (buffer.getvalue() + errors.getvalue()).strip() or 'luna release failed'
    return bundles[-1], ''


def fleet_trust_signing_key(host):
    """Opt-in (--trust-signing-key): make `host` trust this machine's release public key. (ok, message)

    Run AFTER the install, so it works whether or not the host had a signing-aware Luna before.
    This is a trust-on-first-use step carried by your own ssh login; only the public key leaves."""
    pub = signing_pub_path()
    blob, why = signing_parse_pubkey(pub.read_text() if pub.is_file() else '')
    if blob is None:
        return False, 'no usable local release public key (%s); run luna signing init' % why
    if not FLEET_BLOB_RE.fullmatch(str(blob)):  # checked again here: it is pasted into a remote shell line
        return False, 'the local release public key is not a plain ssh-ed25519 key; run luna signing init'
    # blob is validated base64 [A-Za-z0-9+/]{68}: safe inside single quotes.
    script = 'python3 "%s" signing trust \'ssh-ed25519 %s\'\n' % (FLEET_REMOTE_LUNA, blob)
    code, out, err = fleet_ssh(host, script, timeout=60)
    if code != 0:
        return False, (err.strip() or out.strip() or 'exit %d' % code).splitlines()[-1]
    return True, 'trusts release key %s' % signing_fingerprint(blob)


def fleet_install_host(host, bundle, options):
    """Install the bundle on one host. Returns (ok, message)."""
    code, out, err = fleet_ssh(host, FLEET_STATUS_SCRIPT)
    record = fleet_parse_status(code, out, err)
    if not record.get('reachable'):
        return False, 'unreachable: %s' % record.get('error', '?')
    if record.get('installed') is False:
        return False, 'Luna is not installed there; bootstrap it once by hand (copy a bundle, run scripts/install-local.sh)'
    drifted = [n for n, s in (record.get('addons') or {}).items() if s in ('drift', 'missing')]
    if record.get('legacy') and not options.force:
        return False, 'REFUSED: older Luna cannot report payload drift; re-run with --force to overwrite regardless'
    if drifted and not options.force:
        return False, 'REFUSED: installed payloads differ from their pins (%s); inspect them or pass --force' % ', '.join(drifted)
    running = bool(record.get('steamRunning')) or bool(record.get('lumenRunning'))
    # Everything below ends up inside a remote shell line: validate it before it is used.
    for name in options.only:
        if name not in ADDONS:
            return False, 'REFUSED: %.40r is not a known add-on (%s)' % (name, ', '.join(ADDONS))
    try:
        stop_timeout = int(options.stop_timeout)
        if not 1 <= stop_timeout <= 3600:
            raise ValueError('out of range')
    except (TypeError, ValueError):
        return False, 'REFUSED: --stop-timeout must be a whole number of seconds (1-3600)'
    if bundle is not None and not FLEET_BUNDLE_NAME_RE.fullmatch(Path(bundle).name):
        return False, 'REFUSED: unusable bundle name %.60r (expected luna-*.tar.gz, letters digits . _ -)' % Path(bundle).name
    if running and not options.restart_steam:
        return False, 'REFUSED: Steam/Lumen is running there; close it or pass --restart-steam'
    if options.dry_run:
        steps = ['copy bundle', 'luna update --bundle' + ''.join(' --only ' + n for n in options.only)
                 + (' --allow-downgrade' if getattr(options, 'allow_downgrade', False) else '')]
        if getattr(options, 'trust_signing_key', False):
            steps.append('luna signing trust (this machine\'s release public key)')
        if running:
            steps = ['stop Steam (steam -shutdown, wait)'] + steps + ['relaunch Steam']
        return True, 'dry-run: would ' + ', '.join(steps)
    if bundle is None:
        return False, 'no bundle'
    code, out, err = fleet_ssh(host, FLEET_MKTEMP_SCRIPT, timeout=30)
    remote_dir = out.strip().splitlines()[-1] if out.strip() else ''
    if code != 0 or not FLEET_REMOTE_DIR_RE.fullmatch(remote_dir) or '..' in remote_dir.split('/'):
        if code == 0:
            return False, 'could not create a usable temp dir there (unexpected answer %.60r); nothing was sent' % remote_dir
        return False, 'could not create a temp dir there: %s' % (err.strip() or out.strip() or code)
    stopped = False
    try:
        sources = [str(bundle), str(bundle) + '.sha256']
        if os.path.lexists(str(bundle) + '.sig'):
            sources.append(str(bundle) + '.sig')  # the host verifies it against ITS trust file
        copy = ['scp', '-q'] + list(FLEET_SSH_OPTS) + ['--'] + sources + ['%s:%s/' % (host, remote_dir)]
        result = subprocess.run(copy, capture_output=True, text=True)
        if result.returncode != 0:
            return False, 'scp failed: %s' % ((result.stderr.strip().splitlines() or ['?'])[-1])
        if running:
            code, _, _ = fleet_ssh(host, FLEET_STOP_STEAM_SCRIPT % stop_timeout,
                                   timeout=stop_timeout + 60)
            stopped = True
            if code != 0:
                return False, 'Steam did not exit within %ds; nothing was installed' % stop_timeout
        remote_bundle = '%s/%s' % (remote_dir, Path(bundle).name)
        update = ['python3', '"%s"' % FLEET_REMOTE_LUNA, 'update', '--bundle', "'%s'" % remote_bundle]
        for name in options.only:
            update += ['--only', name]
        if getattr(options, 'allow_downgrade', False):
            update.append('--allow-downgrade')
        code, out, err = fleet_ssh(host, ' '.join(update) + '\n', timeout=900)
        tail = (out + err).strip().splitlines()[-1:] or ['']
        if code != 0:
            return False, 'install failed (%d): %s' % (code, tail[0])
        note = 'installed' + (' (Steam restarted)' if stopped else '')
        if getattr(options, 'trust_signing_key', False):
            trusted, detail = fleet_trust_signing_key(host)
            if not trusted:
                return False, note + ', but the release key was NOT trusted there: ' + detail
            note += '; ' + detail
        return True, note
    finally:
        fleet_ssh(host, 'rm -rf -- \'%s\'\n' % remote_dir, timeout=30)
        if stopped:
            code, _, err = fleet_ssh(host, FLEET_START_STEAM_SCRIPT, timeout=30)
            if code != 0:
                print('%s: WARNING: could not relaunch Steam: %s' % (host, err.strip()), file=sys.stderr)


def cmd_fleet(options):
    action = options.fleet_action
    hosts = list(options.hosts)
    configured = fleet_load_hosts()
    if action in ('add', 'remove'):
        if len(hosts) != 1:
            print('usage: luna fleet %s HOST' % action, file=sys.stderr)
            return EXIT_REFUSED
        host = hosts[0]
        if not fleet_valid_host(host):
            print('REFUSING: %r is not a plain hostname (letters, digits, . _ -, optional user@)' % host,
                  file=sys.stderr)
            return EXIT_REFUSED
        if action == 'add':
            if host not in configured:
                configured.append(host)
                fleet_save_hosts(configured)
            print('fleet: %s' % ', '.join(configured))
        else:
            if host not in configured:
                print('%s is not in the fleet' % host, file=sys.stderr)
                return 1
            configured.remove(host)
            fleet_save_hosts(configured)
            print('removed %s' % host)
        return EXIT_OK
    if action == 'list':
        print('local   (%s)' % os.uname().nodename)
        for host in configured:
            print('remote  %s' % host)
        return EXIT_OK
    for host in hosts:
        if not fleet_valid_host(host):
            print('REFUSING: %r is not a plain hostname' % host, file=sys.stderr)
            return EXIT_REFUSED
    if action == 'status':
        return fleet_status(hosts or configured, options.json)
    if action == 'gui':
        return fleet_gui(hosts or configured, options.json, getattr(options, 'verify', False))
    for name in options.only:
        if name not in ADDONS:
            print('unknown add-on %r (known: %s)' % (name, ', '.join(ADDONS)), file=sys.stderr)
            return EXIT_REFUSED
    targets = hosts or configured
    if not targets:
        print('no hosts: luna fleet add HOST', file=sys.stderr)
        return EXIT_REFUSED
    failed = False
    if action == 'push-cache':
        for host in targets:
            code, message = fleet_push_cache(host, options.dry_run)
            failed = failed or code != 0
            print('%-20s %s' % (host, message))
        return 1 if failed else EXIT_OK
    # install
    options.stop_timeout = 120
    with tempfile.TemporaryDirectory(prefix='luna-fleet-') as work:
        bundle = None
        if not options.dry_run:
            bundle, error = fleet_build_bundle(work)
            if bundle is None:
                print('REFUSING: cannot build the bundle: %s' % error, file=sys.stderr)
                return 1
        for host in targets:
            ok, message = fleet_install_host(host, bundle, options)
            failed = failed or not ok
            print('%-20s %s %s' % (host, 'ok  ' if ok else 'FAIL', message))
    return 1 if failed else EXIT_OK



# ===========================================================================
# luna saves: share game saves that have no Steam Cloud between machines.
#
# Syncthing already syncs ~/.local, so a real directory under
# ~/.local/share/game-saves/<key>/ reaches the other machine; the game's own
# save directory (a Proton prefix, ~/.config/unity3d/...) becomes a symlink into
# that store. saves.json in the store maps key -> save locations (relative to
# the prefix / ~/.config / $HOME, so they are valid on every machine).
# Nothing is ever deleted: whatever Luna replaces is renamed to a timestamped
# `<name>.luna-backup-<stamp>` sibling (or stored under _backups/ in the store).
# ===========================================================================

SAVES_PROTON_ROOTS = ('AppData/Local', 'AppData/LocalLow', 'AppData/Roaming', 'Documents', 'Saved Games')
SAVES_NOISE = {
    'microsoft', 'temp', 'packages', 'crashdumps', 'd3dscache', 'nvidia', 'amd', 'openvr', 'dxvk',
    'unrealengine', 'crashreportclient', 'steam', 'epic', 'epic games', 'ubisoft', 'ubisoft game launcher',
    'videos', 'templates', 'pictures', 'music', 'downloads', 'desktop', 'my music', 'my pictures',
    'my videos', 'programs', 'wine', 'mesa_shader_cache', 'cache', 'unity', 'goldberg uplayemu saves',
    'oculus', 'metaxr', 'easyanticheat', 'gameanalytics', 'unity technologies', 'crashes',
}
SAVES_SKIP_STUDIOS = {'ludeon studios'}  # RimWorld has its own Syncthing folder
SAVES_SYNC_SAFE = ('.local/share/Steam',)


def saves_store():
    return home() / '.local/share/game-saves'


def saves_map_path():
    return saves_store() / 'saves.json'


def saves_load_map():
    data = read_json_file(saves_map_path())
    if not isinstance(data, dict) or not isinstance(data.get('games'), dict):
        return {'version': 1, 'games': {}}
    return data


def saves_write_map(data):
    saves_store().mkdir(parents=True, exist_ok=True)
    target = saves_map_path()
    temp = target.with_name('.saves.json.%d.tmp' % os.getpid())
    temp.write_text(json.dumps(data, indent=2, sort_keys=True) + '\n')
    os.replace(temp, target)


def saves_libraries():
    """Steam library roots that exist on this machine (Steam home first)."""
    roots = [steam_home()]
    vdf = steam_home() / 'steamapps/libraryfolders.vdf'
    try:
        roots.extend(Path(m) for m in re.findall(r'"path"\s+"([^"]+)"', vdf.read_text(errors='replace')))
    except OSError:
        pass
    seen, result = set(), []
    for root in roots:
        try:
            real = os.path.realpath(root)
        except OSError:
            continue
        if real not in seen and os.path.isdir(os.path.join(real, 'steamapps')):
            seen.add(real)
            result.append(Path(real))
    return result


def saves_installed():
    """{appid: {'name', 'installdir', 'library'}} from appmanifest_*.acf."""
    games = {}
    for library in saves_libraries():
        for manifest in sorted((library / 'steamapps').glob('appmanifest_*.acf')):
            try:
                text = manifest.read_text(errors='replace')
            except OSError:
                continue

            def field(name):
                found = re.search(r'"%s"\s+"([^"]*)"' % name, text)
                return found.group(1) if found else ''
            appid = field('appid') or manifest.stem.split('_', 1)[1]
            games.setdefault(appid, {'name': field('name') or appid, 'installdir': field('installdir'),
                                     'library': library})
    return games


def saves_has_cloud(appid):
    userdata = steam_home() / 'userdata'
    try:
        return any((u / str(appid) / 'remotecache.vdf').is_file() for u in userdata.iterdir())
    except OSError:
        return False


def saves_prefix_user(appid):
    """Wine user dir of the app's Proton prefix on this machine, or None."""
    for library in saves_libraries():
        user = library / 'steamapps/compatdata' / str(appid) / 'pfx/drive_c/users/steamuser'
        if user.is_dir():
            return user
    return None


def saves_resolve(kind, rel, appid=None):
    """Local Path of a save location, or None when its root does not exist here."""
    if kind == 'proton':
        user = saves_prefix_user(appid)
        return user / rel if user else None
    if kind == 'config':
        return home() / '.config' / rel
    if kind == 'home':
        return home() / rel
    return None


def saves_store_path(key, kind, rel):
    return saves_store() / key / kind / rel


def saves_files(path):
    """[(relative path, size)] of regular files below path, not following symlinks."""
    out = []
    for dirpath, _dirs, names in os.walk(str(path)):
        for name in names:
            full = os.path.join(dirpath, name)
            if os.path.isfile(full) and not os.path.islink(full):
                out.append((os.path.relpath(full, str(path)), os.path.getsize(full)))
    return sorted(out)


def saves_has_data(path):
    path = Path(path)
    return path.is_dir() and not path.is_symlink() and bool(saves_files(path))


def saves_slug(text):
    return re.sub(r'[^a-z0-9]+', '-', text.lower()).strip('-') or 'save'


def saves_norm(text):
    return re.sub(r'[^a-z0-9]', '', text.lower())


def saves_stamp():
    return time.strftime('%Y%m%d-%H%M%S')


def saves_same_fs(a, b):
    return os.stat(str(a)).st_dev == os.stat(str(b)).st_dev


def saves_backup_name(path):
    path = Path(path)
    target = path.with_name('%s.luna-backup-%s' % (path.name, saves_stamp()))
    n = 1
    while target.exists() or target.is_symlink():
        n += 1
        target = path.with_name('%s.luna-backup-%s-%d' % (path.name, saves_stamp(), n))
    return target


def saves_copy_verified(source, dest):
    """Copy a tree to dest (must not exist) via a temp sibling; verify by sha256."""
    temp = dest.with_name('.%s.luna-tmp-%d' % (dest.name, os.getpid()))
    if temp.exists():
        shutil.rmtree(str(temp))
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(str(source), str(temp), symlinks=True)
    want, have = saves_files(source), saves_files(temp)
    if want != have or any(sha256(Path(source) / r) != sha256(temp / r) for r, _ in want):
        shutil.rmtree(str(temp))
        raise OSError('copy of %s did not verify' % source)
    os.rename(str(temp), str(dest))


def saves_move_tree(source, dest):
    """Move a real directory to dest (not existing). Cross-filesystem: copy+verify,
    then the original is renamed to a backup (returned), never deleted."""
    dest.parent.mkdir(parents=True, exist_ok=True)
    if saves_same_fs(source, dest.parent):
        os.rename(str(source), str(dest))
        return None
    saves_copy_verified(source, dest)
    backup = saves_backup_name(source)
    os.rename(str(source), str(backup))
    return backup


def saves_remove_if_empty(path):
    """Remove a directory tree that holds no files (empty dirs only)."""
    if os.path.isdir(str(path)) and not os.path.islink(str(path)) and not saves_files(path):
        shutil.rmtree(str(path))


def saves_game_running(appid):
    if not appid:
        return False
    try:
        result = subprocess.run(['pgrep', '-u', str(os.getuid()), '-f', 'AppId=%s( |$)' % appid],
                                capture_output=True, text=True)
    except FileNotFoundError:
        return False
    return result.returncode == 0


def saves_steam_running():
    """Steam itself (client or web helper) is up: it can rewrite a Proton prefix under our feet."""
    return process_running('steam') or process_running('steamwebhelper')


def saves_check_running(appid, kind, label):
    """Error message when the link/unlink must wait, else None. Proton prefixes also need Steam closed."""
    if saves_game_running(appid):
        return '%s: the game is running; close it first' % label
    if kind == 'proton' and saves_steam_running():
        return '%s: Steam is running and the save is inside a Proton prefix; close Steam first' % label
    return None


def saves_link_points_to(link, target):
    return os.path.islink(str(link)) and os.path.realpath(str(link)) == os.path.realpath(str(target))


def saves_dir_bytes(path):
    return sum(size for _, size in saves_files(path))


# -- discovery ---------------------------------------------------------------

def saves_match_game(name, installed):
    """installed appid whose name / installdir matches a Unity <Game> directory."""
    want = saves_norm(name)
    if not want:
        return None
    for appid, info in installed.items():
        if want in (saves_norm(info['name']), saves_norm(info['installdir'])):
            return appid
    if len(want) >= 6:  # "Hollow Knight Silksong" vs "Hollow Knight: Silksong (Demo)"
        for appid, info in installed.items():
            known = saves_norm(info['name'])
            if known.startswith(want) or want.startswith(known) and len(known) >= 6:
                return appid
    return None


def saves_scan():
    """Candidate save locations: dicts with key, appid, name, kind, rel, path, linked, cloud."""
    installed = saves_installed()
    mapped = saves_load_map()['games']
    rows = []

    def add(key, appid, name, kind, rel, path, cloud):
        store = saves_store_path(key, kind, rel)
        rows.append({'key': key, 'appid': appid, 'name': name, 'kind': kind, 'rel': rel, 'path': str(path),
                     'files': 0 if os.path.islink(str(path)) else len(saves_files(path)),
                     'bytes': 0 if os.path.islink(str(path)) else saves_dir_bytes(path),
                     'linked': saves_link_points_to(path, store), 'steamCloud': cloud,
                     'inStore': saves_has_data(store), 'inMap': rel in [
                         l.get('rel') for l in mapped.get(key, {}).get('links', []) if l.get('kind') == kind]})

    for appid, info in sorted(installed.items(), key=lambda kv: kv[1]['name'].lower()):
        user = saves_prefix_user(appid)
        if not user:
            continue
        cloud = saves_has_cloud(appid)
        for root in SAVES_PROTON_ROOTS:
            base = user / root
            if not base.is_dir() or base.is_symlink():
                continue
            for entry in sorted(base.iterdir()):
                if entry.name.lower() in SAVES_NOISE or not entry.is_dir():
                    continue
                rel = '%s/%s' % (root, entry.name)
                if entry.is_symlink() and not saves_link_points_to(entry, saves_store_path(str(appid), 'proton', rel)):
                    continue
                if entry.is_symlink() or saves_has_data(entry):
                    add(str(appid), str(appid), info['name'], 'proton', rel, entry, cloud)
    unity = home() / '.config/unity3d'
    if unity.is_dir():
        for studio in sorted(unity.iterdir()):
            if not studio.is_dir() or studio.name.lower() in SAVES_SKIP_STUDIOS or studio.is_symlink():
                continue
            for game in sorted(studio.iterdir()):
                if not game.is_dir():
                    continue
                rel = 'unity3d/%s/%s' % (studio.name, game.name)
                appid = saves_match_game(game.name, installed)
                key = appid or saves_slug('%s-%s' % (studio.name, game.name))
                if game.is_symlink():
                    # linked under whichever key its target says
                    target = os.path.realpath(str(game))
                    if not target.startswith(os.path.realpath(str(saves_store())) + os.sep):
                        continue
                    key = os.path.relpath(target, os.path.realpath(str(saves_store()))).split(os.sep)[0]
                elif not saves_has_data(game):
                    continue
                add(key, appid, installed[appid]['name'] if appid else game.name, 'config', rel, game,
                    saves_has_cloud(appid) if appid else False)
    return rows


def saves_candidates(rows):
    """Scan rows worth syncing: no Steam Cloud (linked rows always kept)."""
    return [r for r in rows if r['linked'] or not r['steamCloud']]


# -- targets -----------------------------------------------------------------

def saves_classify_path(arg):
    """Path argument -> (key, name, kind, rel, appid)."""
    path = Path(os.path.abspath(os.path.expanduser(arg)))
    parts = path.parts
    if 'compatdata' in parts:
        i = parts.index('compatdata')
        marker = ('pfx', 'drive_c', 'users', 'steamuser')
        if len(parts) > i + 6 and parts[i + 2:i + 6] == marker:
            appid = parts[i + 1]
            info = saves_installed().get(appid, {})
            return appid, info.get('name', appid), 'proton', '/'.join(parts[i + 6:]), appid
        raise ValueError('%s is inside a Proton prefix but not below its steamuser directory' % path)
    config = home() / '.config'
    try:
        rel = path.relative_to(config)
    except ValueError:
        rel = None
    if rel is not None and len(rel.parts) == 3 and rel.parts[0] == 'unity3d':
        appid = saves_match_game(rel.parts[2], saves_installed())
        name = saves_installed()[appid]['name'] if appid else rel.parts[2]
        return (appid or saves_slug('%s-%s' % rel.parts[1:]), name, 'config', str(rel), appid)
    try:
        rel = path.relative_to(home())
    except ValueError:
        raise ValueError('%s is not below %s' % (path, home()))
    if not rel.parts or str(path).startswith(str(saves_store())):
        raise ValueError('refusing to link %s' % path)
    return saves_slug(rel.name), rel.name, 'home', str(rel), None


def saves_targets(arg):
    """[(key, name, appid, kind, rel)] for an appid, key or path argument."""
    if os.sep in arg or arg.startswith(('~', '.')):
        key, name, kind, rel, appid = saves_classify_path(arg)
        return [(key, name, appid, kind, rel)]
    games = saves_load_map()['games']
    found = {}
    for link in games.get(arg, {}).get('links', []):
        found[(link['kind'], link['rel'])] = (arg, games[arg].get('name', arg), games[arg].get('appid'),
                                              link['kind'], link['rel'])
    for row in saves_scan():
        if row['key'] == arg or row['appid'] == arg:
            found[(row['kind'], row['rel'])] = (row['key'], row['name'], row['appid'], row['kind'], row['rel'])
    return list(found.values())


def saves_record(key, name, appid, kind, rel):
    data = saves_load_map()
    game = data['games'].setdefault(key, {'name': name, 'appid': appid, 'links': []})
    game['name'] = name
    if not any(l.get('kind') == kind and l.get('rel') == rel for l in game['links']):
        game['links'].append({'kind': kind, 'rel': rel})
    saves_write_map(data)


# -- link / unlink -----------------------------------------------------------

def saves_link_one(target, prefer=None, dry_run=False):
    """Link one location. Returns (status, message); status in
    linked|already|skipped|conflict|error."""
    key, name, appid, kind, rel = target
    local = saves_resolve(kind, rel, appid)
    label = '%s [%s]' % (name, rel)
    if local is None:
        return 'skipped', '%s: no Proton prefix on this machine - launch the game once, then retry' % label
    store = saves_store_path(key, kind, rel)
    if os.path.islink(str(local)):
        if saves_link_points_to(local, store):
            if not dry_run:
                saves_record(key, name, appid, kind, rel)
            return 'already', '%s: already linked' % label
        return 'error', '%s: %s is a symlink to %s, not to the store' % (label, local, os.path.realpath(str(local)))
    if kind == 'proton' and saves_prefix_user(appid) is None:
        return 'skipped', '%s: no Proton prefix on this machine - launch the game once, then retry' % label
    blocked = saves_check_running(appid, kind, label)
    if blocked:
        return 'error', blocked
    local_has, store_has = saves_has_data(local), saves_has_data(store)
    if local.exists() and not local.is_dir():
        return 'error', '%s: %s is not a directory' % (label, local)
    if not local_has and not store_has:
        return 'skipped', '%s: no save data here or in the store yet' % label
    if local_has and store_has and prefer is None:
        return 'conflict', ('%s: both this machine and the store have saves; pick one with '
                            '--prefer local|store (the other side is backed up first)' % label)
    use_local = local_has and (not store_has or prefer == 'local')
    notes = []
    if dry_run:
        return 'linked', '%s: would link %s -> %s (%s)' % (
            label, local, store, 'move local into store' if use_local else 'use store, back up local')
    store.parent.mkdir(parents=True, exist_ok=True)
    if use_local:
        if store.exists() or store.is_symlink():  # store data being replaced (prefer local)
            backup = saves_store() / '_backups' / ('%s-%s-%s' % (key, saves_stamp(), saves_slug(rel)))
            backup.parent.mkdir(parents=True, exist_ok=True)
            os.rename(str(store), str(backup))
            notes.append('previous store copy kept in %s' % backup)
        backup = saves_move_tree(local, store)
        if backup:
            notes.append('original kept as %s' % backup)
    else:
        if local_has:
            backup = saves_backup_name(local)
            os.rename(str(local), str(backup))
            notes.append('local copy backed up to %s' % backup)
        else:
            saves_remove_if_empty(local)
    local.parent.mkdir(parents=True, exist_ok=True)
    os.symlink(str(store), str(local))
    saves_record(key, name, appid, kind, rel)
    return 'linked', '%s: linked%s' % (label, ('; ' + '; '.join(notes)) if notes else '')


def saves_unlink_one(target, dry_run=False):
    key, name, appid, kind, rel = target
    local = saves_resolve(kind, rel, appid)
    label = '%s [%s]' % (name, rel)
    store = saves_store_path(key, kind, rel)
    if local is None or not os.path.islink(str(local)):
        return 'skipped', '%s: not linked here' % label
    if not saves_link_points_to(local, store):
        return 'error', '%s: %s does not point into the store' % (label, local)
    blocked = saves_check_running(appid, kind, label)
    if blocked:
        return 'error', blocked
    if dry_run:
        return 'linked', '%s: would copy the store back to %s and remove the symlink' % (label, local)
    if store.is_dir():
        temp = local.with_name('.%s.luna-unlink-%d' % (local.name, os.getpid()))
        saves_copy_verified(store, temp)
        os.unlink(str(local))
        os.rename(str(temp), str(local))
    else:
        os.unlink(str(local))
    return 'linked', '%s: unlinked (a copy stays in the store at %s)' % (label, store)


def saves_all_targets():
    targets = []
    for key, game in sorted(saves_load_map()['games'].items()):
        for link in game.get('links', []):
            targets.append((key, game.get('name', key), game.get('appid'), link['kind'], link['rel']))
    return targets


def saves_conflicts():
    store = saves_store()
    return sorted(p for p in store.rglob('*.sync-conflict-*')) if store.is_dir() else []


def saves_link_state(target):
    """linked|unlinked|broken|wrong|no-prefix|store-missing for a mapped location."""
    key, _name, appid, kind, rel = target
    local = saves_resolve(kind, rel, appid)
    store = saves_store_path(key, kind, rel)
    if local is None:
        return 'no-prefix'
    if os.path.islink(str(local)):
        if saves_link_points_to(local, store):
            return 'linked' if store.exists() else 'store-missing'
        return 'broken' if not local.exists() else 'wrong'
    return 'unlinked'


def cmd_saves(options):
    action = options.saves_action
    if action in ('scan', 'status'):
        return saves_cmd_report(options)
    prefer = options.prefer
    if options.all:
        if options.target:
            print('luna saves %s: give a target or --all, not both' % action, file=sys.stderr)
            return EXIT_REFUSED
        targets = saves_all_targets()
        if not targets:
            print('no linked games in %s yet' % saves_map_path())
            return EXIT_OK
    elif options.target:
        try:
            targets = saves_targets(options.target)
        except ValueError as error:
            print('luna saves: %s' % error, file=sys.stderr)
            return EXIT_REFUSED
        if not targets:
            print('luna saves: nothing found for %s (try `luna saves scan`)' % options.target, file=sys.stderr)
            return 1
    else:
        print('luna saves %s: give an appid/path or --all' % action, file=sys.stderr)
        return EXIT_REFUSED
    failed = False
    for target in targets:
        try:
            if action == 'link':
                status, message = saves_link_one(target, prefer, options.dry_run)
            else:
                status, message = saves_unlink_one(target, options.dry_run)
        except OSError as error:
            status, message = 'error', '%s [%s]: %s' % (target[1], target[4], error)
        print('%-8s %s' % (status.upper(), message))
        failed = failed or status in ('error', 'conflict')
    return 1 if failed else EXIT_OK


def saves_cmd_report(options):
    if options.saves_action == 'scan':
        rows = saves_candidates(saves_scan())
        hidden = [r for r in rows if r['appid'] is None]
        if not options.json and not options.all:
            rows = [r for r in rows if r['appid'] is not None]
        if options.json:
            print(json.dumps({'version': 1, 'candidates': rows}, indent=2, sort_keys=True))
            return EXIT_OK
        if not rows:
            print('no unsynced save candidates found')
            return EXIT_OK
        for row in rows:
            state = 'linked' if row['linked'] else ('in store' if row['inStore'] else 'not linked')
            appid = row['appid'] or '-'
            print('%-8s %-34s %-12s %6.1f MB  %s' % (appid, row['name'][:34], state,
                                                     row['bytes'] / 1e6, row['rel']))
        if hidden and not options.all:
            print('(%d Unity save dir(s) match no installed game; `luna saves scan --all` lists them)' % len(hidden))
        todo = [r for r in rows if not r['linked']]
        if todo:
            print('\n%d candidate(s) not linked: luna saves link <appid|path>' % len(todo))
        return EXIT_OK
    # status
    entries = []
    for target in saves_all_targets():
        entries.append({'key': target[0], 'name': target[1], 'kind': target[3], 'rel': target[4],
                        'state': saves_link_state(target)})
    conflicts = [str(p) for p in saves_conflicts()]
    if options.json:
        print(json.dumps({'version': 1, 'store': str(saves_store()), 'links': entries,
                          'conflicts': conflicts}, indent=2, sort_keys=True))
    else:
        print('store: %s' % saves_store())
        for e in entries:
            print('%-14s %-30s %s' % (e['state'].upper(), e['name'][:30], e['rel']))
        for path in conflicts:
            print('CONFLICT       %s' % path)
        if not entries:
            print('no linked games')
    bad = [e for e in entries if e['state'] in ('broken', 'wrong', 'store-missing')]
    return 1 if bad or conflicts else EXIT_OK


def _doctor_saves():
    data = saves_load_map()
    if not data['games']:
        return []
    found = []
    states = [(t, saves_link_state(t)) for t in saves_all_targets()]
    bad = [(t, s) for t, s in states if s in ('broken', 'wrong', 'store-missing')]
    for target, state in bad:
        found.append(_finding('saves.link', 'warn', 'save link for %s (%s) is %s' % (target[1], target[4], state),
                              'luna saves status; luna saves unlink/link %s' % (target[2] or target[0])))
    pending = [t for t, s in states if s == 'unlinked']
    if pending:
        found.append(_finding('saves.unlinked', 'info', '%d synced save location(s) not linked on this machine: %s'
                              % (len(pending), ', '.join(sorted({t[1] for t in pending})[:4])),
                              'luna saves link --all'))
    conflicts = saves_conflicts()
    if conflicts:
        found.append(_finding('saves.conflicts', 'warn', '%d Syncthing conflict file(s) in %s: %s'
                              % (len(conflicts), saves_store(), ', '.join(str(p) for p in conflicts[:3])),
                              'compare each with its original and keep one'))
    if not found:
        found.append(_finding('saves.links', 'ok', 'game save links healthy (%d)' % len(states)))
    return found
# ======================== end luna saves ===================================
# ---------------------------------------------------------------------------
# luna proton: GE-Proton (Steam custom compatibility tool) per machine.
#
# ~/.local/share/Steam is NOT synced, so every machine installs its own tools.
# Steam must be restarted to list a new tool. Per-game mappings live in Steam's
# config/config.vdf (CompatToolMapping); Luna only READS them, never edits them.
# ---------------------------------------------------------------------------

PROTON_REPO = 'GloriousEggroll/proton-ge-custom'
PROTON_API = 'https://api.github.com/repos/%s/releases' % PROTON_REPO
PROTON_TTL = 6 * 3600
PROTON_PREFIX = 'GE-Proton'
PROTON_SIZE_LIMIT = 4 * 1024 ** 3


def proton_tools_dir():
    return steam_home() / 'compatibilitytools.d'


def _proton_open(request, timeout=60):
    """Single network entry point (tests replace it)."""
    return urllib.request.urlopen(request, timeout=timeout)


def _proton_request(url):
    return urllib.request.Request(url, headers={'User-Agent': 'Luna-Proton', 'Accept': 'application/vnd.github+json'})


def proton_version_key(name):
    name = re.sub(r'-(x86_64|aarch64)$', '', str(name))
    return tuple(int(n) for n in re.findall(r'\d+', name)) or (0,)


def _proton_arch_forms(name):
    """Releases ship as GE-ProtonN-M-x86_64 (older ones without the suffix); Steam maps either."""
    plain = re.sub(r'-(x86_64|aarch64)$', '', str(name))
    return {plain, plain + '-x86_64'}


def proton_normalize(version):
    """'11-11' / 'GE-Proton11-11' -> 'GE-Proton11-11'; rejects path-like input."""
    text = str(version or '').strip()
    if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._-]*', text):
        raise ValueError('invalid Proton version: %r' % text)
    return text if not text[0].isdigit() else PROTON_PREFIX + text


def _proton_dir_size(path):
    total = 0
    for root, _dirs, files in os.walk(str(path)):
        for name in files:
            try:
                total += os.lstat(os.path.join(root, name)).st_size
            except OSError:
                pass
    return total


def proton_installed():
    """[{name, version, internal, size, path}] for each tool dir, newest first."""
    base = proton_tools_dir()
    tools = []
    try:
        entries = sorted(p for p in base.iterdir() if p.is_dir() and not p.name.startswith('.'))
    except OSError:
        return []
    for path in entries:
        version = path.name
        try:
            fields = (path / 'version').read_text(errors='replace').split()
            if len(fields) >= 2:
                version = fields[-1]
        except OSError:
            pass
        internal = []
        try:
            internal = re.findall(r'^\s{0,6}"([^"]+)"\s*(?://.*)?$\s*\{',
                                  (path / 'compatibilitytool.vdf').read_text(errors='replace').split('"compat_tools"', 1)[-1],
                                  re.M)
        except OSError:
            pass
        link = path.is_symlink()
        tools.append({'name': path.name, 'version': version, 'internal': internal, 'symlink': link,
                      'size': 0 if link else _proton_dir_size(path), 'path': str(path)})
    tools.sort(key=lambda t: proton_version_key(t['name']), reverse=True)
    return tools


def _vdf_tokens(text):
    for match in re.finditer(r'"((?:[^"\\]|\\.)*)"|([{}])|//[^\n]*', text):
        if match.group(1) is not None:
            yield match.group(1)
        elif match.group(2):
            yield match.group(2)


def _vdf_block(tokens, pos):
    """Parse after '{' -> ({key: str|dict}, next position)."""
    out = {}
    while pos < len(tokens):
        tok = tokens[pos]
        if tok == '}':
            return out, pos + 1
        if pos + 1 < len(tokens) and tokens[pos + 1] == '{':
            out[tok], pos = _vdf_block(tokens, pos + 2)
        elif pos + 1 < len(tokens):
            out[tok] = tokens[pos + 1]
            pos += 2
        else:
            break
    return out, pos


def proton_mappings():
    """{appid: tool name} from config.vdf CompatToolMapping (read-only). {} if unreadable."""
    try:
        text = (steam_home() / 'config/config.vdf').read_text(errors='replace')
    except OSError:
        return {}
    tokens = list(_vdf_tokens(text))
    for i, tok in enumerate(tokens):
        if tok == 'CompatToolMapping' and i + 1 < len(tokens) and tokens[i + 1] == '{':
            block, _ = _vdf_block(tokens, i + 2)
            return {app: str(v.get('name') or '') for app, v in block.items()
                    if isinstance(v, dict) and v.get('name')}
    return {}


def _proton_names(tool):
    names = {tool['name']} | set(tool.get('internal') or [])
    for name in list(names):
        names |= _proton_arch_forms(name)
    return names


def proton_mapped_to(tool, mappings=None):
    names = _proton_names(tool)
    return sorted(app for app, name in (proton_mappings() if mappings is None else mappings).items()
                  if name in names)


def proton_missing_mappings(tools=None, mappings=None):
    """{tool name: [appids]} for GE-Proton tools games are mapped to but are not installed."""
    tools = proton_installed() if tools is None else tools
    have = set()
    for tool in tools:
        have |= _proton_names(tool)
    missing = {}
    for app, name in (proton_mappings() if mappings is None else mappings).items():
        if name.startswith(PROTON_PREFIX) and name not in have:
            missing.setdefault(name, []).append(app)
    return missing


def _proton_json(url):
    last = None
    for attempt in range(1, STEAM_DOWNLOAD_ATTEMPTS + 1):
        try:
            with _proton_open(_proton_request(url), 20) as source:
                return json.loads(source.read(8 * 1024 * 1024).decode('utf-8'))
        except urllib.error.HTTPError as error:
            last = error
            if error.code not in STEAM_RETRY_STATUS:
                raise OSError('HTTP %s from %s' % (error.code, url)) from error
            delay = _retry_after_seconds(error)
        except (urllib.error.URLError, TimeoutError, ConnectionError, ValueError) as error:
            last, delay = error, None
        if attempt == STEAM_DOWNLOAD_ATTEMPTS:
            break
        time.sleep(delay if delay is not None else min(30.0, 2.0 ** attempt) * (0.5 + random.random() / 2))
    raise OSError('%s: %s' % (url, last))


def _proton_release_summary(data):
    assets = {a.get('name'): a for a in data.get('assets') or [] if isinstance(a, dict)}
    tag = str(data.get('tag_name') or '')
    base = next((b for b in (tag + '-x86_64', tag) if (b + '.tar.gz') in assets), tag)
    tar, tsum = assets.get(base + '.tar.gz') or {}, assets.get(base + '.sha512sum') or {}
    return {'tag': tag, 'base': base, 'tarUrl': tar.get('browser_download_url', ''), 'tarSize': int(tar.get('size') or 0),
            'sumUrl': tsum.get('browser_download_url', '')}


def proton_release(version='latest', force=False):
    """Release summary (cached 6h for latest); raises OSError on network failure."""
    cache = luna_tools_dir() / 'proton-latest.json'
    if version == 'latest':
        cached = read_json_file(cache) or {}
        if (not force and cached.get('tag') and int(cached.get('checkedAt') or 0) > time.time() - PROTON_TTL):
            return cached
        summary = _proton_release_summary(_proton_json(PROTON_API + '/latest'))
        if summary['tag']:
            summary['checkedAt'] = int(time.time())
            try:
                write_json_file(cache, summary)
            except OSError:
                pass
        return summary
    return _proton_release_summary(_proton_json('%s/tags/%s' % (PROTON_API, re.sub(r'-(x86_64|aarch64)$', '', proton_normalize(version)))))


# ------------------------------------------------------------------ safety
#
# Failure mode this section guards against (docs/PROTON_SINGLE_VERSION.md):
# Steam runs a driver query once per registered compat tool, all with app id 0, so
# every tool shares <steam>/steamapps/compatdata/0/pfx. That prefix holds ~600
# symlinks per architecture straight into the DLLs of the tool that last set it up;
# when a second GE-Proton version's wineboot updates it, it writes THROUGH those
# links and overwrites the other version's Windows DLLs in place. Rule: one
# GE-Proton version per machine. Nothing below hashes anything except `verify`.

PROTON_MANIFEST_VERSION = 1
PROTON_DLL_DIRS = ('files/lib/wine/x86_64-windows', 'files/lib/wine/i386-windows',
                   'files/lib64/wine/x86_64-windows', 'files/lib64/wine/i386-windows')
PROTON_MTIME_SLACK = 3600       # DLLs are built shortly BEFORE the `version` file is written
PROTON_MTIME_MIN_FILES = 20
PROTON_PREFIX_SYSDIRS = ('drive_c/windows/system32', 'drive_c/windows/syswow64')


def proton_manifest_dir():
    return luna_tools_dir() / 'proton-manifests'


def proton_manifest_path(name):
    return proton_manifest_dir() / (name + '.json')


def _proton_manifest_valid(data, size_optional=False):
    """True when `data` has the exact shape proton_compare relies on."""
    if not (isinstance(data, dict) and data.get('version') == PROTON_MANIFEST_VERSION):
        return False
    files, links = data.get('files'), data.get('links', {})
    if not isinstance(files, dict) or not isinstance(links, dict):
        return False
    for rel, entry in files.items():
        if not (isinstance(rel, str) and isinstance(entry, list) and len(entry) == 2
                and ((isinstance(entry[0], int) and not isinstance(entry[0], bool)) or (size_optional and entry[0] is None))
                and isinstance(entry[1], str)):
            return False
    return all(isinstance(k, str) and isinstance(v, str) for k, v in links.items())


def proton_manifest_state(name):
    """'ok' | 'missing' | 'unreadable' (present but malformed, or not valid JSON)."""
    path = proton_manifest_path(name)
    if not os.path.lexists(str(path)):
        return 'missing'
    return 'ok' if _proton_manifest_valid(read_json_file(path)) else 'unreadable'


def proton_manifest_load(name):
    data = read_json_file(proton_manifest_path(name))
    return data if _proton_manifest_valid(data) else None


def proton_ge_tools(tools=None):
    return [t for t in (proton_installed() if tools is None else tools) if t['name'].startswith(PROTON_PREFIX)]


def proton_multi_warning(tools=None):
    """One-paragraph warning when more than one GE-Proton is installed, else ''."""
    ge = proton_ge_tools(tools)
    if len(ge) < 2:
        return ''
    return ('%d GE-Proton versions are installed (%s). Steam probes every registered tool against one shared '
            'prefix (compatdata/0/pfx) whose DLL symlinks point into whichever tool set it up last, so one '
            "version's wineboot can overwrite the other's Windows DLLs in place. Keep one: "
            'luna proton prune (or luna proton remove VERSION).' % (len(ge), ', '.join(t['name'] for t in ge)))


def proton_proc_dir():
    """/proc, unless a test points LUNA_PROC_DIR at a look-alike AND the Steam home is not
    under the real user's home: on a real Steam install the override is ignored, so it can
    never hide a running Steam from a destructive command."""
    override = os.environ.get('LUNA_PROC_DIR')
    if not override:
        return '/proc'
    try:
        import pwd
        real_home = os.path.realpath(pwd.getpwuid(os.getuid()).pw_dir)
    except (ImportError, KeyError, OSError):
        return '/proc'
    steam = os.path.realpath(str(steam_home()))
    return '/proc' if steam == real_home or steam.startswith(real_home + os.sep) else override


def _proton_config_unreadable():
    """Path of config.vdf when it exists but cannot be read (mappings unknown), else ''."""
    config = steam_home() / 'config/config.vdf'
    if not os.path.lexists(str(config)):
        return ''
    if not os.access(str(config), os.R_OK):
        return str(config)
    try:
        with open(str(config), 'rb') as handle:
            handle.read(1)
    except FileNotFoundError:
        return ''
    except OSError:
        return str(config)
    return ''


def _proton_remove_tree(tool):
    """Delete one tool dir + manifest after the final safety checks. '' on success, else why not."""
    path = tool['path']
    if os.path.islink(path):
        return 'it is a symlink; never followed or deleted here'
    busy = proton_busy_reason(path)
    if busy:
        return busy
    try:
        shutil.rmtree(path)
    except OSError as error:
        return 'could not delete it: %s' % error
    try:
        proton_manifest_path(tool['name']).unlink()
    except OSError:
        pass
    return ''


def proton_busy_reason(path=None, proc=None):
    """Why a tool directory must not be replaced or removed right now, or ''.
    Steam up (it owns the shared prefix links) or any wine process running from `path`."""
    proc = proc or proton_proc_dir()
    scan = steam_process_scan(proc)
    if scan['running']:
        return 'Steam is running; close it completely first (its prefix links point into the tool directory)'
    if scan['error']:  # fail CLOSED: an unreadable process table is not "Steam is not running"
        return 'cannot tell whether Steam is running (%s); not touching the tool directory' % scan['error']
    if path:
        root = os.path.realpath(str(path))
        try:
            entries = [e for e in Path(proc).iterdir() if e.name.isdigit()]
        except OSError as error:
            return 'cannot list the processes (%s); not touching the tool directory' % error
        uid = os.getuid()
        for entry in entries:
            try:
                if entry.stat().st_uid != uid:
                    continue
                hit = os.path.realpath(os.readlink(str(entry / 'exe'))).startswith(root + os.sep) \
                    if (entry / 'exe').is_symlink() else False
                if not hit:
                    hit = any(a.startswith(root + os.sep) or a == root for a in
                              (entry / 'cmdline').read_bytes().decode('utf-8', 'replace').split('\0'))
            except (FileNotFoundError, ProcessLookupError, NotADirectoryError):
                continue  # exited while we looked
            except OSError as error:
                return 'cannot inspect process %s (%s); not touching the tool directory' % (entry.name, error)
            if hit:
                return 'a process (pid %s) is running from %s; stop it first' % (entry.name, path)
    return ''


def _proton_progress(label, total):
    """Throttled byte progress for hashing: \\r on a TTY, sparse lines otherwise."""
    state = {'last': 0.0}
    tty = sys.stdout.isatty()

    def update(done, final=False):
        now = time.monotonic()
        if not final and now - state['last'] < (0.3 if tty else 5.0):
            return
        state['last'] = now
        text = '%s of %s (%d%%)' % (_format_mb(done), _format_mb(total), 100 * done // total if total else 100)
        if tty:
            print('\r\033[Kproton    : %s  %s' % (label, text), end='\n' if final else '', flush=True)
        else:
            print('proton    :   %s  %s' % (label, text), flush=True)
    return update


def _proton_walk(root):
    """({rel: size} regular files, {rel: link target}) under root; __pycache__ is ignored
    (Proton's own python writes it on first run)."""
    files, links = {}, {}
    base = str(root)
    for current, dirs, names in os.walk(base):
        dirs[:] = sorted(d for d in dirs if d != '__pycache__')
        for name in sorted(names + [d for d in dirs if os.path.islink(os.path.join(current, d))]):
            full = os.path.join(current, name)
            rel = os.path.relpath(full, base)
            try:
                if os.path.islink(full):
                    links[rel] = os.readlink(full)
                elif name.endswith('.pyc') and os.path.basename(current) == '__pycache__':
                    continue
                else:
                    files[rel] = os.lstat(full).st_size
            except OSError:
                pass
    return files, links


def _proton_hash_file(path):
    digest = hashlib.sha256()
    with open(path, 'rb') as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def proton_build_manifest(root, name, source, tag=''):
    """Hash a tree (progress shown). Only ever call this on a tree that came from a
    sha512-verified download, never on an install of unknown state."""
    files, links = _proton_walk(root)
    total = sum(files.values())
    progress = _proton_progress('hashing %s' % name, total)
    done, out = 0, {}
    for rel in sorted(files):
        out[rel] = [files[rel], _proton_hash_file(os.path.join(str(root), rel))]
        done += files[rel]
        progress(done)
    progress(done, final=True)
    return {'version': PROTON_MANIFEST_VERSION, 'name': name, 'tag': tag, 'source': source,
            'createdAt': int(time.time()), 'files': out, 'links': links}


def proton_compare(root, expected, expected_links=None, label='verifying'):
    """Compare a tree with {rel: [size|None, sha256]} (+ optional {rel: link target}).
    Returns {'changed': [], 'missing': [], 'extra': [], 'checked': n}. ValueError on a bad shape."""
    if not _proton_manifest_valid({'version': PROTON_MANIFEST_VERSION, 'files': expected,
                                   'links': {} if expected_links is None else expected_links}, size_optional=True):
        raise ValueError('malformed manifest data')
    files, links = _proton_walk(root)
    changed, missing = [], []
    todo = [rel for rel in sorted(expected) if rel in files]
    for rel in sorted(expected):
        if rel not in files:
            (changed if rel in links else missing).append(rel)
    total = sum(files[r] for r in todo)
    progress = _proton_progress('%s %s' % (label, os.path.basename(str(root))), total)
    done = 0
    for rel in todo:
        size, sha = expected[rel][0], expected[rel][1]
        if size is not None and size != files[rel]:
            changed.append(rel)
        else:
            try:
                if _proton_hash_file(os.path.join(str(root), rel)) != sha:
                    changed.append(rel)
            except OSError:
                missing.append(rel)
        done += files[rel]
        progress(done)
    progress(done, final=True)
    extra = [rel for rel in files if rel not in expected and rel not in (expected_links or {})]
    if expected_links is not None:
        for rel, target in expected_links.items():
            if rel not in links:
                (changed if rel in files else missing).append(rel)
            elif links[rel] != target:
                changed.append(rel)
        extra += [rel for rel in links if rel not in expected_links and rel not in expected]
    return {'changed': sorted(set(changed)), 'missing': sorted(set(missing)),
            'extra': sorted(set(extra)), 'checked': len(expected)}


def _proton_report(name, result):
    bad = result['changed'] or result['missing'] or result['extra']
    if not bad:
        print('verify    : %s OK (%d files match)' % (name, result['checked']))
        return True
    print('verify    : %s MISMATCH: %d changed, %d missing, %d extra (of %d files)'
          % (name, len(result['changed']), len(result['missing']), len(result['extra']), result['checked']))
    for kind in ('changed', 'missing', 'extra'):
        for rel in result[kind][:5]:
            print('            %-8s %s' % (kind, rel))
        if len(result[kind]) > 5:
            print('            %-8s ... and %d more' % (kind, len(result[kind]) - 5))
    print('verify    : fix: luna proton remove %s --force && luna proton install %s  (Steam closed)'
          % (name, name))
    return False


def _proton_read_reference(path):
    """sha256sum-format file -> {rel: [None, sha]}; the leading <tool>/ component is dropped."""
    out = {}
    for line in Path(path).read_text(errors='replace').splitlines():
        match = re.match(r'^([0-9a-fA-F]{64})\s[ *]?(.+)$', line)
        if match:
            rel = match.group(2)
            rel = rel.split('/', 1)[1] if '/' in rel else rel
            out[rel] = [None, match.group(1).lower()]
    return out


def proton_verify(version=None, rebuild=False, against=None):
    """0 = every checked tool matches; 1 = mismatch, missing manifest or error."""
    tools = proton_ge_tools()
    if version:
        try:
            name = proton_normalize(version)
        except ValueError as error:
            print('verify    : %s' % error)
            return 1
        tools = [t for t in tools if t['name'] in _proton_arch_forms(name)]
        if not tools:
            print('verify    : %s is not installed' % name)
            return 1
    if not tools:
        print('verify    : no GE-Proton installed')
        return EXIT_OK
    if (rebuild or against) and len(tools) != 1:
        print('verify    : --rebuild/--against need exactly one VERSION')
        return 1
    ok = True
    for tool in tools:
        name = tool['name']
        if against:
            try:
                reference = _proton_read_reference(against)
            except OSError as error:
                print('verify    : cannot read %s: %s' % (against, error))
                return 1
            result = proton_compare(tool['path'], reference, None)
            # a reference lists regular files only: links in the tree are not "extra"
            result['extra'] = [r for r in result['extra'] if not os.path.islink(os.path.join(tool['path'], r))]
            ok = _proton_report(name, result) and ok
            continue
        if rebuild:
            code = _proton_rebuild(tool)
            ok = ok and code == EXIT_OK
            continue
        if proton_manifest_state(name) == 'unreadable':
            print('verify    : %s: manifest unreadable or malformed (%s); it is not trusted. Run: '
                  'luna proton verify %s --rebuild' % (name, proton_manifest_path(name), name))
            ok = False
            continue
        manifest = proton_manifest_load(name)
        if not manifest:
            print('verify    : %s has no manifest (installed before manifests existed, or by hand). '
                  'It is never created from the current disk state; run: luna proton verify %s --rebuild '
                  '(re-downloads and sha512-checks the release)' % (name, name))
            ok = False
            continue
        ok = _proton_report(name, proton_compare(tool['path'], manifest['files'], manifest.get('links'))) and ok
    return EXIT_OK if ok else 1


def _proton_rebuild(tool):
    """Create the manifest from a freshly downloaded, sha512-verified release, then check
    the installed tree against it."""
    name = tool['name']
    try:
        release = proton_release(re.sub(r'-(x86_64|aarch64)$', '', name), force=True)
    except (OSError, ValueError) as error:
        print('verify    : cannot reach the release API: %s' % error)
        return 1
    base = proton_tools_dir()
    work = Path(tempfile.mkdtemp(prefix='.luna-proton-', dir=str(base)))
    try:
        top = _proton_fetch_verified(release, work)
        if top is None:
            return 1
        if top.name not in _proton_arch_forms(name):
            print('verify    : the release unpacks as %s, not %s; not recording a manifest' % (top.name, name))
            return 1
        manifest = proton_build_manifest(top, name, 'rebuild', release['tag'])
    except (OSError, ValueError, tarfile.TarError) as error:
        print('verify    : rebuild failed: %s' % error)
        return 1
    finally:
        shutil.rmtree(str(work), ignore_errors=True)
    try:
        write_json_file(proton_manifest_path(name), manifest)
    except OSError as error:
        print('verify    : cannot write the manifest: %s' % error)
        return 1
    print('verify    : manifest for %s written from the verified release (%d files) -> %s'
          % (name, len(manifest['files']), proton_manifest_path(name)))
    result = proton_compare(tool['path'], manifest['files'], manifest['links'])
    return EXIT_OK if _proton_report(name, result) else 1


# ------------------------------------------------------------ cheap heuristics

def _proton_dll_finding(tool):
    base = Path(tool['path'])
    try:
        ref = (base / 'version').stat().st_mtime + PROTON_MTIME_SLACK
    except OSError:
        return None
    total = newer = 0
    dirs = []
    for rel in PROTON_DLL_DIRS:
        count = 0
        try:
            with os.scandir(str(base / rel)) as entries:
                for entry in entries:
                    if not entry.name.lower().endswith(('.dll', '.exe', '.sys', '.drv')):
                        continue
                    try:
                        mtime = entry.stat(follow_symlinks=False).st_mtime
                    except OSError:
                        continue
                    total += 1
                    if mtime > ref:
                        newer += 1
                        count += 1
        except OSError:
            continue
        if count:
            dirs.append('%s (%d)' % (rel.split('wine/', 1)[-1], count))
    if newer >= PROTON_MTIME_MIN_FILES and newer * 20 >= total:
        return {'id': 'proton.dll-mtimes', 'severity': 'warn', 'tool': tool['name'],
                'message': '%s: %d of %d Windows DLLs are newer than the tool itself in %s; a wineboot prefix '
                           'update probably overwrote them with another version\'s' % (tool['name'], newer, total, ', '.join(dirs)),
                'fix': 'luna proton verify %s (add --rebuild if it has no manifest), then reinstall it' % tool['name']}
    return None


def _proton_prefix_owner(compat):
    """Tool names compatdata/0 says last set the prefix up (config_info paths, version text)."""
    names = set()
    try:
        names |= set(re.findall(r'compatibilitytools\.d/([A-Za-z0-9._-]+)', (compat / 'config_info').read_text(errors='replace')))
    except OSError:
        pass
    try:
        text = (compat / 'version').read_text(errors='replace')
        for tool in proton_installed():
            if tool['name'] in text or (tool['version'] and tool['version'] in text.split()):
                names.add(tool['name'])
    except OSError:
        pass
    return names


def proton_prefix_findings():
    """Dangling or foreign symlinks in the shared compatdata/0 prefix (readlink only)."""
    compat = steam_home() / 'steamapps/compatdata/0'
    tools_dir = str(proton_tools_dir())
    roots = {tools_dir, os.path.realpath(tools_dir)}
    seen, dangling = {}, {}
    for sysdir in PROTON_PREFIX_SYSDIRS:
        folder = compat / 'pfx' / sysdir
        try:
            entries = list(os.scandir(str(folder)))
        except OSError:
            continue
        for entry in entries:
            if not entry.is_symlink():
                continue
            target = os.path.normpath(os.path.join(str(folder), os.readlink(entry.path)))
            for root in roots:
                if target.startswith(root + os.sep):
                    tool = target[len(root) + 1:].split(os.sep)[0]
                    seen[tool] = seen.get(tool, 0) + 1
                    if not os.path.exists(target):
                        dangling[tool] = dangling.get(tool, 0) + 1
                    break
    found = []
    for tool, count in sorted(dangling.items()):
        found.append({'id': 'proton.prefix-dangling', 'severity': 'warn', 'tool': tool,
                      'message': '%d link(s) in the shared prefix compatdata/0/pfx point into %s, which %s'
                                 % (count, tool, 'is missing files' if (proton_tools_dir() / tool).is_dir() else 'no longer exists'),
                      'fix': 'close Steam, then luna proton verify; Steam repairs the prefix on its next start with the one installed tool'})
    owner = _proton_prefix_owner(compat)
    owner_forms = set()
    for name in owner:
        owner_forms |= _proton_arch_forms(name)
    foreign = {t: c for t, c in seen.items() if t not in dangling and owner and t not in owner_forms}
    mixed = len(seen) > 1 and not owner
    for tool, count in sorted(foreign.items()):
        found.append({'id': 'proton.prefix-foreign', 'severity': 'warn', 'tool': tool,
                      'message': '%d link(s) in compatdata/0/pfx point into %s but the prefix was last set up by %s: '
                                 'the next prefix update can overwrite %s\'s DLLs' % (count, tool, ', '.join(sorted(owner)), tool),
                      'fix': 'keep one GE-Proton (luna proton prune), then luna proton verify'})
    if mixed:
        found.append({'id': 'proton.prefix-foreign', 'severity': 'warn', 'tool': '',
                      'message': 'links in compatdata/0/pfx point into %d different tools (%s)' % (len(seen), ', '.join(sorted(seen))),
                      'fix': 'keep one GE-Proton (luna proton prune), then luna proton verify'})
    return found


def proton_health(tools=None):
    """Cheap, hash-free findings: [{id, severity, message, fix, tool}]."""
    tools = proton_ge_tools(tools)
    found = []
    warning = proton_multi_warning(tools)
    if warning:
        found.append({'id': 'proton.multi-version', 'severity': 'warn', 'tool': '', 'message': warning,
                      'fix': 'luna proton prune'})
    for tool in tools:
        item = _proton_dll_finding(tool)
        if item:
            found.append(item)
    found.extend(proton_prefix_findings())
    return found


def proton_status_data():
    tools = proton_installed()
    try:
        latest = proton_release()['tag'] or 'unknown'
    except OSError:
        latest = 'unknown'
    mappings = proton_mappings()
    newest = max((t['name'] for t in tools if t['name'].startswith(PROTON_PREFIX)),
                 key=proton_version_key, default='')
    return {'tools': [dict({k: t[k] for k in ('name', 'version', 'size')},
                           manifest=proton_manifest_load(t['name']) is not None) for t in tools],
            'latest': latest,
            'updateAvailable': bool(latest != 'unknown' and
                                    (not newest or proton_version_key(latest) > proton_version_key(newest))),
            'mappedGames': sum(1 for _ in mappings),
            'missing': proton_missing_mappings(tools, mappings),
            'warnings': proton_health(tools),
            'toolsDir': str(proton_tools_dir())}


def proton_status(as_json):
    data = proton_status_data()
    if as_json:
        print(json.dumps(data, indent=2, sort_keys=True))
        return EXIT_OK
    print('proton    : %s' % data['toolsDir'])
    if not data['tools']:
        print('installed : none')
    for tool in data['tools']:
        print('installed : %-28s %-16s %s%s' % (tool['name'], tool['version'], _format_mb(tool['size']),
                                                '' if tool['manifest'] or not tool['name'].startswith(PROTON_PREFIX)
                                                else '  (no manifest: luna proton verify %s --rebuild)' % tool['name']))
    note = '  (update available: luna proton install)' if data['updateAvailable'] else ''
    print('latest    : %s%s' % (data['latest'], note))
    for name, apps in sorted(data['missing'].items()):
        print('missing   : %s is mapped by %d game(s) (appid %s); run: luna proton install %s'
              % (name, len(apps), ', '.join(sorted(apps)[:6]), name))
    for item in data['warnings']:
        print('warning   : %s\n            fix: %s' % (item['message'], item['fix']))
    return EXIT_OK


def _proton_virtual_resolve(links, name, limit=40):
    """Resolve `name` (relative to the extraction root) through the symlinks the archive has
    created so far, in a virtual filesystem. Returns the normalised parts, or None when the
    path escapes the root. `links` maps a normalised member path (tuple) to its target text."""
    pending = [p for p in name.split('/') if p not in ('', '.')]
    done = []
    hops = 0
    while pending:
        part = pending.pop(0)
        if part == '..':
            if not done:
                return None
            done.pop()
            continue
        done.append(part)
        target = links.get(tuple(done))
        if target is not None:
            hops += 1
            if hops > limit or target.startswith('/'):
                return None
            done.pop()
            pending = [p for p in target.split('/') if p not in ('', '.')] + pending
    return done


def _proton_safe_extract(archive, dest):
    """Validate every member against a virtual filesystem (so `a -> ../..` followed by `a/x`
    is caught), then extract with the tarfile 'data' filter where Python has it."""
    links = {}
    for member in archive.getmembers():
        if member.isdev():
            raise ValueError('device node in archive: %s' % member.name)
        if member.name.startswith('/'):
            raise ValueError('unsafe path in archive: %s' % member.name)
        parent = _proton_virtual_resolve(links, os.path.dirname(member.name.rstrip('/')))
        if parent is None:
            raise ValueError('unsafe path in archive: %s' % member.name)
        leaf = os.path.basename(member.name.rstrip('/'))
        if leaf in ('', '.', '..'):
            if member.isdir() and leaf in ('', '.'):
                continue
            raise ValueError('unsafe path in archive: %s' % member.name)
        here = tuple(parent) + (leaf,)
        if member.issym():
            if os.path.isabs(member.linkname):
                raise ValueError('absolute symlink in archive: %s' % member.name)
            if _proton_virtual_resolve(links, '/'.join(parent + [member.linkname])) is None:
                raise ValueError('symlink escapes the archive: %s -> %s' % (member.name, member.linkname))
            links[here] = member.linkname
        elif member.islnk():
            if os.path.isabs(member.linkname) or _proton_virtual_resolve(links, member.linkname) is None:
                raise ValueError('unsafe hard link in archive: %s' % member.name)
            links.pop(here, None)
        else:
            links.pop(here, None)
    if hasattr(tarfile, 'data_filter'):
        archive.extractall(dest, filter='data')
    else:
        archive.extractall(dest)


def _proton_download(url, destination, total=0, label=None):
    """Stream `url` to `destination` with retry/backoff; returns sha512 hex."""
    for attempt in range(1, STEAM_DOWNLOAD_ATTEMPTS + 1):
        digest = hashlib.sha512()
        progress = _Progress(label or 'download', total)
        try:
            with _proton_open(_proton_request(url)) as source, open(destination, 'wb') as out:
                try:
                    progress.total = int(source.headers.get('Content-Length') or total)
                except (AttributeError, TypeError, ValueError):
                    pass
                size = 0
                while True:
                    chunk = source.read(1024 * 1024)
                    if not chunk:
                        break
                    size += len(chunk)
                    if size > PROTON_SIZE_LIMIT:
                        raise ValueError('download exceeds size limit')
                    digest.update(chunk)
                    out.write(chunk)
                    progress.update(size)
            progress.update(size, final=True)
            return digest.hexdigest()
        except urllib.error.HTTPError as error:
            if error.code not in STEAM_RETRY_STATUS or attempt == STEAM_DOWNLOAD_ATTEMPTS:
                raise OSError('HTTP %s from %s' % (error.code, url)) from error
            delay, reason = _retry_after_seconds(error), 'HTTP %s' % error.code
        except (urllib.error.URLError, TimeoutError, ConnectionError) as error:
            if attempt == STEAM_DOWNLOAD_ATTEMPTS:
                raise OSError('%s: %s' % (url, error)) from error
            delay, reason = None, str(error)
        if delay is None:
            delay = min(60.0, 2.0 ** attempt) * (0.5 + random.random() / 2)
        print('proton    : %s; retry %d/%d in %.0fs' % (reason, attempt, STEAM_DOWNLOAD_ATTEMPTS - 1, delay), flush=True)
        time.sleep(delay)


def _proton_fetch_verified(release, work):
    """Download the release tarball into `work`, check its sha512 and unpack it.
    Returns the single extracted top-level directory, or None (reason printed)."""
    tag = release['tag']
    asset = release.get('base') or tag
    try:
        with _proton_open(_proton_request(release['sumUrl'])) as source:
            text = source.read(65536).decode('utf-8', 'replace')
    except (OSError, urllib.error.URLError) as error:
        print('proton    : cannot fetch checksum: %s' % error)
        return None
    expected = next((line.split()[0].lower() for line in text.splitlines()
                     if line.split() and line.split()[-1].lstrip('*') == asset + '.tar.gz'), '')
    if not re.fullmatch(r'[0-9a-f]{128}', expected):
        print('proton    : no valid sha512 for %s.tar.gz in the checksum file' % asset)
        return None
    tarball = work / (asset + '.tar.gz')
    actual = _proton_download(release['tarUrl'], tarball, release['tarSize'], tag)
    if actual != expected:
        print('proton    : SHA512 mismatch for %s; nothing installed' % tag)
        return None
    print('proton    : sha512 verified; extracting')
    extract = work / 'x'
    extract.mkdir()
    with tarfile.open(str(tarball), 'r:gz') as archive:
        _proton_safe_extract(archive, str(extract))
    tops = [p for p in extract.iterdir()]
    if len(tops) != 1 or not tops[0].is_dir() or tops[0].name not in (tag, asset):
        print('proton    : unexpected archive layout (expected a single %s/ directory)' % asset)
        return None
    return tops[0]


def _proton_space_ok(release, base):
    need = max(release['tarSize'], 300 * 1024 ** 2) * 4  # tarball + extracted tree + slack
    probe = base if base.exists() else base.parent
    free = shutil.disk_usage(str(probe)).free
    if free < need:
        print('proton    : not enough free space in %s: %s free, ~%s needed' % (probe, _format_mb(free), _format_mb(need)))
        return False
    return True


def proton_install(version='latest', dry_run=False):
    try:
        release = proton_release(version, force=True)
    except (OSError, ValueError) as error:
        print('proton    : cannot reach the release API: %s' % error)
        return 1
    tag = release['tag']
    if not tag or not release['tarUrl'] or not release['sumUrl']:
        print('proton    : release %s has no .tar.gz + .sha512sum assets' % (tag or version))
        return 1
    base = proton_tools_dir()
    asset = release.get('base') or tag
    present = next((n for n in (tag, asset) if (base / n).exists()), '')
    if present:
        print('proton    : %s is already installed (%s); nothing to do' % (tag, base / present))
        return EXIT_OK
    if not dry_run:
        busy = proton_busy_reason()
        if busy:
            print('proton    : refusing to install: %s' % busy)
            return EXIT_REFUSED
        base.mkdir(parents=True, exist_ok=True)
    if not _proton_space_ok(release, base):
        return 1
    if dry_run:
        print('proton    : would install %s (%s) into %s' % (tag, _format_mb(release['tarSize']), base))
        print('proton    : would verify against %s' % release['sumUrl'])
        print('proton    : would record an integrity manifest in %s' % proton_manifest_dir())
        return EXIT_OK
    work = Path(tempfile.mkdtemp(prefix='.luna-proton-', dir=str(base)))
    try:
        top = _proton_fetch_verified(release, work)
        if top is None:
            return 1
        if (base / top.name).exists():
            print('proton    : %s appeared meanwhile; leaving it alone' % top.name)
            return 1
        manifest = proton_build_manifest(top, top.name, 'install', tag)  # from the sha512-verified tree
        busy = proton_busy_reason()  # the download took minutes: Steam may have started meanwhile
        if busy:
            print('proton    : refusing to install: %s' % busy)
            return EXIT_REFUSED
        if (base / top.name).exists() or os.path.islink(str(base / top.name)):
            print('proton    : %s appeared meanwhile; leaving it alone' % top.name)
            return 1
        os.rename(str(top), str(base / top.name))
        name = top.name
    except (OSError, ValueError, tarfile.TarError) as error:
        print('proton    : install failed: %s' % error)
        return 1
    finally:
        shutil.rmtree(str(work), ignore_errors=True)
    try:
        write_json_file(proton_manifest_path(name), manifest)
    except OSError as error:
        print('proton    : installed, but the integrity manifest could not be written: %s' % error)
    print('proton    : installed %s; restart Steam to see it in the compatibility list' % tag)
    warning = proton_multi_warning()
    if warning:
        print('proton    : WARNING: %s' % warning)
        print('proton    : the old version was NOT removed; run: luna proton prune')
    return EXIT_OK


def proton_remove(version, force=False, dry_run=False):
    try:
        name = proton_normalize(version)
    except ValueError as error:
        print('proton    : %s' % error)
        return 1
    tool = next((t for t in proton_installed() if t['name'] in _proton_arch_forms(name)), None)
    if not tool:
        print('proton    : %s is not installed' % name)
        return 1
    if tool.get('symlink'):
        print('proton    : refusing: %s is a symlink (%s); it is never followed or deleted here' % (name, tool['path']))
        return EXIT_REFUSED
    unreadable = _proton_config_unreadable()
    if unreadable and not force:
        print('proton    : refusing: cannot read %s, so games mapped to %s cannot be detected; use --force'
              % (unreadable, name))
        return EXIT_REFUSED
    apps = proton_mapped_to(tool)
    if apps and not force:
        print('proton    : refusing: %d game(s) are mapped to %s (appid %s); use --force'
              % (len(apps), name, ', '.join(apps[:6])))
        return EXIT_REFUSED
    if dry_run:
        print('proton    : would remove %s' % name)
        return EXIT_OK
    problem = _proton_remove_tree(tool)
    if problem:
        print('proton    : refusing to remove %s: %s' % (name, problem))
        return EXIT_REFUSED
    print('proton    : removed %s' % name)
    return EXIT_OK


def proton_prune(keep, dry_run=False):
    """Remove all but the newest `keep` GE-Proton. A version any game is mapped to is
    never removed here (only `remove --force` does that)."""
    if keep < 0:
        print('proton    : --keep must be >= 0')
        return 1
    unreadable = _proton_config_unreadable()
    if unreadable:
        print('proton    : cannot read %s, so mapped versions cannot be protected; nothing pruned' % unreadable)
        return EXIT_REFUSED
    mappings = proton_mappings()
    ge = proton_ge_tools()
    victims = ge[keep:]
    if not victims:
        print('proton    : nothing to prune (%d GE-Proton installed, keeping %d)' % (len(ge), keep))
        return EXIT_OK
    if not dry_run:
        busy = proton_busy_reason()
        if busy:
            print('proton    : refusing to prune: %s' % busy)
            return EXIT_REFUSED
    refused = False
    for tool in victims:
        apps = proton_mapped_to(tool, mappings)
        if apps:
            print('proton    : keeping %s (mapped by %d game(s))' % (tool['name'], len(apps)))
        elif tool.get('symlink'):
            print('proton    : not removing %s: it is a symlink (%s); remove the link yourself if you mean to'
                  % (tool['name'], tool['path']))
            refused = True
        elif dry_run:
            print('proton    : would remove %s' % tool['name'])
        else:
            problem = _proton_remove_tree(tool)
            if problem:
                print('proton    : not removing %s: %s' % (tool['name'], problem))
                refused = True
                continue
            print('proton    : removed %s' % tool['name'])
    warning = proton_multi_warning()
    if warning and not dry_run:
        print('proton    : WARNING: a mapped version is still installed next to the newest one. '
              'Remap those games to the newest tool in Steam, then run: luna proton prune')
    return EXIT_REFUSED if refused else EXIT_OK


def cmd_proton(options):
    action = options.proton_action
    if action == 'status':
        return proton_status(options.json)
    if action == 'install':
        return proton_install(options.proton_version or 'latest', options.dry_run)
    if action == 'remove':
        if not options.proton_version:
            print('proton    : remove needs a VERSION')
            return 1
        return proton_remove(options.proton_version, options.force, options.dry_run)
    if action == 'verify':
        return proton_verify(options.proton_version, options.rebuild, options.against)
    return proton_prune(options.keep, options.dry_run)


def _doctor_proton():
    found = []
    for item in proton_health():
        found.append(_finding(item['id'], item['severity'], item['message'], item['fix']))
    for tool in proton_ge_tools():
        if proton_manifest_state(tool['name']) == 'unreadable':
            found.append(_finding('proton.manifest-unreadable', 'warn',
                                  '%s: the integrity manifest is unreadable or malformed, so it is not trusted' % tool['name'],
                                  'luna proton verify %s --rebuild' % tool['name']))
        elif not proton_manifest_load(tool['name']):
            found.append(_finding('proton.no-manifest', 'info',
                                  '%s has no integrity manifest, so corruption cannot be proven' % tool['name'],
                                  'luna proton verify %s --rebuild' % tool['name']))
    for name, apps in sorted(proton_missing_mappings().items()):
        found.append(_finding('proton.missing-tool', 'warn',
                              '%d game(s) are mapped to %s, which is not installed on this machine'
                              % (len(apps), name), 'luna proton install %s' % name))
    return found
# --------------------------------------------------------------------------- games
# `luna games`: which Steam games are installed on which machine, and queueing
# installs on another one. Strictly read-only locally; `install` only asks the
# REMOTE Steam to install (steam://install/<appid>), it never copies game
# files. Unlock-only games (SLSsteam/Lumen: config/stplug-in/<appid>.lua) can
# only be installed where that lua exists, so the diff reports that per game.

GAMES_TOOL_RE = re.compile(r'^(Proton\b|Steam Linux Runtime|Steamworks Common Redistributables|SteamVR\b)')
GAMES_INSTALLED_FLAG = 4  # StateFlags bit: fully installed
GAMES_FREE_MARGIN = 0     # bytes kept free on top of the game size (none: Steam does its own check)


def games_libraries():
    """steamapps directories of this machine: the default one plus libraryfolders.vdf entries."""
    base = steam_home() / 'steamapps'
    found = [base]
    try:
        data = parse_vdf((base / 'libraryfolders.vdf').read_text(errors='replace'))
    except OSError:
        data = {}
    folders = data.get('libraryfolders') or data.get('LibraryFolders') or {}
    for key in sorted(folders, key=lambda k: (not str(k).isdigit(), int(k) if str(k).isdigit() else 0, str(k))):
        entry = folders[key]
        path = entry.get('path') if isinstance(entry, dict) else (entry if isinstance(entry, str) and
                                                                  not str(key).isalpha() else None)
        if path:
            found.append(Path(path) / 'steamapps')
    result = []
    seen = set()
    for item in found:
        try:
            marker = str(item.resolve())
        except OSError:
            marker = str(item)
        if marker not in seen and item.is_dir():
            seen.add(marker)
            result.append(item)
    return result


def games_lua_ids():
    """appids that have a stplug-in lua on this machine."""
    folder = steam_home() / 'config/stplug-in'
    ids = set()
    try:
        for entry in folder.iterdir():
            if entry.suffix == '.lua' and entry.stem.isdigit():
                ids.add(int(entry.stem))
    except OSError:
        pass
    return ids


def games_parse_manifest(path):
    """Installed-game record from an appmanifest_N.acf, or None (tool, partial, unreadable)."""
    try:
        state = parse_vdf(path.read_text(errors='replace')).get('AppState')
    except OSError:
        return None
    if not isinstance(state, dict) or not str(state.get('appid', '')).isdigit():
        return None
    try:
        flags = int(state.get('StateFlags') or 0)
        size = int(state.get('SizeOnDisk') or 0)
    except ValueError:
        flags, size = 0, 0
    name = str(state.get('name') or state.get('installdir') or state['appid'])
    if not flags & GAMES_INSTALLED_FLAG or GAMES_TOOL_RE.match(name):
        return None
    return {'id': int(state['appid']), 'name': name, 'size': size}


def games_scan_local():
    """{'items': {appid: record}, 'lua': set, 'free': bytes, 'libraries': [...]} for this machine."""
    libraries = games_libraries()
    lua = games_lua_ids()
    items = {}
    for library in libraries:
        for manifest in sorted(library.glob('appmanifest_*.acf')):
            record = games_parse_manifest(manifest)
            if record is None or record['id'] in items:
                continue
            record['lib'] = str(library.parent)
            record['pfx'] = (library / 'compatdata' / str(record['id'])).is_dir()
            record['lua'] = record['id'] in lua
            items[record['id']] = record
    free = 0
    if libraries:
        try:
            free = shutil.disk_usage(str(libraries[0])).free
        except OSError:
            pass
    return {'items': items, 'lua': lua, 'free': free, 'libraries': [str(p.parent) for p in libraries]}


def games_probe_block():
    """Compact, additive `games` section of `luna probe --json`."""
    scan = games_scan_local()
    return {'items': [[g['id'], g['name'], g['size'], int(g['lua'])] for g in
                      sorted(scan['items'].values(), key=lambda g: g['id'])],
            'lua': sorted(scan['lua']), 'free': scan['free']}


def games_from_probe(block):
    """Inverse of games_probe_block (remote side); None when the block is malformed."""
    try:
        items = {}
        for appid, name, size, lua in block['items']:
            items[int(appid)] = {'id': int(appid), 'name': str(name), 'size': int(size),
                                 'lib': '', 'pfx': None, 'lua': bool(lua)}
        return {'items': items, 'lua': {int(x) for x in block['lua']}, 'free': int(block['free'])}
    except (KeyError, TypeError, ValueError):
        return None


# Remote scan for hosts whose installed Luna has no games probe: plain bash/sed,
# no Python needed. Tab-separated, name last.
GAMES_REMOTE_SCRIPT = r'''
S="$HOME/.local/share/Steam"; [ -d "$S" ] || S="$HOME/.steam/steam"
if [ -f "$HOME/.local/share/Lumen/sls-luna/luna.py" ]; then
  out=$(python3 "$HOME/.local/share/Lumen/sls-luna/luna.py" probe --json 2>/dev/null)
  case "$out" in *'"games"'*) echo "PROBE $out";; *) out="";; esac
fi
if [ -z "$out" ]; then
  libs="$S"
  for p in $(sed -n 's/^[[:space:]]*"path"[[:space:]]*"\(.*\)".*/\1/p' "$S/steamapps/libraryfolders.vdf" 2>/dev/null | tr ' ' '\001'); do
    libs="$libs
$(printf '%s' "$p" | tr '\001' ' ')"
  done
  printf '%s\n' "$libs" | awk 'NF && !seen[$0]++' | while IFS= read -r lib; do
    [ -d "$lib/steamapps" ] || continue
    [ "$lib" = "$S" ] && printf 'FREE\t%s\n' "$(df -B1 --output=avail "$lib/steamapps" | tail -1 | tr -d ' ')"
    for f in "$lib"/steamapps/appmanifest_*.acf; do
      [ -f "$f" ] || continue
      id=$(sed -n 's/^[[:space:]]*"appid"[[:space:]]*"\([0-9]*\)".*/\1/p' "$f" | head -1)
      sz=$(sed -n 's/^[[:space:]]*"SizeOnDisk"[[:space:]]*"\([0-9]*\)".*/\1/p' "$f" | head -1)
      fl=$(sed -n 's/^[[:space:]]*"StateFlags"[[:space:]]*"\([0-9]*\)".*/\1/p' "$f" | head -1)
      nm=$(sed -n 's/^[[:space:]]*"name"[[:space:]]*"\(.*\)".*/\1/p' "$f" | head -1)
      pf=0; [ -d "$lib/steamapps/compatdata/$id" ] && pf=1
      printf 'APP\t%s\t%s\t%s\t%s\t%s\n' "$id" "${sz:-0}" "${fl:-0}" "$pf" "$nm"
    done
  done
  printf 'LUA\t%s\n' "$(ls "$S/config/stplug-in" 2>/dev/null | sed -n 's/^\([0-9][0-9]*\)\.lua$/\1/p' | tr '\n' ' ')"
fi
uid="$(id -u)"; s=0
pgrep -u "$uid" -x steam >/dev/null && s=1
pgrep -u "$uid" -x steamwebhelper >/dev/null && s=1
echo "STEAMRUN $s"
'''


def games_parse_remote(code, out, err):
    """Remote record {'reachable', 'items', 'lua', 'free', 'steamRunning'} from GAMES_REMOTE_SCRIPT output."""
    if code == 255:
        return {'reachable': False, 'error': (err.strip().splitlines() or ['ssh failed'])[-1]}
    record = {'reachable': True, 'items': {}, 'lua': set(), 'free': 0, 'steamRunning': False}
    for line in out.splitlines():
        if line.startswith('STEAMRUN '):
            record['steamRunning'] = line.split()[1] == '1'
        elif line.startswith('PROBE '):
            try:
                parsed = games_from_probe(json.loads(line[6:]).get('games'))
            except (ValueError, AttributeError):
                parsed = None
            if parsed:
                record.update(parsed)
        else:
            parts = line.split('\t')
            if parts[0] == 'FREE' and len(parts) > 1 and parts[1].isdigit():
                record['free'] = int(parts[1])
            elif parts[0] == 'LUA' and len(parts) > 1:
                record['lua'] = {int(x) for x in parts[1].split() if x.isdigit()}
            elif parts[0] == 'APP' and len(parts) >= 6 and parts[1].isdigit():
                try:
                    flags, size = int(parts[3] or 0), int(parts[2] or 0)
                except ValueError:
                    continue
                name = _vdf_unescape(parts[5]) or parts[1]
                if flags & GAMES_INSTALLED_FLAG and not GAMES_TOOL_RE.match(name):
                    record['items'].setdefault(int(parts[1]), {
                        'id': int(parts[1]), 'name': name, 'size': size, 'lib': '',
                        'pfx': parts[4] == '1', 'lua': None})
    for appid, game in record['items'].items():
        if game['lua'] is None:
            game['lua'] = appid in record['lua']
    return record


def games_collect_remote(host):
    code, out, err = fleet_ssh(host, GAMES_REMOTE_SCRIPT, timeout=60)
    record = games_parse_remote(code, out, err)
    record['host'] = host
    return record


def games_diff(local, remote):
    """Per-game comparison of this machine (local) against a target record."""
    rows = []
    free = remote.get('free', 0)
    for appid in sorted(set(local['items']) | set(remote['items'])):
        here, there = local['items'].get(appid), remote['items'].get(appid)
        row = {'appid': appid, 'name': (here or there)['name'],
               'localSize': here['size'] if here else None,
               'remoteSize': there['size'] if there else None,
               'where': 'both' if here and there else ('local' if here else 'remote')}
        if here and not there:
            unlock_only = bool(here['lua'])
            row['unlockOnly'] = unlock_only
            row['luaOnTarget'] = appid in remote['lua']
            row['blocked'] = unlock_only and not row['luaOnTarget']
            row['fits'] = here['size'] + GAMES_FREE_MARGIN <= free
        rows.append(row)
    missing = [r for r in rows if r['where'] == 'local']
    return {'games': rows,
            'summary': {'both': sum(r['where'] == 'both' for r in rows),
                        'missingOnTarget': len(missing),
                        'missingBytes': sum(r['localSize'] for r in missing),
                        'blocked': sum(r['blocked'] for r in missing),
                        'tooBig': sum(not r['fits'] for r in missing),
                        'allFit': sum(r['localSize'] for r in missing) <= free,
                        'targetOnly': sum(r['where'] == 'remote' for r in rows),
                        'targetFree': free}}


def games_gb(value):
    return '%.1f' % (value / 1e9) if value is not None else '-'


def games_resolve_host(options):
    host = getattr(options, 'host', None) or (fleet_load_hosts() or [None])[0]
    if not host:
        print('no host: luna games diff HOST (or luna fleet add HOST)', file=sys.stderr)
        return None
    if not fleet_valid_host(host):
        print('REFUSING: %r is not a plain hostname' % host, file=sys.stderr)
        return None
    return host


def games_list(options):
    scan = games_scan_local()
    games = sorted(scan['items'].values(), key=lambda g: g['name'].lower())
    if options.json:
        print(json.dumps({'games': games, 'libraries': scan['libraries'], 'free': scan['free']}, sort_keys=True))
        return EXIT_OK
    print('%-9s %-44s %8s  %-4s %-6s %s' % ('APPID', 'NAME', 'GB', 'PFX', 'UNLOCK', 'LIBRARY'))
    for game in games:
        print('%-9d %-44s %8s  %-4s %-6s %s' % (game['id'], game['name'][:44], games_gb(game['size']),
                                                'yes' if game['pfx'] else '-', 'yes' if game['lua'] else 'no',
                                                game['lib']))
    print('%d game(s), %s GB; %s GB free in the default library' % (
        len(games), games_gb(sum(g['size'] for g in games)), games_gb(scan['free'])))
    return EXIT_OK


def games_diff_cmd(options):
    host = games_resolve_host(options)
    if host is None:
        return EXIT_REFUSED
    remote = games_collect_remote(host)
    if not remote['reachable']:
        print('%s: unreachable (%s)' % (host, remote.get('error', '?')), file=sys.stderr)
        return 1
    result = games_diff(games_scan_local(), remote)
    result['host'] = host
    if options.json:
        print(json.dumps(result, sort_keys=True))
        return EXIT_OK
    summary = result['summary']
    print('%-9s %-40s %8s  %s' % ('APPID', 'NAME (missing on %s)' % host, 'GB', 'STATUS'))
    for row in sorted((r for r in result['games'] if r['where'] == 'local'),
                      key=lambda r: -r['localSize']):
        status = 'ok'
        if row['blocked']:
            status = 'BLOCKED: no stplug-in lua on target'
        elif not row['fits']:
            status = 'does not fit'
        elif row['unlockOnly']:
            status = 'ok (unlock-only, lua present)'
        print('%-9d %-40s %8s  %s' % (row['appid'], row['name'][:40], games_gb(row['localSize']), status))
    print('both: %d | missing on %s: %d (%s GB; %d blocked by missing lua, %d too big alone%s) | '
          'only on %s: %d | %s GB free there' % (
              summary['both'], host, summary['missingOnTarget'], games_gb(summary['missingBytes']),
              summary['blocked'], summary['tooBig'], '' if summary['allFit'] else '; not all fit together',
              host, summary['targetOnly'], games_gb(summary['targetFree'])))
    return EXIT_OK


def games_install_cmd(options):
    host = games_resolve_host(options)
    if host is None:
        return EXIT_REFUSED
    appids = []
    for raw in options.appids:
        if not str(raw).isdigit():
            print('REFUSING: %r is not a numeric appid' % raw, file=sys.stderr)
            return EXIT_REFUSED
        if int(raw) not in appids:
            appids.append(int(raw))
    local = games_scan_local()
    remote = games_collect_remote(host)
    if not remote['reachable']:
        print('%s: unreachable (%s)' % (host, remote.get('error', '?')), file=sys.stderr)
        return 1
    queue, refused, needed = [], [], 0
    for appid in appids:
        here = local['items'].get(appid)
        name = (here or {}).get('name') or str(appid)
        if appid in remote['items']:
            print('%s (%d): already installed on %s, skipping' % (name, appid, host))
        elif (here and here['lua']) and appid not in remote['lua']:
            refused.append('%s (%d): unlock-only and %s has no stplug-in/%d.lua (sync it first)' % (
                name, appid, host, appid))
        elif here is None and appid not in remote['lua']:
            # Not installed here, so ownership/unlock state is unknown: let Steam on the target decide.
            queue.append((appid, name, None))
        elif here is not None and needed + here['size'] > remote['free']:
            refused.append('%s (%d): needs %s GB, only %s GB free on %s' % (
                name, appid, games_gb(here['size']), games_gb(max(remote['free'] - needed, 0)), host))
        else:
            needed += here['size'] if here else 0
            queue.append((appid, name, here['size'] if here else None))
    for line in refused:
        print('REFUSING ' + line, file=sys.stderr)
    for appid, name, size in queue:
        print('%s %s (%d) on %s%s' % ('would install' if options.dry_run else 'installing', name, appid, host,
                                      ' [%s GB]' % games_gb(size) if size else ' [size unknown]'))
    if options.dry_run or not queue:
        return EXIT_REFUSED if refused and not queue else EXIT_OK
    if not remote['steamRunning']:
        if not options.start_steam:
            print('REFUSING: Steam is not running on %s (start it there, or pass --start-steam)' % host,
                  file=sys.stderr)
            return EXIT_REFUSED
        code, _, err = fleet_ssh(host, FLEET_START_STEAM_SCRIPT, timeout=30)
        if code != 0:
            print('%s: could not start Steam: %s' % (host, err.strip()), file=sys.stderr)
            return 1
        print('started Steam on %s; give it a moment to load before the installs are picked up' % host)
    failed = False
    for appid, name, _ in queue:
        # ssh has no graphical session env: run inside the user's systemd manager (it has it), so the
        # steam:// URL is handed to the running Steam instance.
        script = ('[ -n "$XDG_RUNTIME_DIR" ] || export XDG_RUNTIME_DIR="/run/user/$(id -u)"\n'
                  '[ -n "$DBUS_SESSION_BUS_ADDRESS" ] || export DBUS_SESSION_BUS_ADDRESS="unix:path=$XDG_RUNTIME_DIR/bus"\n'
                  'systemd-run --user --quiet --collect steam steam://install/%d >/dev/null 2>&1\n' % appid)
        code, _, err = fleet_ssh(host, script, timeout=60)
        print('%-9d %s %s' % (appid, 'queued' if code == 0 else 'FAIL', name if code == 0 else err.strip()))
        failed = failed or code != 0
    return 1 if failed or refused else EXIT_OK


def cmd_games(options):
    action = options.games_action
    rest = list(getattr(options, 'games_args', None) or [])
    options.host = rest[0] if rest and action in ('diff', 'install') else None
    options.appids = rest[1:] if action == 'install' else []
    if action == 'install' and (not options.host or not options.appids):
        print('usage: luna games install HOST APPID... [--dry-run] [--start-steam]', file=sys.stderr)
        return EXIT_REFUSED
    if action in ('list', 'diff') and len(rest) > (1 if action == 'diff' else 0):
        print('usage: luna games list | luna games diff [HOST]', file=sys.stderr)
        return EXIT_REFUSED
    if action == 'list':
        return games_list(options)
    if action == 'diff':
        return games_diff_cmd(options)
    return games_install_cmd(options)
